pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Aggressive 2-step lookahead: reward bins where next item fits perfectly after this one.
    if next_item_size > 0 {
        let lookahead_gap = post_residual as i64 - next_item_size as i64;
        if lookahead_gap == 0 {
            // Perfect 2-item packing: strongly favor this bin.
            score -= 80.0;
        } else if lookahead_gap > 0 {
            // Next item fits with slack; reward proportionally to tightness.
            let tight = 1.0 - lookahead_gap as f64 / bin_capacity as f64;
            score -= 40.0 * tight;
            if (lookahead_gap as u32) < 10 {
                score -= 15.0; // near-perfect chain
            }
        } else {
            // Next item won't fit after this placement; mild penalty scaled by overflow.
            score += (lookahead_gap.abs() as f64).min(50.0) * 0.5;
        }
        // Reward if post_residual is closest to next_item_size relative to mean residual.
        let dist = (post_residual as f64 - next_item_size as f64).abs();
        let mean_dist = (mean_residual - next_item_size as f64).abs();
        if mean_dist > 1e-9 {
            score -= 20.0 * (1.0 - (dist / mean_dist).min(1.0));
        }
    } else {
        // Last item: just minimize post residual, already done by base score.
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Prefer fuller bins relative to mean residual (best-fit flavor).
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Early in the stream, allow opening fresh bins slightly more readily;
    // late in the stream, squeeze every open bin harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses so we reuse bins late.
        score += 30.0 + 40.0 * progress;
        if next_item_size > 0 && bin_capacity as f64 - next_item_size as f64 >= item_size as f64 {
            // New bin can host a perfect 2-chain with next item; discount penalty.
            score -= 25.0;
        }
    }

    // Slight penalty for proliferating many open bins early.
    if open_bins_count > 8 && progress < 0.5 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..~20)
    // are effectively unusable; penalize them super-linearly.
    let dead_threshold = 20.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * (dead_threshold - post_residual as f64) * 2.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score -= (1.0 - fit_ratio.min(1.0)) * 15.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
        if next_item_size == post_residual {
            score -= 30.0;
        }
    } else if next_item_size > post_residual {
        // Post-residual too small for next item: mild penalty scaled by how close.
        score += 5.0;
    }

    // Open-bin pressure: discourage spreading across many bins when alternatives exist.
    if fitting_bins_count > 1 {
        score += (open_bins_count as f64) * 0.5;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer new bin only when existing fits are terrible.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced late in the stream.
        score = 60.0 + (open_bins_count as f64) * 0.3;
        // If nothing fits well (large dead space would be created elsewhere), new bin is attractive.
        if (post_residual as f64) >= 0.0 && (bin_residual as f64) - (item_size as f64) >= dead_threshold {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
    }

    // Slight mean-residual coupling: prefer bins whose residual is below mean (tighter bins).
    score += ((mean_residual - bin_residual as f64) * 0.1).clamp(-5.0, 5.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Dead space = residual too small to ever fit any item (min item size 1 here,
        // so treat "very small" gaps as low-utility: <= 10 nearly unusable).
        if post_residual <= 10 {
            score += 60.0; // hard penalty for creating near-dead space
        } else if post_residual <= 25 {
            score += 25.0 * (1.0 - (post_residual as f64 - 10.0) / 15.0);
        } else {
            // Larger gaps are progressively less penalized (still usable).
            score -= 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward bins whose residual is being well matched to the item (tight fit).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize new bins implicitly via this bin's score being lowered).
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score -= 20.0 * pressure * (item_size as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover: mild penalty for stranded space.
        score += 10.0;
    }

    // Early stream: keep bins flexible (favor larger residuals slightly);
    // late stream: pack tightly, accept imperfect fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 10.0 * (post_residual as f64 / bin_capacity as f64);
    score -= progress * 12.0;

    // Prefer bins below mean residual (i.e., emptier-than-average bins get used,
    // keeping tight bins for smaller future items) when many bins are open.
    if (bin_residual as f64) > mean_residual {
        score += 6.0;
    } else {
        score -= 6.0;
    }

    // New-bin candidate calibration: an empty bin gets a mild penalty so it is
    // only chosen when all open-bin scores are worse (poor fits / dead space).
    if bin_residual == bin_capacity {
        score += 18.0 - 10.0 * pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful later
    // are heavily penalized. Define "unusable" as post_residual < 10 (min item)
    // or post_residual smaller than the next item's size.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(10) {
        score += 25.0; // tiny dead gap
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // gap cannot host the lookahead item: penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.6;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // gap can host the next item: reward
        score -= (next_item_size as f64) * 0.3;
    }

    // Perfect or near-perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    } else {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 15.0; // reward tight packing
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // alternatives exist; encourage consolidation.
    if bin_residual < bin_capacity {
        score += (open_bins_count as f64) * 1.5;
    }

    // Mean residual coupling: prefer bins with residual below mean
    // (denser bins first), above-mean bins get a mild penalty.
    let resid_f = bin_residual as f64;
    if resid_f > mean_residual {
        score += (resid_f - mean_residual) * 0.2;
    } else {
        score -= (mean_residual - resid_f) * 0.2;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit
    // (i.e., this call is the empty-bin candidate and fits are scarce).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            score += 20.0; // last-chance bin should win instead
        } else {
            score += 8.0; // plenty of options; keep item in an open bin
        }
    }

    // Late in the stream: consolidate harder to avoid many half-empty bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr_norm = pr / cap; // 0..1 normalized post residual
    let pr2 = pr_norm * pr_norm;
    let pr3 = pr2 * pr_norm;
    // Early in the stream: tolerate large residuals slightly less (keep bins flexible);
    // late in the stream: strongly prefer small post residuals (tight packing).
    let w_early = (1.0 - progress) * (1.0 - progress);
    let w_late = progress * progress;
    score += 8.0 * w_late * pr2 * cap;
    score -= 6.0 * w_early * pr2 * cap;
    // Smooth cubic interaction: reward very tight fits more as stream progresses.
    score -= 10.0 * progress * pr3 * cap;

    // Dead-space penalty: post residual that cannot fit the next item is wasted.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let unusable = ((nx - pr) / cap).max(0.0);
        let unusable2 = unusable * unusable;
        score += 12.0 * unusable2 * cap * (0.5 + 0.5 * progress);
        // Smooth bonus if post residual is a near-perfect cradle for the next item.
        let fit_gap = (pr - nx).abs() / cap;
        score -= 5.0 * (1.0 - fit_gap) * (1.0 - fit_gap) * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    } else if fitting_bins_count > 2 {
        // Many alternatives: mildly penalize to prefer best-fit discrimination.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Coupling with mean residual: prefer bins whose post residual stays near the mean
    // early (balance flexibility), but deviate toward tight fits late.
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * cap * (1.0 - progress);
    score -= 2.0 * dev.abs() * progress;

    // Mild penalty on spreading across many bins early (encourage consolidation).
    score += 0.4 * open_bins_count as f64 * (1.0 - progress) * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps that are too small to be useful later are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // --- Reward bins that can still host the lookahead item ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Bonus if post_residual is a tight wrap around next item.
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 8.0;
            }
        } else {
            score += 6.0;
        }
    }

    // --- Open bins pressure: discourage hoarding many open bins ---
    score += 1.5 * open_bins_count as f64;

    // --- Last-chance bin: strongly favor using it before opening a new one ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive for large items / many open bins,
        // but discouraged when a decent existing fit exists.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 45.0 + 0.8 * open_bins_count as f64 - 10.0 * progress;
        if item_size >= 60 {
            score -= 15.0;
        }
        if fitting_bins_count > 0 && post_residual >= 15 {
            score += 20.0; // keep using existing bins when fit isn't terrible
        }
    }

    // --- Mean residual coupling: prefer bins below mean residual (tighter bins) ---
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual was close to item size.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Lookahead: if the next item fits into this bin's post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let pressure = mean_residual / bin_capacity as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * pressure * (0.5 + t);
        score += 2.0 * open_bins_count as f64 * (1.0 - t);
    } else {
        // New-bin candidate: attractive only when mean residual is low or stream is early.
        score += 15.0 * pressure;
        score -= 8.0 * (1.0 - t);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0 * (1.0 - next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Mild preference for more-full bins overall.
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Exact fit: perfect closure, strong reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Harmonic classes of post_residual: dead space classes by integer division.
    let pr = post_residual as f64;
    // Class thresholds: residual <= 10 is a "usable sliver" (next items min size 1... but keep generic).
    if post_residual > 0 && post_residual <= 10 {
        score -= 40.0; // small leftovers are fine, near-closed bins
    } else {
        // Penalize awkward mid-range residuals that few future items can fill.
        let half = post_residual / 2;
        // Modulo-style coupling: does post_residual divide nicely into plausible item chunks?
        let chunk = if post_residual >= 50 { 25 } else if post_residual >= 34 { 17 } else { 10 };
        if post_residual % chunk == 0 {
            score -= 15.0; // splittable residual, likely reusable
        } else {
            score += 10.0 + 0.5 * (half as f64 % 7.0); // odd dead-space penalty
        }
    }

    // Lookahead: reward bins where the next item also fits in the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0;
        // Bonus if next item nearly closes the bin after this placement.
        if post_residual - next_item_size <= 5 {
            score -= 30.0;
        }
    } else if next_item_size > 0 && next_item_size > bin_residual && next_item_size <= post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; mildly penalize leaving large unusable gap.
        score += 0.3 * pr;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a bin should only win when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 150.0 - 30.0 * progress;
        // If many bins can fit, discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 50.0 * (fitting_bins_count as f64).min(3.0);
        }
        // If this is a large item and mean residual is small, new bin is attractive.
        if item_size as f64 > mean_residual + 20.0 {
            score -= 100.0;
        }
        // Exact half-ish items into a fresh bin are fine.
        if item_size * 2 >= bin_capacity {
            score -= 40.0;
        }
    }

    // Prefer tightest bins overall: closeness of item to residual (best-fit core).
    score += (bin_residual - item_size) as f64 * 0.2;

    // Mild penalty for spreading across too many open bins when residuals are large.
    if open_bins_count > 3 && mean_residual > 40.0 && post_residual > 30 {
        score += 5.0;
    }

    score
}

