        let open_pressure = if open_bins_count > 0 { mean_residual } else { 0.0 };
        if open_pressure < item_size as f64 * 0.5 {
            score -= 80.0; // open bins are too full, new bin is fine
        } else {
            score += 150.0; // discourage opening when open bins have room
        }
    }

    // Slight early-stream bias toward filling bins greedily
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=9) are almost useless for future
    // items (min size 10 in classic regime, but sizes 1..100 possible) — penalize
    // heavily when the gap falls into the "dead zone" below the smallest plausible
    // useful leftover.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0 + 6.0 * (10 - post_residual) as f64; // tiny unusable slivers
    } else if post_residual > 9 && post_residual <= 20 {
        score += 12.0; // marginal gap, mildly wasteful
    }

    // Reward near-perfect fills strongly (sub-linear so 0 residual dominates).
    if post_residual == 0 {
        score -= 100.0;
    } else {
        score -= 40.0 * (1.0 - pr / bin_capacity as f64).powf(3.0);
    }

    // Tightness relative to residual: prefer bins where item consumes most of the gap.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * fit_ratio;
    }

    // Open-bins pressure: many open bins -> discourage spreading, favor consolidating
    // into existing bins; few open bins -> new bins are cheap.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 4.0 * pressure * (1.0 - fit_ratio);

    // New-bin candidate: only attractive when residuals across open bins are large
    // (item fits poorly everywhere) or no open bin fits well.
    if bin_residual == bin_capacity {
        let mean_fit = item_size as f64 / mean_residual.max(1.0);
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { (fitting_bins_count as f64).recip() };
        let poor_elsewhere = ((mean_fit - 1.0).max(0.0)) * 40.0;
        let early_discount = 1.0 - (step_index as f64 / (total_items.max(1) as f64)).min(1.0) * 0.3;
        score = 55.0 + 20.0 * scarcity - poor_elsewhere * early_discount;
        // Never open a new bin if a perfect or near-perfect fit exists.
        if fit_ratio > 0.95 { score += 200.0; }
    }

    // Lookahead: if next item would fit exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
