            score += (post_residual as f64 - next_item_size as f64).abs() * 0.1;
        }
    }

    // Time horizon: late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate logic: only attractive when this bin is empty and
