        score -= 80.0;
        if post_residual == next_item_size {
            score -= 300.0; // next item will close the bin completely
        }
    }

    // Penalize leaving a residual that is small enough to be "dead space"
    // (no plausible item of size 1..100 can use it well): residual < 10 means
    // nothing else fits, but we already covered 0; residual 1..=9 is waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Penalize residuals that are large but not large enough for the next item:
    // creates fragmentation relative to the lookahead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Compare against mean residual across open bins: prefer bins whose
    // residual is already below average (denser bins), keep fat bins flexible.
    let residual_f = bin_residual as f64;
    if residual_f > mean_residual {
        score += 0.3 * (residual_f - mean_residual);
    } else {
        score -= 0.1 * (mean_residual - residual_f);
    }

    // Last-chance bin: if this is the only bin that can fit the item, use it
    // rather than opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless no good
    // placement exists. Base penalty grows with number of open bins.
    if bin_residual == bin_capacity {
        score += 250.0 + 15.0 * open_bins_count as f64;
        // Exception: if the next item also fits perfectly after this one in a
        // fresh bin and current fits are poor, fresh start is fine — soften a bit.
        if next_item_size == 0 {
            score += 100.0; // no lookahead value in a fresh bin at stream end
        }
    }

    // Late in the stream, closing bins tightly matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * fit_ratio * 40.0;

    // Lookahead: if next item fits in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
            // Extra reward if next item also fits tightly afterwards.
            let next_post = post_residual - next_item_size;
            score -= (next_post as f64).min(20.0) * 0.5;
        } else {
            // Next item won't fit here; small penalty proportional to wasted potential.
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    }

    // Penalize leaving very small dead space that nothing (min size 1) can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Time horizon: early in stream, be conservative (favor filling existing bins);
    // late in stream, prefer tight fits even more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= fit_ratio * progress * 20.0;

    // New-bin candidate handling: penalize opening a new bin unless it's a good idea.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 30.0;
        // If few bins fit, opening may be justified — reduce penalty.
        if fitting_bins_count == 0 {
            score -= 45.0;
        } else if fitting_bins_count == 1 {
            score -= 15.0;
        }
        // Large items (>= half capacity) are fine to start a fresh bin.
        if item_size * 2 >= bin_capacity {
            score -= 20.0;
        }
        // Many open bins with high mean residual: avoid opening more.
        if open_bins_count > 3 && mean_residual > 40.0 {
            score += 25.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid fragmentation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mild penalty for bins with much larger residual than the mean (keep uniform bins).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Normalized post-residual, non-linearly coupled with stream progress:
    // late in the stream, wasted space matters more (quadratic ramp).
    let waste_norm = pr / cap;
    score += 30.0 * waste_norm * waste_norm * (0.5 + progress);

    // Perfect-fit reward: strong smooth bonus as post_residual approaches 0.
    score -= 25.0 * (1.0 - waste_norm).max(0.0) * (1.0 - waste_norm).max(0.0);

    // Lookahead coupling: reward leaving room for the next item,
    // penalize residuals that nearly-but-not-quite fit the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            score -= 12.0 * (1.0 - slack / cap) * (0.5 + progress);
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0 + 20.0 * progress;
    } else if fitting_bins_count > 1 {
        // mild congestion penalty scaled by number of competing bins
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (tighter bins first), smooth logistic-style preference.
    let diff = (mean_residual - bin_residual as f64) / cap;
    score += 15.0 * diff / (1.0 + (-4.0 * diff).abs());

    // New-bin candidate: penalize opening a new bin, more so early in the
    // stream and when many bins are already open; relax late in the stream.
    if bin_residual == bin_capacity {
        score += 35.0 * (1.0 - progress) + 5.0 * (open_bins_count as f64).sqrt();
    }

    // Small smooth fill-encouragement term for large items.
    score -= 6.0 * (it / cap) * (1.0 - waste_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: reward heavily.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of the leftover space: classify post_residual by
    // capacity fractions. Small leftovers are "usable dead space" only
    // if the next item (or typical small items) can fill them.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let next_f = next_item_size as f64;

    // Fraction of capacity left over.
    let frac = post_f / cap_f;

    // Penalize leftover by its class:
    // class 0: <= 1/8 of capacity -> nearly dead space, strong penalty
    // class 1: <= 1/4 -> moderate penalty
    // class 2: <= 1/2 -> mild
    // class 3: > 1/2 -> still roomy, mild
    if frac <= 0.125 {
        score += 60.0;
    } else if frac <= 0.25 {
        score += 25.0;
    } else if frac <= 0.5 {
        score += 10.0;
    } else {
        score += 5.0;
    }

    // Reward bins whose leftover can exactly host the next item (perfect chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    }
    // Reward if next item fits into the leftover (good continuation).
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
        // Extra reward when the next item would then leave a tiny remainder
        // again (double-chain potential).
        let second_left = post_residual - next_item_size;
        if second_left <= 10 {
            score -= 15.0;
        }
    }
    // Penalize if next item cannot use this leftover at all: dead space risk.
    else if next_item_size > 0 && next_item_size > post_residual {
        score += 12.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when existing fits are poor, otherwise keep open bins
    // preferred so space gets consolidated.
    if bin_residual == bin_capacity {
        // Base mild penalty so we prefer filling existing bins with decent fits.
        score += 30.0;
        // But if many bins are open and mean residual is small (fragmented),
        // a fresh bin is fine.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        if open_bins_count > 0 && mean_residual < 0.15 * cap_f {
            score -= 25.0;
        }
        // If the next item is large and current leftovers are all too small,
        // opening fresh space is wise.
        if next_item_size > 0 && next_f > mean_residual {
            score -= 15.0;
        }
    }

    // Slight preference for tighter existing bins when many bins compete:
    // normalize by how many alternatives exist.
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Small tie-breaker toward bins with residual close in size to the item
    // (minimize wasted fraction).
    let waste_ratio = post_f / (bin_residual as f64).max(1.0);
    score += 20.0 * waste_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small
    // to be useful for future items (assume min item size ~1, but gaps
    // below a "usable threshold" are nearly dead).
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 12.0; // hard penalty on tiny gaps
    }

    // Non-linear dead-space curve: quadratic growth of waste for mid residuals
    // that are unlikely to host a typical next item.
    let pr = post_residual as f64;
    if next_item_size > 0 {
        if (next_item_size as f64) > pr {
            // This bin's leftover can't fit the lookahead item -> extra penalty.
            score += 8.0 + (pr / 10.0);
        } else {
            // Reward bins whose leftover exactly accommodates the lookahead item.
            score -= 10.0;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins; encourage
    // filling existing bins when many are open.
    score += (open_bins_count as f64) * (pr / bin_capacity as f64) * 3.0;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first).
    score += (mean_residual - pr) * 0.5;

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    // Make it attractive only when the item is large relative to capacity
    // or when open bins are numerous and residuals are fragmented.
    if bin_residual == bin_capacity {
        let item_ratio = item_size as f64 / bin_capacity as f64;
        // Large items fit well in fresh bins; small items should use open bins.
        score += (1.0 - item_ratio) * 60.0;
        score += (open_bins_count as f64).sqrt() * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: this bin's post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item leaves only a tiny sliver.
    else if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if gap <= 5.0 {
            score -= 25.0 - 4.0 * gap;
        } else if post_residual > next_item_size {
            // next item fits here with some slack left: mild reward scaled by slack
            score -= (8.0 - 0.15 * gap).max(0.0);
        }
    }

    // Penalize dead space: post_residual too small to be useful for typical items.
    if post_residual < 10 {
        score += 12.0;
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 0.6;
    }

    // Reward bins that are tighter than the fleet mean (packing dense bins together).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin gives a decent fit
    // (i.e., item would leave a small residual here anyway) or fleet is nearly empty.
    if bin_residual == bin_capacity {
        let best_open_penalty = if fitting_bins_count == 0 { 0.0 } else { 15.0 };
        // Opening a new bin leaves a full bin_residual; penalize unless item is large
        // (leaves small post_residual) or open bins are crowded.
        score += 10.0 + best_open_penalty - 0.1 * (item_size as f64 - 50.0);
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, prefer closing out existing bins over opening new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer fuller bins overall (small residual before placement).
    score += 0.1 * (bin_capacity - bin_residual) as f64 * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic discount for small post_residual.
    let t = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - t) * (1.0 - t);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Exact-fill of residual: item exactly matches bin space.
    if item_size == bin_residual {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many fitting bins: this placement is not scarce, mild penalty relative
    // to alternatives so the tightest bin still wins via other terms.
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Lookahead coupling: if the next item would fit exactly in post_residual,
    // reward heavily; if next item cannot fit post_residual but could fit
    // elsewhere, mild penalty for fragmenting.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    } else {
        // Last item: fill as much as possible.
        score -= 30.0;
    }

    // Global state: penalize opening a new bin when mean residual across open
    // bins is still large (plenty of collective room).
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        let pressure = mean_residual / bin_capacity as f64;
        score += 30.0 * pressure;
        score += 5.0 * (open_bins_count as f64).sqrt();
        // Early in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
        // If next item is huge and this bin is fresh, keep it fresh for it.
        if next_item_size > bin_capacity * 2 / 3 {
            score -= 35.0;
        }
    } else {
        // Reward using bins that are already below mean residual (balancing).
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        }
    }

    // Dead-space penalty: residual too small for the minimum plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let progress_curve = 0.5 + 0.5 * (progress * std::f64::consts::PI).sin();
    score -= progress_curve * prn * prn * cap * 0.35;

    // Tight-fit reward: small post_residual strongly favored, smoothed by cubic term
    let tight = 1.0 - prn;
    score -= tight * tight * tight * 8.0;

    // Penalize residuals too small to ever be useful (dead space), smooth ramp
    let dead = ((30.0 - pr) / 30.0).max(0.0);
    score += dead * dead * 12.0;

    // Lookahead coupling: reward if next item fits the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let snug = 1.0 - ((pr - nxt) / cap).min(1.0);
            score -= snug * snug * 10.0;
        } else {
            score += ((nxt - pr) / cap) * 6.0;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Discourage opening new bins when good open bins exist, more so early on
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (1.0 + open_bins_count as f64);
        score += 4.0 + 6.0 * scarcity * (1.0 - progress);
    }

    // Mild preference for bins deviating from mean residual (diversity of gaps)
    score += ((pr - mean_residual) / cap).abs() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small dead zones" (<=10, 11..=20) are rewarded; mid-range leftovers
    // (21..=50) are the classic wasteland and get penalized.
    let dead_zone = if post_residual <= 10 { -40.0 }
        else if post_residual <= 20 { -18.0 }
        else if post_residual <= 50 { 14.0 }
        else { 0.0 };
    score += dead_zone;

    // Integer-division threshold: post_residual / 10 class
    let class = (post_residual / 10) as f64;
    score += 1.5 * class * (1.0 - class / 10.0);

    // Modulo coupling: leftovers that are multiples of 5 or 10 pair well
    // with typical item sizes drawn from coarse grids.
    if post_residual % 10 == 0 { score -= 6.0; }
    else if post_residual % 5 == 0 { score -= 3.0; }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly reward; if next item cannot fit anywhere else, this bin matters.
    if next_item_size > 0 {
        if next_item_size == post_residual as u32 { score -= 30.0; }
        else if next_item_size < post_residual as u32 { score -= 8.0; }
        else { score += 6.0; }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 { score -= 25.0; }

    // New-bin candidate: only attractive when current bin would leave
    // a large, awkward residual or when bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let awkward = (post > 20.0 && post < 51.0) as f64 * 22.0;
        let crowding = (open_bins_count as f64 / (mean_residual / cap + 0.5)).min(4.0);
        score = cap as f64 - 12.0 - awkward - crowding * 2.0 - 20.0 * progress;
    }

    // Mild global pressure: prefer tighter bins when mean residual is high.
    score -= (mean_residual / cap) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for "dead space": residuals too small to hold any plausible item.
    // Items are 1..=100; treat residuals < 10 as near-unusable.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward tight fits: small but still usable leftover space.
    score -= 2.5 * (bin_capacity as f64 - post_residual as f64).sqrt();

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Pressure from number of open bins: when many bins are open,
    // prefer consolidating into existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // If the next item fits exactly into the post-residual, big reward (chained fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Mild reward if next item can still fit afterwards.
        score -= 4.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        // Next item cannot use this leftover and it is dead space: penalize.
        score += 12.0;
    }

    // New-bin candidate: only attractive when open bins have poor residuals
    // (mean residual very small, i.e. nothing useful left anywhere).
    if bin_residual == bin_capacity {
        if mean_residual < 8.0 {
            score -= 20.0;
        } else {
            score += 10.0 + 0.2 * mean_residual;
        }
    }

    // Prefer bins whose residual is close to the item (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with a slight superlinear penalty.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 30.0;

    // Aggressive 2-step lookahead: reward if next item exactly fills the post-residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt <= post {
            // Perfect chaining: next item fits exactly -> strong reward.
            let gap = (post - nxt).abs();
            if gap == 0.0 {
                score -= 25.0;
            } else {
                // Partial credit scaled by how well next item uses the leftover.
                score -= 15.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here; penalize dead space relative to next item.
            score += 0.25 * (post - nxt).abs();
        }
    } else {
        // Last item in stream: leftover space is worthless; minimize it hard.
        score += post_residual as f64 * 0.5;
    }

    // Compare post_residual against mean residual across open bins.
    // Leaving a bin far below the mean wastes capacity elsewhere.
    if mean_residual > 0.0 {
        let diff = post_residual as f64 - mean_residual;
        score += 0.15 * diff;
    }

    // Last-chance bin: if only this bin can fit the item, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, mild bonus so we don't open new bins unnecessarily.
        score -= 3.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are very full.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if mean residual is small (bins nearly full)
        // and the item is large.
        let pressure = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = bin_capacity as f64 + 40.0 - 35.0 * pressure
            - 0.3 * item_size as f64 * pressure;
    }

    // Late in the stream, tighten up: waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = post / cap;
    score -= 18.0 * (1.0 - 2.0 * fit_ratio).powi(2).min(1.0) * (1.0 - fit_ratio);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let chain_waste = post_residual - next_item_size as f64;
            score -= 8.0 * (1.0 - chain_waste / cap);
        } else {
            // Next item won't fit here; slight penalty proportional to gap.
            score += 0.05 * (next_item_size as f64 - post);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Penalize opening new bins when open bins exist and stream is early/mid.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more early on and when few bins open.
        score += 20.0 + 15.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // Allow new bin late in stream if mean residual is small (open bins nearly full).
        score -= 10.0 * (1.0 - mean_residual / cap).max(0.0) * progress;
    }

    // Mild preference for bins with residual close to mean (keeps balance),
    // but favor below-mean residuals (use fuller bins first).
    score += 0.03 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let item = item_size as f64;

    // Base: prefer tight fits, but weight dead space non-linearly.
    let mut score = pr * (1.0 + 0.8 * (pr / cap).powi(2));

    // Smooth stream-progress coupling: later in the stream, tolerate less slack.
    score *= 1.0 + 0.5 * progress * (pr / cap);

    // Reward near-full packing with a smooth quadratic bonus.
    let fill = 1.0 - (pr / cap);
    score -= 6.0 * fill * fill;

    // Penalize bins that leave a residual the next item cannot use smoothly.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.35 * gap * (1.0 - progress);
        if pr >= next_item_size as f64 {
            score -= 2.0 * (next_item_size as f64 / cap);
        }
    }

    // Last-chance bin: strong smooth reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 5.0 + 3.0 * progress;
    }

    // Mild pressure toward consolidating into fewer bins when many are open.
    score += 0.02 * open_bins_count as f64 * (1.0 - fill);

    // Deviation from mean residual: prefer bins below-mean slack for large items.
    score += 0.1 * (mean_residual - pr) * (item / cap);

    // New-bin candidate: penalize slightly so it only wins when open bins are poor.
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how it divides into capacity
    let pr = post_residual;
    let pr_frac = pr as f64 / cap;

    // Class bonus: residuals that are nice fractions of capacity (1/2, 1/3, 1/4)
    // are more likely reusable by future items -> subtract reward.
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;
    if pr == half {
        score -= 12.0;
    } else if pr == third {
        score -= 9.0;
    } else if pr == quarter {
        score -= 6.0;
    }

    // Integer-division thresholds: small dead space is bad, large is fine.
    if pr > 0 && pr < 10 {
        score += 15.0; // unusable sliver
    }

    // Lookahead harmonic coupling: if next item fits exactly into post_residual,
    // strongly reward; if next item is a divisor-class match (next <= pr but wastes > half), penalize.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            let waste = (pr - next_item_size) as f64;
            if waste > cap * 0.5 {
                score += 5.0;
            } else {
                score -= 4.0;
            }
        }
    }

    // Last-chance bin: avoid opening a new bin if this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when residuals across open bins are low
    // (mean residual small) or post_residual here would be a perfect fit class.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (mean_residual / cap).max(0.0);
        // Open new bin when open bins are nearly full (low mean residual)
        score = 30.0 + 60.0 * pressure - 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open
        }
    }

    // Mild tie-break: prefer tighter fits overall
    score += (bin_residual - item_size) as f64 * 0.01 * (1.0 - pr_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize opening a new bin when other bins fit (open-bin pressure).
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 + 25.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
    }

    // Last-chance bin: strongly favor using it to avoid waste.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 8.0;
    }

    // Mild preference for bins tighter than the current mean residual.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Open-bin count pressure: discourage proliferation of many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: this bin's leftover exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack * 1.5;
    }
    // Next item cannot use the leftover: penalize proportionally to dead space.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Tight fits are good: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 20.0 * tightness;

    // Compare against mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current bin fit is poor and
    // the item would leave a large, awkward residual.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 50.0 && next_item_size > 0 && post_residual >= next_item_size;
        if poor_fit {
            score -= 10.0; // fresh bin can host a future pairing
        } else {
            score += 30.0; // discourage opening new bins by default
        }
    }

    // Late in the stream: consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small dead space) nonlinearly.
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= 55.0 * tight * tight;

    // Penalize post_residual that is too small to hold any plausible future item
    // (items are 1..=100; residual < next item's need is dead space unless tiny).
    if post_residual > 0 {
        let usable = if next_item_size > 0 && post_residual >= next_item_size { 1.0 } else { 0.35 };
        score += 30.0 * (1.0 - usable);
    }

    // Lookahead: strong bonus if the next item exactly fills the post-residual
    // (perfect chain), mild bonus if it fits.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 70.0;
        } else if post_residual > next_item_size {
            score -= 18.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Time horizon: early in the stream, be pickier about wasting space;
    // late in the stream, just close bins out.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.6 * (1.0 - t);

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into existing bins over opening new ones.
    let crowd = open_bins_count as f64 / (1.0 + mean_residual / cap.max(1.0));
    score += 0.05 * crowd;

    // New-bin candidate handling: an empty bin has no sunk cost; only prefer it
    // when the item is large relative to capacity (would leave open bins cramped)
    // or when existing bins are very full (mean residual low).
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        let fullness = 1.0 - mean_residual / cap;
        let bonus = 90.0 * item_frac * item_frac + 60.0 * fullness * fullness - 25.0;
        score += bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = x * x * (3.0 - 2.0 * progress) + x * (1.0 + 2.0 * progress);

    // Dead-space penalty: small post residuals are wasted space
    let dead = (1.0 - x) * (1.0 - x);
    score += 4.0 * dead * (1.0 - progress);

    // Reward tight fits
    score -= (item_size as f64 / cap) * (1.0 - x) * 2.0;

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 3.0;
    }

    // Lookahead: favor leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let diff = x - nx;
        score -= 2.0 * (diff * diff).max(0.0).min(1.0) * (1.0 - diff.abs());
        if pr < next_item_size as f64 {
            score += 1.5 * (next_item_size as f64 - pr) / cap;
        }
    }

    // Prefer denser bins when many are open
    score -= (mean_residual - pr) / cap * 0.5;

    // New-bin candidate: penalize early, reward late
    if bin_residual == bin_capacity {
        score += 1.0 + 4.0 * (1.0 - progress) - 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod small divisors reveals
    // how "usable" the leftover space is for common item sizes (1..100 range).
    let r = post_residual;

    // Penalize residuals that are not divisible into useful chunks.
    // A residual divisible by 25 or 20 can host typical medium items exactly.
    if r > 0 {
        if r % 25 == 0 { score -= 12.0; }
        else if r % 20 == 0 { score -= 8.0; }
        else if r % 10 == 0 { score -= 5.0; }
        else { score += 3.0; }
    }

    // Dead-space class: residuals in (0,10] are nearly unusable given min item 1,
    // but tiny slivers (< 5) are pure waste -> heavy penalty.
    if r > 0 && r < 5 { score += 40.0; }
    else if r > 0 && r <= 10 { score += 15.0; }

    // Integer-division thresholds: how many "half-bin" chunks remain.
    let halves = r / 50;
    score -= 6.0 * halves as f64;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= r {
        if next_item_size == r {
            score -= 30.0; // perfect harmonic closure
        } else {
            let next_post = r - next_item_size;
            // reward if the chain keeps residuals on nice classes
            if next_post % 10 == 0 { score -= 10.0; }
            if next_post < 5 { score += 20.0; } // would create dead space
            score -= 4.0;
        }
    } else if next_item_size > 0 && next_item_size > r {
        // next item won't fit here anyway; slight penalty for blocking
        score += 5.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Progress-based mild pressure: later in the stream, prefer tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress;

    // New-bin candidate: give it a baseline that real bins must beat,
    // but allow opening a new bin when all residuals are poor fits.
    if bin_residual == bin_capacity {
        score += 25.0;
        // If existing bins would leave bad residuals, new bin becomes attractive:
        if r % 10 != 0 || (next_item_size > 0 && next_item_size > r && r > 0) {
            score -= 30.0;
        }
    }

    // Coupling with mean residual: prefer bins below mean (tighter bins first).
    score -= 0.3 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space zone: residuals that most items (>=10) cannot use are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }
    // Moderately hard-to-fill gaps: partial penalty.
    if post_residual >= 10 && post_residual < 25 {
        score += 40.0;
    }

    // Lookahead synergy: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 2.0 * next_item_size as f64;
        if post_residual == next_item_size {
            score -= 50.0;
        }
    }
    // Penalize if next item cannot fit in post_residual (dead space likely).
    if next_item_size > post_residual && post_residual > 0 {
        score += 1.5 * next_item_size as f64;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: penalize creating more bins when many are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 60.0 + 5.0 * open_bins_count as f64;
    } else {
        score -= 3.0 * open_bins_count as f64;
    }

    // Early stream: be lenient, allow opening bins (flexibility later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score -= 40.0 * (1.0 - progress);
    }

    // Prefer bins tighter than the mean residual (fill fuller bins first).
    score += 0.5 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }
    // Near-perfect match: next item fits with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to the shortfall.
        let shortfall = (next_item_size - post_residual) as f64;
        score += 80.0 * (shortfall / bin_capacity as f64);
    }

    // Reward tight fits in the current step (small dead space).
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 100.0 * tightness;

    // Penalize bins whose residual is already far below mean (wasted space elsewhere).
    score += 0.5 * (mean_residual - post_residual as f64).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * tightness;

    // Make the brand-new bin option unattractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 40.0 + 10.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual relative to capacity.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio;

    // Strongly penalize wasting a large residual on a small item (dead space creation).
    if post_residual > 0 && post_residual < 10 {
        score -= 30.0; // near-perfect fill bonus
    }
    if post_residual >= 10 && post_residual < item_size.min(20) as u32 {
        score += 8.0; // residual too small for typical future items
    }

    // Last-chance bonus: if this is the only bin that can fit, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; slightly penalize leaving awkward gap
            score += 5.0;
        }
    }

    // Global pressure: many open bins with low mean residual -> prefer consolidating
    // into existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when existing residuals are large/scattered
        // or item is huge relative to mean residual.
        let pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 30.0 * pressure + 10.0 * (1.0 - progress);
        if item_size as f64 > mean_residual {
            score -= 35.0; // item doesn't fit typical open bin well -> new bin helps
        }
    } else {
        // Existing bin: reward choosing bins below mean residual (consolidate small gaps).
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        } else {
            score += 5.0;
        }
        // More open bins -> stronger consolidation incentive.
        score -= (open_bins_count.min(50) as f64) * 0.3;
    }

    // Late-stream bias: as stream ends, tighten packing (prefer fullest bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: quadratic waste in post-residual, modulated by stream progress
    let mut score = pr * (1.0 + 0.9 * progress) + 60.0 * norm_pr * norm_pr * (0.4 + progress);

    // Smooth non-linear coupling: post_residual x progress interaction
    score += 25.0 * norm_pr * norm_pr * progress * (1.0 - progress) * 4.0;

    // Reward tight fits (small post-residual relative to item size)
    score -= 30.0 * (1.0 - norm_pr) * fit * (1.0 + 0.5 * progress);

    // Penalize bins far from mean residual (encourage residual homogenization)
    let dev = (pr - mean_residual) / cap;
    score += 12.0 * dev * dev;

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0 * (1.0 + progress);
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nxs = next_item_size as f64;
        if pr >= nxs {
            let slack = (pr - nxs) / cap;
            score -= 15.0 * (1.0 - slack) * (0.5 + 0.5 * progress);
        } else {
            score += 10.0 * ((nxs - pr) / cap);
        }
    }

    // New-bin candidate: penalize opening a bin unless it is genuinely better
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        score += 40.0 + 5.0 * crowd * (1.0 - progress) - 20.0 * progress;
        // allow new bin late in stream or when many bins can fit anyway
        if fitting_bins_count > 2 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bucket into deciles of capacity
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_class = (post_residual * 10 / bin_capacity) as i32; // 0..9 harmonic class

    // Reward small post_residual (tight fits), extra reward for near-zero classes
    score -= (9 - post_class) as f64 * 3.0;
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= bin_capacity / 20 {
        score -= 25.0; // near-perfect
    } else if post_residual <= bin_capacity / 10 {
        score -= 12.0;
    }

    // Dead-space penalty: residual too small for any plausible item (items >= 1,
    // but small residuals < 10 are hard to fill given typical min sizes)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Coupling with next item: reward if next_item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
            // modulo harmony: next item leaves a class-0 remainder
            if (post_residual % next_item_size.max(1)) == 0 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here; slight penalty for wasting large residual
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // last item: prefer closing bins tightly
        score -= 20.0;
    }

    // Last-chance bonus: only this bin fits -> avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin is a fallback unless current fit is bad
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 45.0;
        // cheaper to open a new bin late in the stream? no: cheaper early (more items to fill it)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
        // if item is large, new bin is reasonable
        if item_size >= bin_capacity / 2 {
            score -= 25.0;
        }
        // if many bins open and mean residual large, prefer reusing existing bins
        score += (open_bins_count as f64).ln().max(0.0) * 8.0;
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
    }

    // Prefer filling bins with large residual when item is large (avoid fragmentation)
    if item_size as f64 > mean_residual {
        score += 5.0;
    }

    // Mild penalty for spreading across too many bins
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can use are heavily penalized.
    // Items are 1..=100, but small gaps (< ~10) are rarely usable; grade the penalty
    // by how "wasted" the gap is relative to the mean residual of open bins.
    if post_residual > 0 {
        // dead-space zone: gap too small to be useful
        let dead_threshold = 12.0f64;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 4.0;
        }
        // gap that cannot fit the lookahead item is worth much less
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
        // gap that exactly fits the lookahead item is gold
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 20.0;
        }
    } else {
        // perfect fill: strongly reward
        score -= 30.0;
    }

    // Reward tight fits: utilization of the bin after placement.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Open-bins pressure: when many bins are open, prefer consolidating into
    // existing bins; when few bins are open, opening a new bin is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.0;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when the current fit is bad (large dead space) or when
    // the item is large and would leave an awkward gap elsewhere.
    if bin_residual == bin_capacity {
        // baseline competitiveness for a fresh bin
        let fresh_base = item_size as f64 * 0.9;
        // penalize opening new bins when existing bins fit decently
        let open_penalty = (open_bins_count as f64) * 1.2;
        // if next item is large, a fresh bin is more attractive (reserves space)
        let lookahead_bonus = if next_item_size >= item_size { 6.0 } else { 0.0 };
        score = fresh_base + open_penalty - lookahead_bonus;
        // if no other bin fits, new bin must win
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild stream-progression adaptation: later in the stream, be more
    // conservative about dead space since fewer items remain to fill gaps.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && (post_residual as f64) < 12.0 {
        score += progress * 6.0;
    }

    // Mean-residual coupling: if the average residual across open bins is small,
    // this bin's residual matters more; penalize diverging from it.
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fit.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 15 {
        score -= 40.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space the next item cannot use: penalize proportionally.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just fill tightest bin.
        score -= 100.0;
    }

    // Compare against mean residual: prefer bins that stay near/above mean
    // (avoid fragmenting the most reusable space).
    if (bin_residual as f64) < mean_residual - 10.0 {
        score += 15.0;
    } else if (bin_residual as f64) > mean_residual + 10.0 {
        score -= 10.0;
    }

    // Last-chance bin before opening a new one: strong incentive to use it.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && post_residual <= 20;
        if good_fit_exists {
            score += 250.0; // discourage opening a new bin
        } else {
            score -= 30.0; // allow opening when fits are poor
        }
    }

    // Mild preference to consolidate into fewer bins as stream progresses.
    if open_bins_count > 4 {
        score -= 2.0 * open_bins_count as f64 / (open_bins_count as f64 + post_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Core fit quality: strongly reward near-perfect fits ---
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 45.0 * fit_ratio * fit_ratio; // superlinear reward for tight packing

    // --- Dead space penalty: residuals that are too small to hold any item (min size 1..=100, but tiny slivers are useless) ---
    if post_residual > 0 && post_residual < 8 {
        score += 60.0; // unusable sliver
    } else if post_residual >= 8 && post_residual < 20 {
        score += 18.0 * (1.0 - progress); // small残 space is worse early when many large items may come
    }

    // --- Lookahead coupling: does the leftover fit the next item? ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // leftover can host the next item: reward proportionally to how snugly
            let snug = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * snug;
        } else if next_item_size > post_residual {
            // next item won't fit here afterwards: mild penalty scaled by how much it misses
            let miss = (next_item_size - post_residual) as f64;
            score += 0.35 * miss.min(40.0);
        }
    } else {
        // Last item: only immediate tightness matters, weight post_residual less
        score *= 0.8;
    }

    // --- Last-chance bonus: this is the only bin that can fit the item ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0; // strongly prefer using the last viable bin over opening a new one
    }

    // --- Global state coupling ---
    // When many bins are open with large mean residual, prefer consolidating into fullest bins
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 12.0 * fullness * (open_bins_count as f64).ln().max(1.0);

    // Mean-residual aware penalty: if this bin's residual is far above mean, it's a poor target
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev.max(0.0); // penalize targeting bins with more free space than average
    score -= 0.10 * (-dev).max(0.0); // slight reward for bins tighter than average

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: grows as stream progresses and bins accumulate
        let mut new_bin_cost = 55.0 + 25.0 * progress + 1.5 * open_bins_count as f64;
        // If no open bin fits well (item much smaller than residual of others), new bin is fine
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            new_bin_cost -= 30.0; // large items start fresh bins more readily
        }
        // Lookahead: a fresh bin guarantees the next item fits too
        if next_item_size > 0 && next_item_size <= bin_capacity {
            new_bin_cost -= 8.0;
        }
        score = new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Base: reward tight fits non-linearly (quartic in fill ratio)
    let mut score = pr * (1.0 + 0.6 * fill * fill);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early stream: tolerate larger residuals; late stream: penalize heavily
    let prog_coupling = pr * (0.4 + 1.4 * progress * progress) - 0.5 * pr * progress * (1.0 - progress);
    score += prog_coupling;

    // Lookahead synergy: reward bins whose post-residual fits the next item (smooth kernel)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = pr - nxt;
        let kernel = (-0.02 * diff * diff).exp();
        score -= 8.0 * kernel * (0.5 + 0.5 * progress);
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Scarcity pressure: many open bins -> prefer consolidating (penalize residuals relative to mean)
    let scarcity = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += scarcity * (pr - mean_residual).abs() * 0.3;

    // Smooth penalty for wasteful near-empty placements in existing bins
    let waste = (pr / cap - 0.5).max(0.0);
    score += 6.0 * waste * waste * scarcity;

    // New-bin candidate: neutral-ish score that decays with progress
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.25 * progress) - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Exact fit: perfect closure, strong reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Harmonic classes of post_residual: dead space classes by integer division.
    let pr = post_residual as f64;
    // Class thresholds: residual <= 10 is a "usable sliver" (next items min size 1... but keep generic).
    if post_residual > 0 && post_residual <= 10 {
        score -= 40.0; // small leftovers are fine, near-closed bins
    } else {
        // Penalize awkward mid-range residuals that few future items can fill.
        let half = post_residual / 2;
        // Modulo-style coupling: does post_residual divide nicely into plausible item chunks?
        let chunk = if post_residual >= 50 { 25 } else if post_residual >= 34 { 17 } else { 10 };
        if post_residual % chunk == 0 {
            score -= 15.0; // splittable residual, likely reusable
        } else {
            score += 10.0 + 0.5 * (half as f64 % 7.0); // odd dead-space penalty
        }
    }

    // Lookahead: reward bins where the next item also fits in the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0;
        // Bonus if next item nearly closes the bin after this placement.
        if post_residual - next_item_size <= 5 {
            score -= 30.0;
        }
    } else if next_item_size > 0 && next_item_size > bin_residual && next_item_size <= post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; mildly penalize leaving large unusable gap.
        score += 0.3 * pr;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a bin should only win when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 150.0 - 30.0 * progress;
        // If many bins can fit, discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 50.0 * (fitting_bins_count as f64).min(3.0);
        }
        // If this is a large item and mean residual is small, new bin is attractive.
        if item_size as f64 > mean_residual + 20.0 {
            score -= 100.0;
        }
        // Exact half-ish items into a fresh bin are fine.
        if item_size * 2 >= bin_capacity {
            score -= 40.0;
        }
    }

    // Prefer tightest bins overall: closeness of item to residual (best-fit core).
    score += (bin_residual - item_size) as f64 * 0.2;

    // Mild penalty for spreading across too many open bins when residuals are large.
    if open_bins_count > 3 && mean_residual > 40.0 && post_residual > 30 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (<10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Medium gaps (10..20) mildly penalized since fewer items fit them.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving a gap that can host the lookahead item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 4.0 * (next_item_size as f64 / 100.0);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space relative to lookahead: penalize.
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, opening a new one is cheaper.
    let pressure = (open_bins_count as f64).ln() * 5.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; discount early in stream.
        score += 15.0 + pressure * (1.0 - step_index as f64 / total_items.max(1) as f64 * 0.5);
    } else {
        score -= pressure * 0.4;
    }

    // Prefer bins whose residual is close to the mean (balanced packing).
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and next item size (perfect chain placement).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Exact match gets a strong bonus; near matches get a decaying bonus.
        if diff == 0.0 {
            score -= 40.0;
        } else {
            score -= 20.0 * (-diff / 15.0).exp();
        }

        // Penalize leaving a residual that is too small for the next item
        // (dead space: next item must go elsewhere or a new bin opens).
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are already
    // well-utilized; filling them fully is good, so reward low residual bins.
    let r = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.3 * (r - mean_residual).max(0.0);
        score -= 0.15 * (mean_residual - r).max(0.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current item is large relative
    // to available fits and would leave bad dead space in any open bin.
    if bin_residual == bin_capacity {
        // New empty bin baseline: post_residual = capacity - item_size.
        // Penalize opening a new bin unless the item is big enough that
        // open bins would be badly fragmented.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 + 10.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            // New bin can also host the next item: soften the penalty.
            score -= 12.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative anyway
        }
    }

    // Small penalty for wasting more than half a bin's worth of space.
    if post_residual > bin_capacity / 2 {
        score += 0.25 * (post_residual - bin_capacity / 2) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let tightness = post_residual as f64 / bin_capacity as f64;
        score -= 60.0 * (1.0 - tightness).powi(6);
    }

    // Lookahead: reward if the next item can fit into the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        let bonus = if slack_after_next == 0 { 120.0 } else { 40.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64) };
        score -= bonus;
    } else if next_item_size > 0 {
        // Penalize leaving residual that nothing will use.
        score += 15.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Penalize opening new bins when plenty of open bins can fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / 10.0;
        score += 30.0 + 20.0 * pressure * (1.0 - progress) + mean_residual * 0.3;
        // But allow a new bin if item is huge and mean residual is small.
        if item_size as f64 > bin_capacity as f64 * 0.7 && mean_residual < item_size as f64 {
            score -= 60.0;
        }
    } else {
        // Mild preference for bins with smaller residuals (fill emptier space first).
        score += 0.1 * bin_residual as f64;
    }

    // Slight time-dependent aggression toward consolidation early on.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits, non-linearly penalized dead space
    let mut score = pr * (1.0 + 0.8 * pr / cap);

    // Quadratic dead-space blowup, smoothed by stream progress
    let x = pr / cap;
    score += 30.0 * x * x * (0.5 + progress);

    // Cubic interaction: late in stream, tiny residuals are gold
    score -= 25.0 * progress * (1.0 - x) * (1.0 - x) * (1.0 - x);

    // Lookahead: reward if next item fits the post residual (chaining)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 12.0 * (1.0 - slack) * (0.4 + 0.6 * progress);
        } else {
            // penalize residuals that strand the next item
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Slight penalty when bin's residual is far from the mean residual
    // (prefer placements that keep bin population balanced)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Mild new-bin bias control: empty candidate bin has pr == cap
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Small post residuals are excellent.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Integer-division thresholds: dead-space class via (post_residual / 10)
    let dead_class = post_residual / 10; // 0..=10
    score += match dead_class {
        0 => -40.0,          // near-perfect fit
        1 => -25.0,          // excellent
        2 => -12.0,          // good
        3 => 0.0,
        4 => 8.0,
        5 => 18.0,           // half-empty
        6 => 26.0,
        7 => 34.0,
        _ => 40.0 + (dead_class as f64 - 8.0) * 3.0,
    };

    // Modulo arithmetic: residuals divisible by small moduli pair well with
    // typical item sizes, so leftover chunks remain reusable.
    let mod_bonus = (post_residual % 10 == 0) as i32 as f64 * 6.0
        + (post_residual % 20 == 0) as i32 as f64 * 4.0
        + (post_residual % 5 == 0) as i32 as f64 * 2.0;
    score -= mod_bonus;

    // Lookahead coupling: harmonic class of next item vs post residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            // next item fits here later: strong reward, scaled by closeness
            let tight = 1.0 - (pr - nx) / cap;
            score -= 20.0 * tight * tight;
        } else {
            // next item cannot use this leftover: penalize large unusable gaps
            score += 6.0 * (1.0 - pr / nx).max(0.0);
        }
        // modulo resonance between leftover and next item
        if post_residual >= next_item_size && (post_residual % next_item_size.max(1)) < 10 {
            score -= 4.0;
        }
    } else {
        // last item: reward filling as much as possible
        score -= 30.0 * (1.0 - frac);
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when no open
    // bin offers a decent harmonic class (mean residual already large).
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / cap).clamp(0.0, 1.0);
        score = cap as f64 * 0.92 - 25.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a bin anyway
        }
    }

    // Slight preference for consolidating when many bins are open
    score -= (open_bins_count.min(20) as f64) * (1.0 - frac) * 0.4;

    // Stream progression: early on, be pickier about large residuals
    if total_items > 0 {
        let t = step_index as f64 / total_items as f64;
        score += (1.0 - t) * frac * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        score += 30.0 + 10.0 * pressure;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward keeping this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // Next item cannot use the leftover; leftover becomes dead space.
        score += 10.0;
    }

    // Prefer bins whose residual deviates below the mean (fill the emptiest-ish bins,
    // keeping tighter bins for smaller future items).
    score += 0.15 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Small residual is only good if it's still usable by the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            // Lookahead match: next item exactly fills the remaining space.
            if post_residual == next_item_size {
                score -= 500.0;
            } else {
                // Partial lookahead match: reward proportionally to tightness.
                let tightness = next_item_size as f64 / post_residual as f64;
                score -= 200.0 * tightness;
            }
        } else {
            // Dead space: residual too small for the next item (or no next item).
            // Penalize more as the residual shrinks into unusable territory.
            let unusable = (next_item_size as f64 - post_residual as f64).max(0.0);
            score += 1.5 * unusable;
        }
    }

    // Favor bins whose residual is below the mean (tighter bins get filled first),
    // leaving larger residuals in other bins for future flexibility.
    let diff = mean_residual - bin_residual as f64;
    score += 0.5 * diff;

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: an empty bin is a resource; discourage opening
    // one unless the item fits poorly everywhere (no lookahead benefit anywhere).
    if bin_residual == bin_capacity {
        let good_fit_exists = post_residual == 0
            || (next_item_size > 0 && post_residual >= next_item_size);
        let _ = good_fit_exists; // informational only; empty bin has post_residual = C - item
        // Base penalty for consuming a fresh bin.
        score += 120.0;
        // Soften the penalty late in the stream when leftover bins matter less.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 60.0 * progress;
        // If many bins are open, opening yet another one fragments capacity.
        score += 5.0 * open_bins_count as f64;
    }

    // Mild preference to keep a few large-residual bins available early on.
    if bin_residual != bin_capacity && bin_residual as f64 > 2.0 * mean_residual {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of the fit: fraction of the bin consumed by this item
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead coupling: reward if next item fits into post_residual
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // penalize post-residuals that are too small for the next item
            let waste = next_item_size as f64 - post_residual as f64;
            score += 0.3 * waste;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when good fitting bins exist
    if bin_residual == bin_capacity {
        let scarcity = (fitting_bins_count as f64).max(1.0);
        score += 25.0 / scarcity;
        // early stream: opening bins is cheap; late stream: prefer filling existing
        score += 20.0 * (1.0 - progress);
        // if mean residual is large, discourage new bins
        score += 0.2 * mean_residual;
    }

    // Crowding: many open bins -> prefer consolidating into existing bins
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // Slight preference for bins tighter than the average residual
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Base: post-residual waste, scaled non-linearly by stream progress.
    // Early in the stream waste is cheap (bins can be filled later); late in the
    // stream waste becomes costly, so we amplify it smoothly.
    let pr = post_residual as f64;
    let progress_amp = 1.0 + 2.0 * progress * progress; // smooth quadratic ramp 1 -> 3
    let mut score = pr * progress_amp;

    // Non-linear reward for tight fits: residual^2 term penalizes large leftovers
    // disproportionately (quadratic waste penalty), normalized by capacity.
    score += (pr * pr) / cap;

    // Cubic coupling: extreme waste (nearly empty bins) is punished super-linearly.
    let prn = pr / cap;
    score += 30.0 * prn * prn * prn * cap;

    // Reward bins whose residual is close to the item (good fit) relative to mean residual.
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 10.0 * fit_ratio * fit_ratio; // tighter fit => higher ratio => lower score

    // Interaction between post_residual and mean residual: placing the item in a bin
    // whose residual is near the mean keeps balance; deviations get smoothed penalty.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - gap / cap);
    }
    // If next item cannot fit in post-residual but could fit elsewhere, mild penalty
    // proportional to leftover size relative to next item.
    if next_item_size > post_residual {
        score += 3.0 * (pr / cap);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the waste is egregious.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 - prn);
    }

    // Mild penalty for spreading across too many open bins: consolidation pressure
    // grows smoothly with open bin count.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (pr / cap);

    // New-bin candidate handling: an empty bin has huge raw residual; scale it down
    // but keep it competitive only when the fit into open bins would be terrible.
    if bin_residual == bin_capacity {
        // Empty-bin score: moderate constant plus waste-avoidance term comparing
        // item size to capacity; attractive when item is large relative to capacity.
        score = 25.0 + 40.0 * (1.0 - item_size as f64 / cap) * (1.0 - progress);
        // Late in the stream, opening new bins is less desirable.
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 (capacity fraction quantum)
    let q = bin_capacity / 10; // 10
    let class = (post_residual % q) as f64;
    // Perfect-fit class (residue 0) is highly desirable
    if post_residual % q == 0 {
        score -= 8.0 + post_residual as f64 / 10.0;
    } else if post_residual % q == 1 {
        // residue 1 is dead space: worst class
        score += 12.0;
    } else {
        // penalize small odd residues (hard to reuse)
        score += class * 0.6;
    }

    // Integer-division thresholds on post_residual: classify leftover size
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if post_residual == 0 {
        score -= 20.0; // exact fill
    } else if post_residual < quarter {
        score += 6.0; // tiny leftover, likely dead
    } else if post_residual < half {
        score -= 2.0; // medium leftover reusable by small items
    } else {
        score -= 4.0; // large leftover still flexible
    }

    // Lookahead coupling: does next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward leftover matching next item's harmonic class
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 - slack * 0.1;
            if (post_residual - next_item_size) % q == 0 {
                score -= 4.0; // chain of class-aligned fills
            }
        } else {
            score += 3.0; // leftover cannot host next item
        }
    } else {
        // last item: prefer exact closure
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter fit
        score += (fitting_bins_count as f64).ln() * 1.5;
    }

    // New-bin candidate handling: empty bin gets baseline score
    if bin_residual == bin_capacity {
        // opening a new bin is good only if no open bin fits well
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 * 0.9 - progress * 5.0
            + if fitting_bins_count == 0 { -6.0 } else { 4.0 + mean_residual * 0.05 };
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 3.0; // room to pair items in a fresh bin
        }
    }

    // Mild pressure to consolidate when many bins are open
    score -= (open_bins_count as f64).sqrt() * 0.4;

    // Mean residual alignment: prefer bins near the mean residual (balanced packing)
    score += ((post_residual as f64 - mean_residual).abs()) * 0.05;

    // Tight-fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly unusable
    // (items are >= 1, but gaps < next plausible small item waste space).
    if post_residual > 0 {
        if post_residual <= 10 {
            // unusable sliver: heavy penalty
            score += (11 - post_residual as i32) as f64 * 40.0;
        } else if post_residual < 20 {
            score += (20 - post_residual) as f64 * 6.0;
        }
    } else {
        // perfect fit: strong reward
        score -= 120.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins becomes expensive.
    let open_pressure = open_bins_count as f64 * 4.0;
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 60.0 + open_pressure;
        // But if this bin is the last chance and fit would be very tight,
        // still allow the existing bin to win (handled by existing-bin branch).
        if post_residual == 0 {
            score -= 200.0; // fresh bin with perfect fit never happens; keep guard
        }
        // Early stream: opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 25.0;
    } else {
        // Existing bin bonus, stronger when it's the only fitting bin.
        score -= 15.0 + if fitting_bins_count == 1 { 45.0 } else { 0.0 };
    }

    // Lookahead coupling: if the leftover residual could exactly host the
    // next item, this placement is doubly valuable.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }
    // If leftover is smaller than next item but nonzero, it's dead space
    // relative to lookahead: mild extra penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins whose residual is already below
    // average (tighter bins), keeping loose bins for future large items.
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 && bin_res_f < mean_residual {
        score -= (mean_residual - bin_res_f) * 0.5;
    } else if mean_residual > 0.0 {
        score += (bin_res_f - mean_residual) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item -> strong reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits too, but leftover remains; reward proportional to closeness
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize unusable remainder
            let dead = (next_item_size - post_residual) as f64;
            score += 0.6 * dead;
        }
    } else {
        // Last item: prefer tightest fit (already via post_residual), small bonus
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless it is genuinely needed
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 55.0 - 10.0 * progress;
        // Opening a new bin is more acceptable when few bins fit the item
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Coupling with mean residual: prefer bins whose residual deviates below mean (tight bins)
    let resid = post_residual as f64;
    if resid < mean_residual {
        score -= 0.3 * (mean_residual - resid);
    } else {
        score += 0.2 * (resid - mean_residual);
    }

    // Slight preference to fill nearly-full bins early in the stream
    score += 0.05 * (post_residual as f64) * (1.0 - step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize when item nearly fills the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize leaving small unusable gaps (dead space under min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly in the post-residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 90.0;
        } else if post_residual > next_item_size {
            score -= 10.0;
        } else {
            // Next item cannot use leftover: dead space likely.
            score += 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate: only attractive when the item is large and few bins
    // fit it well, or when open bins are crowded (low mean residual).
    if bin_residual == bin_capacity {
        let crowdedness = mean_residual / bin_capacity as f64; // high = roomy bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize new bins generally; discount penalty when bins are crowded
        // or the item is big.
        score += 120.0
            - 60.0 * (1.0 - crowdedness)
            - 40.0 * fill_ratio
            - 20.0 * progress;
        // If many bins already fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 2 {
            score += 80.0;
        }
    }

    // Mild preference for fuller bins among many open bins (reduce bin count).
    if open_bins_count > 1 {
        score -= 5.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Prefer bins below mean residual (consolidate emptiness).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: post-residual, with non-linear polynomial shaping by stream progress.
    // Early: prefer tight fills (low post_residual) mildly.
    // Late: penalize large post_residual more aggressively to squeeze bins.
    let poly = 1.0 + 2.0 * progress * progress; // smooth coupling, 1 -> 3
    let mut score = pr * poly;

    // Non-linear reward for near-perfect fits (post_residual close to zero),
    // scaled up as the stream progresses.
    let tight = (1.0 - pr / cap).powi(8);
    score -= 12.0 * tight * (0.5 + progress);

    // Penalize mid-range dead space (unusable gaps) with a smooth bump.
    let dead = (pr / cap - 0.35) * (pr / cap - 0.35);
    score += 6.0 * dead * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: reward if the next item can also fit the resulting residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack_fit = 1.0 - ((pr - nx) / cap).powi(2);
            score -= 8.0 * slack_fit * (0.5 + progress);
        } else {
            score += 4.0 * progress; // next item won't fit; mild penalty
        }
    }

    // New-bin candidate handling: make it attractive only when open bins
    // would leave large residuals or are scarce/crowded.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (1.0 + mean_residual.max(0.0));
        score = pr * poly + 10.0 + 3.0 * progress + crowd.min(20.0);
        // Allow new bin if existing fits are all poor (high mean residual spread)
        if mean_residual > 0.6 * cap && fitting_bins_count <= 2 {
            score -= 18.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: residues near multiples of 10 are "usable slots"
    let r = post_residual % 10;
    let class_bonus = match r {
        0 => 12.0,           // perfectly harmonic residual
        1 | 9 => 6.0,
        2 | 8 => 2.0,
        3 | 7 => -2.0,
        4 | 6 => -6.0,
        _ => -10.0,          // r == 5: half-class, awkward dead space
    };
    score -= class_bonus;

    // Integer-division threshold: residual big enough for a "half" (>=50) or "third" (>=33)
    let half = post_residual / 50;
    let third = post_residual / 33;
    score -= 4.0 * (half as f64) + 2.0 * (third as f64);

    // Lookahead coupling: if the next item fits exactly into the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // next item won't fit here: penalize large wasted residuals less if bin almost full
            let waste_frac = post_residual as f64 / bin_capacity as f64;
            score += 8.0 * waste_frac;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when item is large relative to capacity
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        if fill > 0.5 {
            score -= 10.0 * (fill - 0.5);
        } else {
            score += 12.0 * (0.5 - fill);
        }
        // late in stream, prefer packing into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
    }

    // Mean-residual coupling: if this bin is far below mean residual, it's a laggard bin — prefer filling it
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= 2.0 * diff.min(20.0);
    }

    // Penalize creating tiny unusable slivers (< 10, smallest item size)
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest future item are "dead".
    // Penalize post_residuals in the unusable gap (1..10) heavily; reward near-perfect fits.
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 45.0; // dead space: wasted but unusable
    } else if post_residual <= 20 {
        score += 8.0; // marginal usability
    } else {
        // Usable residual: mildly reward larger usable space
        score -= 4.0;
    }

    // Reward tight fits relative to item size (post_residual / item_size ratio)
    if item_size > 0 {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= 25.0 * fill_ratio; // favor placing into bins where item fills more
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 35.0;
        } else if slack < 10 {
            score += 5.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 12.0; // next item won't fit here -> this residual likely becomes dead
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize opening new bins); with few open bins, new bins are cheaper.
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open-bin pressure and stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 18.0 + 10.0 * bin_pressure + 15.0 * progress;
    } else {
        // Existing bin: reward slightly more when many bins are open.
        score -= 3.0 * bin_pressure;
    }

    // Mean residual context: if this bin is far below mean residual, it's a laggard bin;
    // filling laggard bins consolidates residual mass.
    let dev = mean_residual - pr;
    if dev > 0.0 {
        score -= 0.3 * dev.min(40.0);
    } else {
        score += 0.2 * (-dev).min(40.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: residual after placement exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: next item fits with small waste left after that.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next <= 10 {
            score -= 40.0 - (after_next as f64) * 2.0;
        } else if after_next <= 25 {
            score -= 15.0 - (after_next as f64) * 0.4;
        } else {
            // Large leftover after two steps: penalize proportionally.
            score += (after_next as f64) * 0.15;
        }
    }

    // Next item cannot fit here at all: mild penalty if leftover is big dead space.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Favor tight fits relative to the mean residual of open bins.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.3;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize creating tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // New-bin candidate: prefer it only when open bins are quite full on average
    // and the current leftover would be large dead space.
    if bin_residual == bin_capacity {
        score = 45.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        if mean_residual > 40.0 {
            score -= (mean_residual - 40.0) * 0.4;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * tightness * tightness;

    // Penalize small unusable leftovers (dead space), worse late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 8.0 + 10.0 * progress;
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins have poor fits or
    // the lookahead item would benefit from a fresh bin.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 18.0; // fresh bin can host both current and next item
        }
        if fitting_bins_count > 0 && mean_residual > item_size as f64 + 15.0 {
            score += 12.0; // open bins still roomy; don't open new bin
        }
    }

    // Lookahead synergy: placing here leaves room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Prefer bins whose residual is close to mean (balanced usage).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // Slight preference for using fewer bins as stream progresses.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial base: reward small post_residual, increasingly so late in stream
    let mut score = pr * (1.0 + 1.5 * progress * norm_pr);

    // Penalize dead space quadratically when it can't fit the lookahead item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        score += 0.8 * gap * gap / cap;
        // Reward bins whose post_residual exactly accommodates next item
        if pr >= next_item_size as f64 {
            score -= 6.0 * (1.0 - (pr - next_item_size as f64) / cap) * (0.5 + progress);
        }
    }

    // Last-chance bonus: smooth in fitting_bins_count
    let scarcity = 1.0 / (fitting_bins_count as f64);
    score -= 10.0 * scarcity * (1.0 - norm_pr) * (0.5 + 0.5 * progress);

    // Mild penalty for very tight fits creating tiny residuals (smooth cubic)
    score += 0.05 * (norm_pr * (1.0 - norm_pr)).powi(3) * cap;

    // New-bin candidate: neutral-ish score scaled by stream progress
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.4 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: residuals in the same
    // "harmonic band" as common small items are more reusable ---
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity remaining after placement
    let frac = pr / cap;

    // Harmonic class: integer division thresholds on post_residual.
    // Class 0: pr <= 10 (dead space), Class 1: 11..=25, Class 2: 26..=50, Class 3: >50
    let class = if post_residual <= 10 { 0u32 }
        else if post_residual <= 25 { 1 }
        else if post_residual <= 50 { 2 }
        else { 3 };

    // Penalize dead-space classes progressively (non-linear coupling)
    score += match class {
        0 => 30.0 + (10.0 - pr) * 2.0,      // tiny leftover is nearly useless
        1 => 8.0,                            // small but usable
        2 => 0.0,                            // sweet spot
        3 => -6.0 * (frac - 0.5),            // large leftover slightly rewarded
        _ => 0.0,
    };

    // Modulo arithmetic: residuals divisible into common item sizes are good.
    // Check divisibility by small harmonic steps 5 and 10.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.5;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Exact harmonic match is highly desirable
        if post_residual == next_item_size {
            score -= 25.0;
        } else {
            let after_next = post_residual - next_item_size;
            score -= 12.0;
            // Penalize leaving another dead class behind
            if after_next <= 10 {
                score += 6.0;
            }
        }
    } else if next_item_size > post_residual {
        // Next item can't use this bin's leftover; mild penalty scaled by waste
        score += 3.0 * (next_item_size as f64 - pr).min(20.0) / 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin for a poor reason.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bins are congested
    // (few fitting bins, high mean residual spread) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = (fitting_bins_count == 0) as i32;
        // Base cost of a fresh bin
        score = 45.0;
        score -= 20.0 * congestion as f64;
        // Early in the stream, opening bins is cheaper (more future items to fill them)
        score -= 15.0 * (1.0 - progress);
        // If mean residual across open bins is low, open bins are depleted -> new bin good
        score -= (mean_residual / cap * 10.0).min(10.0);
        // If next item is large and wouldn't fit anywhere else anyway, new bin is fine
        if next_item_size > 50 && fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    // Mild global pressure: with many open bins, prefer consolidation
    score += 0.4 * open_bins_count as f64 * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are unusable.
    if post_residual > 0 {
        // Dead-space zone: gap too small to plausibly fit a future item.
        let dead_threshold = 10.0f64; // smallest plausible item size
        if (post_residual as f64) < dead_threshold {
            // Heavy penalty proportional to how "dead" the gap is.
            score += (dead_threshold - post_residual as f64) * 8.0;
        }
        // Moderate penalty for any leftover gap (waste), scaled by progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += (post_residual as f64) * 0.15 * (1.0 + progress);
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Open bins pressure: discourage opening new bins when many are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize new bin proportional to open bins count and mean residual.
        score += 10.0 + open_bins_count as f64 * 2.0 + mean_residual * 0.5;
    } else {
        // Reward using existing bins, more when few fitting bins remain.
        score -= 2.0 + (fitting_bins_count as f64).recip() * 3.0;
    }

    // Lookahead: if the next item fits the post-residual exactly-ish, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here after placement: slight penalty.
        score += 3.0;
    }

    // Last-chance bin: strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Perfect match: next item consumes ALL remaining space -> strongly favored.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits into the leftover: partial reward scaled by closeness.
            score -= 40.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // Next item cannot use the leftover: penalize dead space, worse if gap is large.
            score += gap * 0.5;
        }
        // Small post residuals that the next item can't use are near-useless dead space.
        if post_residual < next_item_size && post_residual < 10 {
            score += 15.0;
        }
    } else {
        // Last item: only absolute tightness matters.
        score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Reward tight fits relative to current residual (best-fit core).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins below the mean residual (get rid of awkward small spaces)
    // unless the fit is tight; penalize bins far above mean residual when fit is loose.
    let mean_diff = bin_residual as f64 - mean_residual;
    score += 0.15 * mean_diff * (1.0 - fill_ratio);

    // Slight preference to keep many bins consolidated as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Never prefer opening a new bin unless no open bin fits well.
    if bin_residual == bin_capacity {
        // New-bin candidate: neutral base plus penalty that shrinks when
        // the item is large relative to capacity or few bins fit.
        score += 8.0;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 50.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving small unusable slivers (dead space) behind.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0; // perfect chain fit
        } else if post_residual >= next_item_size {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 6.0 * next_fit;
        } else {
            // Next item won't fit here; mild penalty proportional to leftover size.
            score += 0.05 * post_residual as f64;
        }
    } else {
        // Last item of the stream: minimize waste aggressively.
        score += 0.5 * post_residual as f64;
    }

    // Prefer bins with smaller residuals among open bins (fill fuller bins first).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Slight preference to reuse existing bins over opening new ones as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more later in the stream and when many bins are open.
        score += 10.0 + 15.0 * progress + 0.5 * open_bins_count as f64;
    }

    // Discourage opening new bins when the mean residual across open bins is large.
    if bin_residual == bin_capacity {
        score += 0.1 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let size_norm = item_size as f64 / cap;

    // Base: penalize post_residual, with non-linear (quadratic) waste growth
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth polynomial coupling with stream progress: early on, keep space open;
    // later, tighten packing (waste penalized more as progress grows).
    let prog_coupling = 30.0 * norm_pr * (progress * progress) + 15.0 * norm_pr * progress;
    score += prog_coupling;

    // Reward filling a bin well: subtract for low post_residual (smooth sigmoid-like term)
    let fill = 1.0 - norm_pr;
    score -= 20.0 * fill * fill * fill * (1.0 + progress);

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + size_norm);
    }

    // Penalize opening new bins when many bins already open (fragmentation pressure)
    let open_norm = open_bins_count as f64 / (1.0 + progress * 50.0 + 10.0);
    score += 5.0 * open_norm * norm_pr;

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let fit_quality = next_item_size as f64 / (pr + 1.0);
        score -= 12.0 * fit_quality * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        // next item cannot use leftover: mild penalty for dead space
        score += 6.0 * norm_pr * (1.0 - fill);
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably from mean
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev - 8.0 * dev * fill;

    // New-bin candidate handling: only attractive when current bin would leave large waste
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // new bin has huge post_residual; make it unattractive unless item is large and
        // no good fit exists (post_residual after placing in empty bin = cap - item)
        let waste = norm_pr;
        score = pr + 55.0 * waste * cap - 20.0 * size_norm * size_norm;
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bucket by capacity fractions.
    // Perfect fits (post_residual == 0) are heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Class boundaries: residual <= 10 is "dead space" (most items are >= 10 originally,
        // but with sizes 1..100 only small residuals are truly dead).
        let dead_threshold = 12u32;
        if post_residual <= dead_threshold {
            // Dead space penalty grows steeply as residual shrinks.
            score += (dead_threshold - post_residual) as f64 * 3.0;
        }
    }

    // Integer-division thresholds on post_residual relative to next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: reward, stronger if snug (small leftover after next).
            let next_leftover = post_residual - next_item_size;
            score -= 8.0 + (next_item_size as f64) * 0.25;
            if next_leftover == 0 {
                score -= 25.0;
            } else if next_leftover <= 10 {
                score -= 6.0;
            }
        } else {
            // Next item will not fit in this bin: penalize using this bin now,
            // unless the fit is very tight (post_residual small anyway).
            score += 5.0;
        }
    } else {
        // Last item: pure tightness.
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }
    // Many fitting bins: mild penalty for wasting a scarce-tightness bin.
    if fitting_bins_count > 3 && bin_residual != bin_capacity {
        score += 2.0 * (fitting_bins_count as f64).min(6.0);
    }

    // New-bin candidate handling: make opening a new bin attractive only when
    // no open bin offers a good (low post_residual) fit.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin ~ large residual.
        score += 55.0;
        // Early in stream, opening bins is cheap (build diversity).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 35.0 * (1.0 - progress);
        // If open bins are already slack (mean residual high), prefer fresh bin.
        score -= (mean_residual / 20.0).min(10.0);
        // If the only alternative is poor (this call context: many bins but bad fits),
        // fresh bin looks better when mean residual is far below what we'd leave.
        if next_item_size > 0 && post_residual == bin_capacity {
            score -= 5.0;
        }
    } else {
        // Using an open bin: reward proportional to how much we consolidate.
        score -= (item_size as f64) * 0.15;
        // Prefer bins tighter than the average residual.
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 3.0;
        }
        // Too many open bins: push consolidation.
        if open_bins_count > 8 {
            score -= 1.5 * ((open_bins_count - 8) as f64).min(10.0);
        }
    }

    // Modulo arithmetic harmonic classes on post_residual:
    // residuals divisible by common item sizes (e.g. 25, 50) pair well with
    // future splits; reward those classes slightly.
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 4.0;
    } else if post_residual % 25 == 0 && post_residual > 0 {
        score -= 2.0;
    } else if post_residual % 10 == 0 && post_residual > 0 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += (11.0 - post_residual as f64) * 8.0; // tiny gap => very bad
        } else if post_residual < 20 {
            score += (20.0 - post_residual as f64) * 2.0;
        } else if post_residual <= 30 {
            // gap that can still host the smallest item class is mildly bad
            score += 4.0;
        } else {
            // large leftover space is usable: reward it
            score -= (post_residual as f64 - 30.0) * 0.3;
        }
    } else {
        // perfect fit
        score -= 30.0;
    }

    // Exact-fit lookahead: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // If next item fits into post_residual, this bin remains useful: small reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }
    // If next item would NOT fit and post_residual is small, penalize (dead end).
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin, especially late in the stream.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 12.0 + 10.0 * progress;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins
    // and encourage filling existing ones more tightly.
    let ob_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable only if item is large and open bins are few
        // or the item barely fits anywhere (fitting_bins_count small).
        score += 15.0 + ob_pressure * 6.0;
        if item_size >= 50 {
            score -= 8.0;
        }
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    } else {
        // Reward using existing bins as open-bin count grows.
        score -= ob_pressure * 1.5;
        // Prefer bins with residual close to the item (tight fit) relative to mean.
        let tightness = (bin_residual as f64 - item_size as f64).abs();
        score += tightness * 0.1;
        // If bin residual is well below mean residual, it is a "small" bin: use it.
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Late-stream consolidation: as the stream ends, favor maximal filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact or near-exact match between post_residual
    // and the next item size (completes the bin on the following step).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if gap == 0 {
            // Perfect: next item exactly fills this bin -> strongly favored.
            score -= 60.0;
        } else if gap <= 5 {
            score -= 40.0 - gap as f64 * 4.0;
        } else if gap <= 15 {
            score -= 20.0 - gap as f64 * 1.0;
        } else {
            // Next item won't fit here: leftover is likely dead space.
            score += gap.min(40) as f64 * 0.6;
        }
    } else {
        // Last item: minimize waste directly.
        score -= 25.0;
    }

    // Relative to mean residual: placing into a below-average-residual bin
    // (tight bin) preserves flexibility in roomier bins.
    let rel = post_residual as f64 - mean_residual;
    score += rel * 0.35;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Penalize the brand-new empty bin candidate unless the item is large
    // relative to capacity or all open bins are already tight.
    if bin_residual == bin_capacity {
        let tight_open = mean_residual < item_size as f64 * 1.5 && open_bins_count > 0;
        let big_item = item_size as f64 > bin_capacity as f64 * 0.6;
        if next_item_size > 0 && post_residual >= next_item_size && (big_item || tight_open) {
            score -= 10.0; // allow opening a new bin when it also serves the next item
        } else {
            score += 55.0; // otherwise discourage wasting a fresh bin
        }
    }

    // Slight preference for tighter bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64 / bin_capacity as f64) * (10.0 + 20.0 * progress);

    // Mild penalty for accumulating many open bins with slack.
    score += open_bins_count as f64 * 0.4 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.14;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling: tight fits are rewarded more as stream progresses.
    let tightness = 1.0 - pr / cap; // 0 = empty fit, 1 = perfect fit
    score -= (tightness * tightness) * (2.0 + 6.0 * progress) * cap * 0.05;

    // Penalize dead space relative to the next item's needs (smooth quadratic gap).
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 0.35 * (gap / cap) * (gap / cap) * cap;
        // Reward when this bin's post-residual exactly hosts the next item.
        let match_bonus = 1.0 - ((pr - next_item_size as f64).abs() / cap);
        score -= 4.0 * match_bonus * match_bonus * progress;
    }

    // Last-chance bin: strong smooth reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0 + 8.0 * progress;
    }

    // Mild penalty for spreading across many bins when residuals are large.
    let spread = (mean_residual / cap - pr / cap).abs();
    score += 1.5 * spread * spread * open_bins_count as f64;

    // Late-stream preference for consolidating into existing bins.
    score += (1.0 - progress) * 1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space into
    // capacity-fraction buckets. Residuals that align with common item-size
    // classes (divisors of ~100: 10, 20, 25, 50) are more reusable.
    let pr = post_residual;
    let class = if pr == 0 { 0 }
        else if pr <= 10 { 1 }
        else if pr <= 20 { 2 }
        else if pr <= 25 { 3 }
        else if pr <= 50 { 4 }
        else { 5 };
    // Reward small-but-aligned residuals, penalize mid-range dead space.
    let class_bonus: [f64; 6] = [6.0, 4.0, 2.0, 3.0, 0.0, 1.5];
    score -= class_bonus[class as usize];

    // Modulo arithmetic on residual: exact harmonic alignment gets a bonus.
    if pr > 0 {
        if cap as u32 % pr == 0 { score -= 2.0; }
        if pr % 10 == 0 { score -= 1.5; }
        if pr % 5 == 0 { score -= 0.5; }
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // this placement creates a perfect chain — reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 8.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / cap).powi(2);
        } else {
            // Next item cannot use this residual; mild penalty scaled by waste.
            score += 1.0 + (next_item_size as f64 - pr as f64) / cap;
        }
    } else {
        // Last item: only zero-residual matters.
        score += if pr > 0 { 5.0 } else { -5.0 };
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless residual would be tiny).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0 + item_size as f64 / cap;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin offers a tight fit.
    if bin_residual == bin_capacity {
        let tight_exists = fitting_bins_count > 0 && (post_residual as f64) < 0.25 * cap;
        score += if tight_exists { 15.0 } else { -1.0 };
        // Late in the stream, prefer consolidating into open bins.
        score += (step_index as f64 / total_items.max(1) as f64) * 4.0;
    }

    // Prefer bins whose residual deviates favorably from the mean
    // (below-mean residual = tighter bin, better fill).
    score += 0.5 * ((bin_residual as f64 - mean_residual) / cap);

    // Many open bins: discourage spreading; reward filling existing ones.
    if open_bins_count > 4 {
        score -= 0.2 * open_bins_count as f64 * (item_size as f64 / cap);
    }

    // Integer-division threshold: residual that could still host a
    // mid-size item (>= 25) is worth preserving.
    if pr >= 25 && next_item_size > 0 && next_item_size > pr {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward tight fits: small post_residual relative to item size is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Perfect or near-perfect fill gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits into the post residual, reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead-end residual for the next item: penalize mildly.
        score += 5.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 1.5;

    // Mean residual coupling: if this bin's residual is well below average,
    // using it up is efficient (we shrink a small residual further).
    let dev = bin_residual as f64 - mean_residual;
    if dev < 0.0 {
        score -= 0.3 * (-dev);
    } else {
        score += 0.2 * dev;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit
    // or open-bin pressure is high; otherwise keep it expensive.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64) * 2.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Slight progression bias: later in the stream, prefer consolidating.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact/near-exact matches
    // between the post-placement residual and the next item's size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect lookahead match: next item exactly fills the bin afterwards.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to tightness of the match.
            let fit_ratio = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fit_ratio * fit_ratio;
            // Extra reward if the two items together nearly fill the bin.
            let combined = (item_size + next_item_size) as f64 / bin_capacity as f64;
            score -= 25.0 * combined * combined;
        } else {
            // Next item cannot use this residual: penalize dead space.
            let waste = next_item_size as f64 - post_residual as f64;
            score += 0.5 * waste;
        }
        // Small continuous penalty on gap size (non-linear).
        score += 0.05 * gap * gap / 10.0;
    } else {
        // Last item: just minimize residual waste directly.
        score -= 10.0;
    }

    // Penalize residuals that deviate above the mean residual of open bins
    // (creating an outlier hole), reward bins already below the mean.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;
    if dev > 0.0 {
        score += 0.1 * dev * dev / 100.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Late in the stream, consolidation matters more: tighten selection.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (i.e., this bin's residual equals capacity and mean residual is small).
    if bin_residual == bin_capacity {
        if mean_residual < item_size as f64 * 0.4 || fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 15.0; // prefer reusing open bins with usable space
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    score -= (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward heavily; if post residual is too small for the next item
    // but nonzero, penalize (dead space relative to lookahead).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            score -= 8.0 * (1.0 - (post_residual as f64 - nxt) / bin_capacity as f64);
        } else {
            score += 3.0 * (nxt - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Crowding bonus: prefer filling bins when many bins are open.
    if open_bins_count > 1 {
        score -= (open_bins_count as f64).ln() * (bin_residual as f64 / bin_capacity as f64) * 2.0;
    }

    // Global residual alignment: prefer bins whose residual is near mean
    // (keeps bin pool homogeneous), penalize outliers.
    let res = bin_residual as f64;
    score += (res - mean_residual).abs() * 0.05;

    // Time horizon: early in the stream, be conservative (favor keeping
    // residuals large for future items); late in the stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (post_residual as f64) * 0.3;
    score -= progress * 5.0;

    // New-bin candidate: only attractive when it gives a much better
    // outlook than existing bins — penalize the empty bin baseline.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Allow new bin late in stream if existing bins are poor fits.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: favor small post residual, with a smooth non-linear (quadratic) shaping
    let mut score = pr * (1.0 + 0.8 * pr_norm) - 12.0 * pr_norm * (1.0 - pr_norm);

    // Polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; late, penalize them more (smooth ramp)
    let ramp = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 25.0 * ramp * pr_norm * pr_norm;

    // Lookahead coupling: if next item fits exactly in post residual, reward strongly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        let fit_quality = 1.0 - gap / cap;
        score -= 18.0 * fit_quality * fit_quality * (1.0 - ramp);
    }

    // Last-chance bin bonus (only one bin can fit the item)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Penalize opening a new bin when decent fits exist (smooth in open_bins_count)
    if bin_residual == bin_capacity {
        score += 6.0 + 2.0 * (open_bins_count as f64).sqrt() + 15.0 * (1.0 - ramp);
    }

    // Mild mean-residual coupling: prefer bins deviating from mean residual
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: group residuals into capacity-fraction bands
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity remaining after placement
    let frac = pr / cap;

    // Harmonic classes: 1/2, 1/3, 1/4, 1/6 thresholds (classic bin-packing harmonic scheme)
    let mut class_bonus = 0.0;
    if pr == 0 {
        class_bonus = -60.0; // perfect fill, strongly favored
    } else if frac <= 1.0 / 6.0 {
        class_bonus = -40.0; // tiny sliver, nearly useless space but well-filled bin
    } else if frac <= 1.0 / 4.0 {
        class_bonus = -25.0;
    } else if frac <= 1.0 / 3.0 {
        class_bonus = -10.0;
    } else if frac <= 1.0 / 2.0 {
        class_bonus = 5.0;
    } else {
        class_bonus = 15.0; // large residual left behind: wasteful placement
    }
    score += class_bonus;

    // Modulo arithmetic on post_residual: rewards residuals that are "harmonic"
    // divisors/complements of common item sizes (multiples of 10, 20, 25, 50)
    let pr_u = post_residual;
    let mut mod_bonus = 0.0;
    if pr_u % 10 == 0 { mod_bonus -= 8.0; }
    if pr_u % 20 == 0 { mod_bonus -= 4.0; }
    if pr_u % 25 == 0 { mod_bonus -= 3.0; }
    if pr_u % 50 == 0 { mod_bonus -= 3.0; }
    score += mod_bonus;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it fills
            let fill = next_item_size as f64 / pr;
            score -= 20.0 * fill;
            // harmonic check on residual after the lookahead item
            let pr2 = post_residual - next_item_size;
            if pr2 % 10 == 0 { score -= 6.0; }
            if pr2 == 0 { score -= 10.0; }
        } else {
            // next item will not fit here: penalize leaving a residual that is
            // a "trap" (slightly larger than next item)
            let gap = (next_item_size - post_residual) as f64;
            if gap < 10.0 {
                score += 12.0; // dead space trap for the lookahead item
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bin moderately attractive only when
    // existing fits are poor (large post_residual) or stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // empty bin baseline: neutral score, adjusted by open bin pressure
        score = 55.0 - 10.0 * progress + 2.0 * (open_bins_count as f64).sqrt();
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 5.0; // new bin can host the next item too
        }
    }

    // Mean-residual coupling: when open bins are generally empty, prefer tighter fills
    score += 0.05 * mean_residual;

    // Slight preference for bins that are already well-used
    let used = (bin_capacity - bin_residual) as f64;
    score -= 0.05 * used;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1..=10)
    // can realistically use are heavily penalized.
    if post_residual > 0 {
        if post_residual <= 10 {
            // Unusable sliver: nearly as bad as wasted space in a new bin.
            score += (11 - post_residual as i32) as f64 * 8.0;
        } else if post_residual <= 20 {
            // Marginal zone: only small items could fit.
            score += (21 - post_residual as i32) as f64 * 2.5;
        } else if post_residual <= 40 {
            score += 3.0;
        }
        // Perfect fit: zero waste, strong reward.
        if post_residual == 0 {
            score -= 25.0;
        }
    } else {
        score -= 25.0;
    }

    // Prefer bins whose residual was already tight (efficient packing history).
    let tightness = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
    score -= tightness * 6.0;

    // Open-bin pressure: discourage scattering across many bins, but relax
    // pressure as the stream progresses (endgame favors closing bins out).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 - 0.8 * progress);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: reward when the next item fits the post-residual,
    // penalize when next item is stranded by the leftover gap.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 7.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Mean-residual coupling: bins far below mean residual are "fresher";
    // slightly prefer filling the emptiest bins to consolidate waste.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.05;

    // New-bin candidate: only attractive when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching: strongly reward exact match of
    // post_residual with the next item's size (perfect chaining).
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;

        if post_residual == next_item_size {
            // Perfect 2-chain: bin becomes exactly full after next item.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item still fits: reward proportionally to tightness.
            let tightness = nxt / (post + 1.0);
            score -= 25.0 * tightness;
        } else {
            // Next item won't fit here: penalize dead space relative to gap.
            let gap = nxt - post;
            score += 0.15 * gap;
        }

        // Extra coupling: if post_residual matches next item modulo small slack,
        // give a mild bonus (near-exact chain).
        let slack = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if slack <= 5.0 && post_residual >= next_item_size {
            score -= 12.0 * (1.0 - slack / 5.0);
        }
    }

    // Penalize post_residual relative to the mean residual of open bins:
    // leaving more dead space than average is bad.
    score += 0.30 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    if open_bins_count > 3 {
        score -= 5.0 * (open_bins_count as f64).ln();
    }

    // New-bin candidate (empty bin): penalize unless the item is huge or
    // no good chain exists, so we keep using partially-filled bins otherwise.
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size >= 70 {
            score -= 35.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Mild reward for tight fits overall.
    score -= 10.0 * (item_size as f64 / bin_residual.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 50.0;
    }

    // Tightness ratio: strongly favor bins where the item fills most of the residual
    let fill = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill * fill;

    // Penalize leaving awkward small residuals that few future items can use
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 4.0;
    }

    // Lookahead coupling: reward residual that can host the next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // next item won't fit here; mild penalty proportional to waste
            score += 5.0;
        }
    }

    // Last-chance bin bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Global pressure: many open bins with large mean residual -> prefer consolidation
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 10.0;
    }

    // Late in the stream, favor closing out bins (larger post_residual penalized more)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * post_residual as f64 * 0.5;

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 25.0 + 15.0 * (1.0 - fill) };
        score += desperation;
        // early stream: opening bins is cheap; late stream: consolidate
        score += (1.0 - progress) * 20.0 - progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth non-linear shaping over stream progress.
    // Early on, prefer tight fills (low post_residual); later, weight dead space more.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear polynomial coupling: (normalized post_residual)^2 and ^3 modulated by progress.
    score += cap * (norm_pr * norm_pr) * (0.3 + 0.7 * progress);
    score += cap * (norm_pr * norm_pr * norm_pr) * (1.5 * progress);

    // Reward filling bins nearly exactly (smooth bump around small residuals).
    let tightness = 1.0 - norm_pr;
    score -= (item_size as f64 / cap) * (tightness * tightness) * 30.0;

    // Lookahead: penalize if post_residual cannot fit next item (smooth hinge).
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += gap * (0.5 + 0.5 * progress);
        // Reward when next item fits exactly into resulting residual.
        let fit_gap = (next_item_size as f64 - pr).abs();
        score -= (1.0 - fit_gap / cap) * 5.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Slight preference for consolidating into existing bins vs opening new ones.
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * progress;
    } else {
        score -= 2.0 + 3.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Coupling with mean residual: bins far from the mean residual get a mild penalty
    // (smooth quadratic deviation), encouraging balanced residual distribution.
    let dev = pr - mean_residual;
    score += 0.02 * dev * dev * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "usable slots"
    // in the capacity-100 geometry (multiples of 10, 20, 25, 50).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else {
        let mut bonus = 0.0;
        if pr % 50 == 0 { bonus += 18.0; }
        else if pr % 25 == 0 { bonus += 12.0; }
        else if pr % 20 == 0 { bonus += 10.0; }
        else if pr % 10 == 0 { bonus += 6.0; }
        score -= bonus;

        // Penalize small dead space (< 10) — unusable for typical items.
        if pr < 10 {
            score += 25.0;
        } else {
            // Integer-division thresholds: classify residual size class.
            let class = pr / 20; // 0..=5
            score -= class as f64 * 4.0;
        }
    }

    // Tight fit reward: item consumes most of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            score -= 8.0 * (next_item_size as f64 / pr as f64);
        } else {
            // next item won't fit here: slight penalty if post residual small
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless existing
    // fits are terrible (residuals large but item small).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // new bins are cheaper late in the stream (fewer future items to waste)
        score += 15.0 - 10.0 * progress;
        // if mean residual of open bins is large, discourage new bin further? No:
        // large mean residual means open bins are empty-ish; new bin mildly ok.
        score += (mean_residual / bin_capacity as f64) * 10.0;
        if next_item_size > 0 && next_item_size >= item_size {
            // pairing potential in fresh bin
            score -= 5.0;
        }
    }

    // Many open bins: prefer consolidating into existing bins.
    score += open_bins_count as f64 * 0.15;

    // Modulo coupling between item and residual (harmonic classes).
    if bin_residual % item_size.max(1) == 0 {
        score -= 6.0; // residual divides evenly by item: future perfect splits
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to be useful are heavily penalized.
    // Dead zone thresholds: residual < 10 is nearly unusable; < 20 is marginal.
    if post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if post_residual < 20 {
        score += 15.0; // marginal gap
    } else if post_residual <= 30 {
        score -= 8.0; // still useful for small items; reward moderate residuals
    }

    // Reward tight fits (small post_residual relative to bin_residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing bins over opening new ones
    let progress = step_index as f64 / (total_items.max(2) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin, scaled by open-bin pressure,
    // but relax the penalty if the item would leave a large residual anyway elsewhere.
    if bin_residual == bin_capacity {
        score += 20.0 + pressure;
        // If next item is large, a fresh bin is more attractive
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    // Lookahead: if the next item fits exactly into post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's already tight; prefer it
    let dev = mean_residual - post_residual as f64;
    score -= 0.3 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward when the leftover space exactly (or nearly) matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        if post_residual >= next_item_size {
            // Next item fits perfectly or close: strong reward.
            score -= 60.0 * (1.0 - diff / bin_capacity as f64);
            if diff == 0.0 {
                score -= 40.0; // perfect chain bonus
            }
        } else {
            // Next item won't fit: penalize small dead space left behind.
            score += 0.5 * post_residual as f64;
        }
    }

    // Compare against mean residual: prefer bins whose post-residual is close to mean
    // (keeps residuals uniform, avoids many tiny unusable slivers).
    let mr = mean_residual;
    if mr > 0.0 {
        let rel = (post_residual as f64 - mr) / mr;
        score += 5.0 * rel.abs();
    }

    // Penalize creating tiny dead space (< 10) that is likely unusable.
    if post_residual < 10 && post_residual > 0 {
        score += 30.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so we prefer existing bins with good fit,
    // but keep it competitive when all fits are bad (large post_residual elsewhere).
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    // Late in stream: tighten packing, prefer tight fits more strongly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / (bin_capacity as f64));
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty if we waste space.
        score += 5.0 * (post_residual as f64) / (bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Global state: many open bins with large mean residual -> prefer consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let consolidation_pressure = (open_bins_count as f64).ln1p() * (mean_residual / bin_capacity as f64);
    score += 10.0 * consolidation_pressure * (1.0 - progress);

    // New-bin candidate handling: make empty bin moderately attractive only when
    // no open bin offers a good fit (large post_residual) or bin is crowded.
    if bin_residual == bin_capacity {
        let escape_bonus = 15.0 + 20.0 * (mean_residual / bin_capacity as f64);
        score -= escape_bonus * (0.3 + 0.7 * progress);
    }

    // Mild preference for filling bins that are already fairly full.
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr * (1.0 + 0.5 * progress * norm_pr * norm_pr);

    // Smooth decay term: later in the stream, tight fits are increasingly rewarded.
    score -= (item_size as f64 / cap) * (1.0 + progress) * 10.0;

    // Penalize residuals that cannot fit the lookahead item (smooth quadratic gate).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        let usable = 1.0 - (gap / cap).powi(2);
        score -= usable * (next_item_size as f64 / cap) * 5.0;
    }

    // Last-chance bonus: only fitting bin gets strong smooth discount.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty for proliferating bins relative to mean residual.
    score += 0.01 * open_bins_count as f64 * (1.0 - norm_pr);

    // New-bin candidate: penalize unless current residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap - 0.5).abs();
        score += 20.0 - 15.0 * frag * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space in low classes is hard to fill.
    let pr = post_residual;
    if pr > 0 {
        // Penalize residuals that fall into awkward classes (1..10 and 11..19 are near-unusable
        // for items >=10; class boundaries via integer division).
        let cls = pr / 10; // harmonic class 0..10
        match cls {
            0 => score += 40.0,                    // dead space < 10: unusable
            1 => score += 25.0,                    // 10..19: only tiny items fit
            2 => score += 10.0,                    // 20..29
            3 => score += 4.0,                     // 30..39
            4 => score += 1.0,
            _ => {}                                // large residual: fine
        }
        // Modulo coupling: residuals that are exact multiples of 10 pair well with
        // common item sizes, reward them.
        if pr % 10 == 0 {
            score -= 6.0;
        }
        // Reward exact fill.
        if pr == 0 {
            score -= 100.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = pr - next_item_size;
        if slack == 0 {
            score -= 50.0; // perfect pair
        } else {
            score -= (10.0 - slack.min(10) as f64) * 1.5;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // Next item won't fit here anyway; slight penalty for wasting the residual.
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes the mean residual spread
    // across open bins. Penalize the empty bin unless open bins are crowded.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is only chosen when fits are terrible.
        score += 55.0;
        // If the stream is early, opening bins is cheap; if late, consolidation matters.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // If many bins are open with large mean residual, opening another is wasteful.
        score += open_bins_count as f64 * 2.0;
        score += mean_residual * 0.3;
        // If the item is huge relative to capacity, a fresh bin is more acceptable.
        score -= (item_size as f64 / bin_capacity as f64) * 40.0;
    }

    // Mild preference for tighter existing bins beyond raw post_residual.
    score += (bin_residual as f64 / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Dead space = residual too small to ever fit any item (min item size 1 here,
        // so treat "very small" gaps as low-utility: <= 10 nearly unusable).
        if post_residual <= 10 {
            score += 60.0; // hard penalty for creating near-dead space
        } else if post_residual <= 25 {
            score += 25.0 * (1.0 - (post_residual as f64 - 10.0) / 15.0);
        } else {
            // Larger gaps are progressively less penalized (still usable).
            score -= 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward bins whose residual is being well matched to the item (tight fit).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize new bins implicitly via this bin's score being lowered).
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score -= 20.0 * pressure * (item_size as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover: mild penalty for stranded space.
        score += 10.0;
    }

    // Early stream: keep bins flexible (favor larger residuals slightly);
    // late stream: pack tightly, accept imperfect fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 10.0 * (post_residual as f64 / bin_capacity as f64);
    score -= progress * 12.0;

    // Prefer bins below mean residual (i.e., emptier-than-average bins get used,
    // keeping tight bins for smaller future items) when many bins are open.
    if (bin_residual as f64) > mean_residual {
        score += 6.0;
    } else {
        score -= 6.0;
    }

    // New-bin candidate calibration: an empty bin gets a mild penalty so it is
    // only chosen when all open-bin scores are worse (poor fits / dead space).
    if bin_residual == bin_capacity {
        score += 18.0 - 10.0 * pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with superlinear penalty on waste.
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // 2-step lookahead: strongly reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff == 0.0 {
            score -= 40.0; // perfect chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            // next item still fits here: mildly reward closeness
            score -= 12.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize small unusable leftovers
            score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight" -> good to use.
    let rel = if mean_residual > 0.0 { bin_residual as f64 / mean_residual } else { 1.0 };
    score += 3.0 * (rel - 1.0); // penalize using bins with above-average residual

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let bad_fit = fitting_bins_count == 0
            || (next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 5);
        if bad_fit {
            score -= 10.0; // allow opening a new bin when open bins fit poorly
        } else {
            score += 25.0; // discourage wasting a fresh bin on a good existing fit
        }
    }

    // Late-stream pressure: consolidate more aggressively as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight preference to fill bins when many bins are open (reduce spread).
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty reduction as post_residual shrinks.
    let tight = (post_residual as f64 / bin_capacity as f64).powi(2);
    score -= 40.0 * (1.0 - tight);

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead-space penalty: residuals too small for the minimum item (1..=100 range, use 10 as
    // practical dead-space threshold but scale with stream progress since late-game
    // small residuals become more acceptable).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let dead_threshold = 10.0 * (1.0 - 0.5 * progress);
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 2.5;
    }

    // Lookahead coupling: reward residuals that can host the next item too.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Bonus if next item then fits almost perfectly.
            let double_left = post_residual - next_item_size;
            if double_left == 0 {
                score -= 25.0;
            }
        } else if bin_residual >= next_item_size && post_residual > 0 {
            // Placing current item blocks a better next-item fit; mild penalty.
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Crowding pressure: many open bins with high mean residual -> prefer consolidation
    // into existing bins rather than opening new ones.
    if open_bins_count > 2 {
        let pressure = (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64);
        score += pressure * (post_residual as f64 / bin_capacity as f64) * 5.0;
    }

    // New-bin candidate handling: empty bin gets a base handicap so we only open when
    // no open bin offers a decent fit; handicap shrinks late in the stream.
    if bin_residual == bin_capacity {
        score += 35.0 - 15.0 * progress;
        // Opening a bin is more attractive when mean residual of open bins is small
        // (they are nearly full) or very few bins exist.
        score -= (mean_residual / bin_capacity as f64) * 20.0;
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild time-horizon term: early in the stream, keep bins flexible (favor mid residuals);
    // late, just pack tightly.
    score += (1.0 - progress) * 3.0 * ((post_residual as f64 - 25.0).abs() / 25.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Normalized post-residual: unusable dead space measure
    let x = pr / cap; // 0..1

    // Non-linear dead-space penalty: quadratic growth, dead space near full bins is cheap,
    // dead space in mostly-empty bins is expensive.
    let dead_penalty = 40.0 * x * x + 10.0 * x;

    // Best-fit reward: strongly favor minimal post-residual (smooth, non-linear)
    let tight_reward = -60.0 * (1.0 - x) * (1.0 - x) * (1.0 - x);

    // Lookahead coupling: if the next item fits the post-residual exactly or well,
    // reward this placement; if post-residual is too small for next item, penalize.
    let lookahead = if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            -35.0 * (1.0 - slack) * (1.0 - slack)
        } else {
            let miss = (nx - pr) / cap;
            25.0 * miss * miss
        }
    } else {
        0.0
    };

    // Stream-progress coupling: early in the stream, keep bins open loosely (favor new bins
    // to preserve flexibility); late in the stream, consolidate aggressively.
    let progress_shift = progress * (1.0 - progress) * 4.0; // peak mid-stream
    let openness_bonus = if is_new_bin { -18.0 * (1.0 - progress) } else { 0.0 };

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    let last_chance = if fitting_bins_count == 1 && !is_new_bin { -45.0 } else { 0.0 };

    // New-bin penalty grows with number of open bins and mean residual (avoid bin proliferation
    // when open bins still hold space)
    let new_bin_penalty = if is_new_bin {
        30.0 + 4.0 * open_bins_count as f64 + 20.0 * (mean_residual / cap)
    } else {
        0.0
    };

    // Mean-residual coupling: when open bins are collectively full, using them is good.
    let crowd_term = if !is_new_bin { -8.0 * (mean_residual / cap) * (mean_residual / cap) } else { 0.0 };

    let mut score = pr
        + dead_penalty
        + tight_reward
        + lookahead
        + openness_bonus * progress_shift
        + last_chance
        + new_bin_penalty
        + crowd_term;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let res_mod = post_residual % 10;

    // Penalize dead space that is unusable for typical items: post_residual < 10 is perfect (0),
    // small odd residuals (1..9) are near-dead space.
    if post_residual == 0 {
        score -= 40.0; // perfect fit, excellent
    } else if res_mod != 0 {
        // residual not aligned to decade grid: harder to fill later
        score += (10 - res_mod) as f64 * 0.8;
    }

    // Fraction-of-capacity classes for post_residual
    let frac = post / cap;
    if frac < 0.10 {
        score -= 10.0; // nearly full bin: great
    } else if frac > 0.50 {
        score += 15.0; // leaving more than half empty is wasteful
    }

    // Harmonic coupling with next item: if next_item_size exactly matches post_residual,
    // this is a chain fit -> strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // next item also fits here: reward proportionally to how well it fills
            let next_fill = next_item_size as f64 / post as f64;
            score -= 20.0 * next_fill;
            // modulo harmony: (post_residual - next_item_size) aligned to decade grid
            let chain_res = post_residual - next_item_size;
            if chain_res % 10 == 0 {
                score -= 8.0;
            }
        } else {
            // next item won't fit in this bin; penalize if this bin becomes low-utility
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline so it only wins
    // when open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 12.0;
        // opening early in the stream is cheaper (more items left to fill it)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // if next item is large, a fresh bin may serve it better
        if next_item_size > 50 {
            score -= 6.0;
        }
    }

    // Prefer filling bins whose residual is far below mean residual (tightest bins)
    score -= (mean_residual - post).max(0.0) * 0.3;

    // Integer-division threshold: post_residual / item_size ratio class
    if item_size > 0 {
        let ratio = post_residual / item_size;
        if ratio == 0 {
            score -= 5.0; // item dominates residual: tight fit
        } else if ratio >= 3 {
            score += 10.0; // item small relative to leftover: poor packing
        }
    }

    // Mild pressure against bin proliferation
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (minimum item size = 1, but practically small gaps) are
    // wasted capacity. Penalize small-but-nonzero post_residual heavily,
    // while rewarding exact fits (post_residual == 0).
    if post_residual == 0 {
        score -= 60.0; // perfect fit is always ideal
    } else if post_residual < 10 {
        score += 80.0; // tiny unusable sliver -> strong penalty
    } else if post_residual < 25 {
        score += 30.0; // marginal gap
    } else if post_residual < 50 {
        score -= 5.0; // moderate usable space
    } else {
        score -= 10.0; // large residual, still flexible
    }

    // If the lookahead item can exactly fill the post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // lookahead fits: reward proportional to how well it uses the gap
        let fill = next_item_size as f64 / post_residual as f64;
        score -= 15.0 * fill;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item cannot use this gap -> mild penalty for hoarding space
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins; prefer
    // filling existing bins when bin count is already high.
    let pressure = open_bins_count as f64 / (bin_capacity as f64 / item_size.max(1) as f64);
    score += pressure * 2.0;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize a fresh bin slightly so it's chosen only when fits are poor,
    // but ease the penalty late in the stream when consolidation matters.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 - 10.0 * progress;
    }

    // Prefer bins whose residual is close to the item (tight fit quality).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness;

    // Slight preference for bins below mean residual (tighter bins first).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (dead space minimization)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0 + (5 - post_residual) as f64 * 10.0;
    }

    // 2-step lookahead: reward when post_residual matches next item size exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else {
            let gap = if post_residual > next_item_size {
                post_residual - next_item_size
            } else {
                (next_item_size - post_residual) as f64 * 0.5
            };
            // Small leftover that can't host the next item is dead space
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.8;
            } else {
                score -= gap as f64 * 0.3;
            }
            // Bonus if next item fits snugly into post_residual (small slack)
            if post_residual >= next_item_size && (post_residual - next_item_size) <= 5 {
                score -= 80.0;
            }
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - post_residual as f64) * -0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize creating tiny unusable residuals (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // New-bin candidate: baseline attractiveness; open a new bin only when
    // existing fits are poor (large post_residual or dead-space penalties).
    if bin_residual == bin_capacity {
        score = 120.0 + post_residual as f64 * 0.5;
        // Late in stream, be more reluctant to open new bins
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += progress * 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize dead space that no plausible future item can use:
    // smallest item is >= 1, so residual below ~1 is perfect; otherwise
    // penalize residuals that are too small relative to typical items.
    if post_residual > 0 {
        let unusable = (post_residual as f64).ln().max(0.0);
        score += 6.0 * unusable;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin (chained perfect packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: mild penalty for stranding space
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 10.0 * t;
    }

    // New-bin candidate logic: opening a new bin is penalized when open bins
    // exist with decent mean residual, but encouraged early or when open bins
    // are all nearly full.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        let mean_r = if open_bins_count > 0 { mean_residual } else { 0.0 };
        // penalty grows with number of open bins having usable space
        score += 25.0 + 3.0 * open_f * (mean_r / bin_capacity as f64);
        // early stream: new bins are cheap; late stream: conserve bins
        score -= 20.0 * (1.0 - t);
        // if next item is large, a fresh bin is valuable
        if next_item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Mild pressure to fill fuller bins when many bins are open.
    score -= (bin_residual as f64 / bin_capacity as f64) * 2.0 * (open_bins_count.min(50) as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, big leftover space is tolerable; late in the stream it becomes costly.
    let progress_weight = 0.5 + 2.5 * progress * progress;
    score += progress_weight * (pr * pr) / cap;

    // Reward tight fits (small post_residual) with a smooth saturating bonus.
    let tightness = 1.0 - pr / cap;
    score -= 12.0 * tightness * tightness * tightness;

    // Lookahead coupling: if the next item fits the post residual, reward this bin.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 6.0 * progress;
    } else if next_item_size > 0 {
        // Dead space relative to next item: penalize proportionally to mismatch.
        let mismatch = (pr - next_item_size as f64).min(cap);
        score += 3.0 * (mismatch / cap) * (mismatch / cap) * 100.0 / cap;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty proportional to number of open bins to encourage consolidation.
    score += 0.15 * open_bins_count as f64;

    // Coupling with mean residual: bins already loose get a nudge to absorb items.
    score -= 0.05 * mean_residual * progress;

    // New-bin candidate: keep it neutral-to-slightly-high so only genuinely
    // bad fits among open bins trigger opening a new bin.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality by integer division thresholds
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let frac = pr / cap;

    // Class 1: tiny dead space (<10) -> excellent, strong reward
    if post_residual < 10 {
        score -= 40.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Class 2: harmonic band 10..=25 -> moderate
    else if post_residual <= 25 {
        score -= 12.0;
    }
    // Class 3: awkward band 26..=45 -> penalize (too big to ignore, too small for most items)
    else if post_residual <= 45 {
        score += 15.0 + (45 - post_residual) as f64 * 0.5;
    }
    // Class 4: large residual >45 -> fine, mildly reward
    else {
        score -= 5.0;
    }

    // Modulo arithmetic on post_residual: residues divisible by common item sizes pair well
    if post_residual > 0 {
        let r = post_residual;
        if r % 10 == 0 { score -= 8.0; }
        else if r % 5 == 0 { score -= 4.0; }
        else { score += (r % 5) as f64 * 1.5; }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 { score -= 20.0 - gap as f64; }
            else { score += gap as f64 * 0.3; }
        } else {
            // next item cannot fit here; residual becomes final dead space
            score += pr * 0.4;
        }
    } else {
        // last item: any residual is pure waste; minimize it aggressively
        score += pr * 1.5;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / cap).max(0.0);
        score = cap * 0.55 + (1.0 - pressure) * 25.0;
        if fitting_bins_count == 0 { score -= 50.0; }
        if next_item_size > 0 && next_item_size > bin_capacity - item_size.min(bin_capacity) {
            score += 10.0;
        }
    }

    // Stream progression: late in stream, tighten bins harder
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += t * 10.0;
    // Many open bins: discourage spreading, favor filling existing ones
    score += open_bins_count as f64 * 0.8;
    // Mean residual coupling: when mean residual is low, waste matters more
    score += (mean_residual - pr) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=9) are almost unusable
    // for items >= 10, so punish them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual as i32) as f64 * 6.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else {
        // Larger leftover space is more reusable; mildly reward it.
        score -= (post_residual as f64).sqrt() * 2.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Open-bin pressure: discourage spreading across many open bins,
    // prefer filling existing bins when the stream is long.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.5 + 3.0 * progress);

    // Deviation from mean residual: prefer bins that are already low
    // (close to full) relative to the average.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            // Next item cannot use the leftover gap; penalize creating it.
            score += (post_residual as f64) * 0.5;
        }
    }

    // New-bin candidate handling: an empty bin is a fresh resource.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by pressure of
        // existing open bins and how bad the current fits are.
        score = 120.0 + open_bins_count as f64 * 2.0;
        // If no existing bin is a decent fit (all would leave tiny gaps),
        // make the new bin attractive.
        if post_residual == bin_capacity - item_size {
            // this is the new-bin call itself; cheapen when item is large
            // and would waste little space.
            score -= (item_size as f64 / bin_capacity as f64) * 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 80.0; // must open a new bin anyway
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0; // new bin can also host the next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can exactly or nearly host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-chain: consume residual fully across two items.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward proportional fit, penalize leftover slack quadratically.
            score -= 30.0 - slack * 0.25 + slack * slack * 0.02;
        } else {
            // Next item won't fit here after placement: penalize by gap size.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.35;
        }
    } else {
        // Last item: prefer tightest fit only.
        score += 0.0;
    }

    // Tightness reward: smaller post_residual relative to capacity is good.
    score -= (bin_capacity - post_residual) as f64 * 0.15;

    // Compare against mean residual: a bin far below mean residual is
    // already well-utilized; prefer filling those further.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.20;
    } else {
        score += (res - mean_residual) * 0.10;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Discard creating tiny unusable slivers (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // New-bin candidate handling: only attractive when no open bin is
    // decently fittable or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = open_bins_count as f64;
        // Penalize opening new bins mildly; relax when many bins are open
        // and mean residual is high (fragmentation is already bad).
        let mut new_bin_score = 45.0 + progress * 10.0;
        if mean_residual < item_size as f64 {
            new_bin_score -= 15.0; // fragmented state: fresh bin is useful
        }
        if open_bins_count > 0 && fitting_bins_count > 0 {
            new_bin_score += open_pressure * 0.5;
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items,
    // but reward residuals that could fit a mid/small item later.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 25.0 * (10.0 - pr) / 10.0; // near-dead space penalty
        } else if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            score -= 15.0; // can also host the lookahead item
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bins get a moderate baseline so we
    // only open a new bin when no open bin fits decently.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in the stream, opening bins is cheaper (more future use).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    }

    // Lookahead coupling: if the next item would not fit the post residual
    // but would fit a fresh bin, penalize consuming this bin awkwardly.
    if next_item_size > post_residual as u32 && next_item_size > 0 {
        score += 5.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Global state: many open bins with high mean residual -> prefer reusing
    // existing capacity rather than opening new bins.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 4.0 * (mean_residual / bin_capacity as f64);
    }

    // Slight preference for bins with residual close to item + next item sum.
    if next_item_size > 0 {
        let target = item_size as f64 + next_item_size as f64;
        let diff = (bin_residual as f64 - target).abs();
        score += 0.15 * diff;
    }

    // Mild noise-free tiebreak: prefer fuller bins (smaller residual).
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: penalize wasted space, non-linearly
    let mut score = pr as f64;

    // Smooth non-linear coupling of wasted space with stream progress.
    // Later in the stream, tight fits matter more -> amplify penalty on large residuals.
    let poly = x * x * (1.0 - x) + x * x * x; // smooth bump peaking mid-range
    score += 60.0 * progress * poly;

    // Reward near-full fits (small post residual) more strongly as stream advances
    score -= 25.0 * progress * (1.0 - x) * (1.0 - x);

    // Coupling with mean residual: prefer bins whose residual deviates favorably
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * (0.5 + progress);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - x);
    }

    // Lookahead: reward if next item fits well into the resulting residual
    if next_item_size > 0 && (next_item_size as f64) <= x * cap {
        let slack = x * cap - next_item_size as f64;
        score -= 15.0 * (1.0 - slack / cap) * (0.3 + 0.7 * progress);
    } else if next_item_size > 0 {
        // penalize leaving residual that nothing useful can use
        score += 8.0 * x * (0.5 + 0.5 * progress);
    }

    // Mild penalty for spreading across many open bins late in the stream
    score += (open_bins_count as f64).ln() * 2.0 * progress;

    // New-bin candidate: prefer opening a fresh bin only when current fits are poor
    if bin_residual == bin_capacity {
        score = 30.0 + 50.0 * (1.0 - progress) - 20.0 * (fitting_bins_count as f64).recip();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of small denominators) are more likely to be
    // filled by future items, so reward them (subtract), penalize dead zones.
    let pr = post_residual;
    let mut class_bonus = 0.0;
    if pr > 0 {
        if pr % 10 == 0 {
            class_bonus -= 6.0; // perfectly divisible leftover, highly reusable
        } else if pr % 5 == 0 {
            class_bonus -= 3.0;
        } else if pr % 25 == 0 {
            class_bonus -= 5.0;
        } else if pr <= 5 {
            class_bonus -= 8.0; // near-perfect fit
        } else if pr < 10 {
            class_bonus += 12.0; // dead space: nothing (>=10... or >=1) may fit well
        }
        // mid-range leftovers 30..60 are the most flexible for unknown streams
        if pr >= 30 && pr <= 60 {
            class_bonus -= 4.0;
        }
        if pr > 80 {
            class_bonus += 6.0; // huge leftover means poor utilization of this bin
        }
    } else {
        class_bonus -= 15.0; // perfect closure of the bin
    }
    score += class_bonus;

    // Lookahead coupling: does the next item fit the post-residual exactly or well?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0; // next item closes this bin perfectly
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            if gap <= 5 {
                score -= 10.0;
            } else if gap % 10 == 0 {
                score -= 6.0;
            } else {
                score -= 2.0 * (1.0 - gap as f64 / cap);
            }
        } else {
            // next item cannot follow here; penalize proportionally to overflow
            score += ((next_item_size - pr) as f64 / cap) * 8.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // among many options, prefer tightest (already via post_residual) but
        // slightly discourage spreading across too many open bins
        score += (open_bins_count as f64) * 0.35;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: high, but discounted when current
        // fit would create dead space or when bins are getting fragmented.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut open_cost = 30.0 - 10.0 * progress;
        // If placing here would leave awkward leftover, opening a fresh bin
        // becomes more attractive (its post_residual = cap - item_size, a
        // clean slate).
        if pr > 0 && pr < 10 {
            open_cost -= 12.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            open_cost -= 6.0; // new bin can also host the next item
        }
        score += open_cost;
    }

    // Mild normalization against mean fragmentation across open bins.
    score += (mean_residual - post_residual as f64) * 0.05;

    // Small harmonic jitter on item size class to break ties deterministically.
    score += ((item_size % 7) as f64) * 0.05 - 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=9) are almost useless for future
    // items (min size 10 in classic regime, but sizes 1..100 possible) — penalize
    // heavily when the gap falls into the "dead zone" below the smallest plausible
    // useful leftover.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0 + 6.0 * (10 - post_residual) as f64; // tiny unusable slivers
    } else if post_residual > 9 && post_residual <= 20 {
        score += 12.0; // marginal gap, mildly wasteful
    }

    // Reward near-perfect fills strongly (sub-linear so 0 residual dominates).
    if post_residual == 0 {
        score -= 100.0;
    } else {
        score -= 40.0 * (1.0 - pr / bin_capacity as f64).powf(3.0);
    }

    // Tightness relative to residual: prefer bins where item consumes most of the gap.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * fit_ratio;
    }

    // Open-bins pressure: many open bins -> discourage spreading, favor consolidating
    // into existing bins; few open bins -> new bins are cheap.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 4.0 * pressure * (1.0 - fit_ratio);

    // New-bin candidate: only attractive when residuals across open bins are large
    // (item fits poorly everywhere) or no open bin fits well.
    if bin_residual == bin_capacity {
        let mean_fit = item_size as f64 / mean_residual.max(1.0);
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { (fitting_bins_count as f64).recip() };
        let poor_elsewhere = ((mean_fit - 1.0).max(0.0)) * 40.0;
        let early_discount = 1.0 - (step_index as f64 / (total_items.max(1) as f64)).min(1.0) * 0.3;
        score = 55.0 + 20.0 * scarcity - poor_elsewhere * early_discount;
        // Never open a new bin if a perfect or near-perfect fit exists.
        if fit_ratio > 0.95 { score += 200.0; }
    }

    // Lookahead: if next item would fit exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strong bonus when item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Near-perfect fit: small residuals are valuable; scale by tightness.
    if post_residual > 0 && post_residual <= 10 {
        score -= 40.0 + (10 - post_residual) as f64 * 3.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 120.0 - slack as f64 * 8.0;
            } else {
                // Penalize leaving a gap that next item can't meaningfully use.
                score += slack as f64 * 0.4;
            }
        }
    }

    // Relative to mean residual: bins tighter than average are precious,
    // prefer filling them; bins looser than average absorb overflow.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.8;
    } else {
        score += (res - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin for an awkward item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: keep it expensive so we prefer existing bins,
    // but cheaper late in the stream or when open bins are all loose.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_tight = mean_residual / bin_capacity as f64;
        score += 200.0 - progress * 60.0 - avg_tight * 80.0;
    }

    // Mild penalty for creating very large dead space relative to capacity.
    let dead = res / bin_capacity as f64;
    if dead > 0.5 {
        score += (dead - 0.5) * 100.0;
    }

    // Prefer consolidating into fewer bins when many are open.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: squared post-residual penalty scaled down.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Small-dead-space zone reward (post_residual <= 10 is nearly unusable).
    if post_residual > 0 && post_residual <= 10 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Crowding: many open bins -> prefer filling existing ones.
    let crowding = (open_bins_count as f64).ln().max(0.0);
    score += crowding * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Mean residual coupling: if this bin's residual is below mean, it's a good filler.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.5;
    } else {
        score += (res - mean_residual) * 0.2;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Next item won't fit here; penalize large leftover slightly.
            score += (post_residual as f64 - next_item_size as f64).abs() * 0.1;
        }
    }

    // Time horizon: late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate logic: only attractive when this bin is empty and
    // existing bins are fragmented (high mean residual, poor fit here).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let poor_fit = (bin_residual - item_size) as f64;
        let pressure = (open_bins_count as f64 * fragmentation).powi(2);
        score = 120.0 + poor_fit * 0.3 - pressure * 5.0 - progress * 30.0;
        // If the item fills a new bin well, opening is cheap.
        if item_size >= 80 {
            score -= 40.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling: normalized post-residual squared/curved terms
    let x = pr / cap; // normalized residual in [0,1]
    score += 40.0 * x * x * (1.0 - x); // penalize mid-size waste, favor near-full fits

    // Stream progress coupling: waste matters more as stream progresses
    let progress_w = t * t;
    score *= 1.0 + 1.5 * progress_w;

    // Reward tight fits with smooth falloff
    let fit_tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_tightness * fit_tightness;

    // Last-chance bonus (smooth)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - x);
    }

    // Lookahead: favor bins whose leftover could fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let compat = if pr >= nx { (pr - nx) / cap } else { 0.0 };
        score -= 20.0 * compat * (1.0 - compat);
    }

    // Mild diversity pressure: many open bins -> prefer filling existing
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * x;

    // New-bin candidate: prefer opening a fresh bin only when existing fits are poor
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * (1.0 - t) - 20.0 * (1.0 - x);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity fractions (1/8 granularity) and reward tight, "composable" leftovers.
    let eighth = bin_capacity as f64 / 8.0;
    let class = (post_residual as f64 / eighth).floor().min(8.0);

    // Dead-space penalty: residuals that no plausible item (1..=80) can fill well.
    // post_residual in 1..=9 is nearly unusable -> heavy penalty; post_residual == 0 is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 9 {
        score += 300.0;
    } else if post_residual <= 20 {
        score += 60.0;
    }

    // Reward residuals in "harmonic" sizes that combine well: exact multiples of
    // small units (10, 20, 25, 50) are reusable by future items.
    let pr = post_residual;
    if pr % 10 == 0 { score -= 40.0; }
    if pr % 20 == 0 { score -= 25.0; }
    if pr % 25 == 0 { score -= 20.0; }
    if pr % 50 == 0 { score -= 30.0; }

    // Modulo-4 class coupling: even/odd alignment between item and leftover.
    if (item_size + post_residual) % 4 == 0 {
        score -= 10.0;
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            let next_left = post_residual - next_item_size;
            if next_left <= 10 { score -= 80.0; }
            else { score -= (post_residual - next_item_size) as f64 * 0.5; }
        } else {
            // next item won't fit here anyway; penalize large leftovers slightly more
            score += class * 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Prefer fuller bins over emptier ones when many bins are open (consolidation).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 30.0;

    // New-bin candidate: make it unattractive unless open bins are all poor fits
    // (i.e., large mean residual spread or few fitting bins). A fresh bin has
    // post_residual == capacity; keep its score near "neutral high".
    if bin_residual == bin_capacity {
        // base cost of opening a bin, modulated by stream progress and load
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 250.0 + 50.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: new bin is necessary
        }
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 40.0; // big next item benefits from fresh capacity
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: heavily penalize small unusable gaps.
    // A residual that cannot fit even the smallest plausible item is wasted.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual < 30 {
        score += 5.0;
    } else {
        // Larger residuals are more reusable: mild reward scaling sub-linearly.
        score -= (post_residual as f64).sqrt() * 0.5;
    }

    // Perfect fit bonus: strongly reward leaving zero residual.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: reward residuals that can still fit the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0; // gap too small for lookahead item
    }

    // Open bins pressure: discourage opening/spreading when many bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bin count.
        score += open_bins_count as f64 * 3.0;
        // But allow new bin when existing fits are poor (many fitting bins = fragmentation).
        if fitting_bins_count > 0 && post_residual >= 50 {
            score -= 5.0;
        }
    } else {
        // Reward using existing bins, more when bin count is high.
        score -= open_bins_count as f64 * 0.5;
    }

    // Last-chance bin: strongly prefer filling the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (i.e., tighter bins get priority, keeping loose bins flexible).
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    // Early stream: be slightly greedy about tight fits; late stream: fill aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual == 0) as i32 as f64 * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits with small slack
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 25.0 * (1.0 - slack as f64 / bin_capacity as f64);
    }
    // Next item does NOT fit: penalize proportionally to wasted lookahead potential
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 + 0.3 * (next_item_size - post_residual) as f64;
    }

    // Penalize tiny unusable dead space strongly (non-linear)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - 3.0 * post_residual as f64;
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Reward bins tighter than the mean residual (best-fit orientation)
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Progress-based pressure: late in stream, prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.4;

    // New-bin candidate: penalize opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        let good_fit_exists = next_item_size > 0
            && fitting_bins_count > 0
            && open_bins_count > 0;
        if good_fit_exists {
            score += 70.0;
        } else {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual is consumed well.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.85 {
        score -= 25.0 * fit_ratio;
    } else if fit_ratio > 0.6 {
        score -= 10.0 * fit_ratio;
    }

    // Penalize large post-residuals that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // near-perfect fill
    }
    if post_residual >= 10 && post_residual < 30 {
        score += 5.0; // awkward dead zone
    }

    // Lookahead coupling: if the next item fits the post-residual, reward.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0;
            // Exact chain fit bonus
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; penalize wasted residual relative to next item
            let waste = post_residual as f64 - (post_residual as f64 % next_item_size.max(1) as f64);
            score += 0.15 * waste;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is expensive early/late.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 45.0; // base penalty so existing bins usually win
        // Open a new bin if existing residuals are fragmented relative to item.
        if mean_residual < item_size as f64 * 1.05 && fitting_bins_count > 0 {
            new_bin_score -= 20.0;
        }
        // Late in stream, prefer consolidating into open bins.
        new_bin_score += 20.0 * progress;
        // Many open bins: discourage opening more.
        new_bin_score += 2.0 * open_bins_count as f64;
        // If no bin fits well, new bin becomes attractive.
        score = new_bin_score;
    }

    // Mild global pressure: when mean residual is low, squeeze existing bins.
    score -= 0.05 * mean_residual;

    // Slight preference for bins with residual close to item (avoid overshoot).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr;

    // Non-linear waste penalty: dead space that is too small to be useful is worse.
    let unusable = {
        let t = pr / cap;
        t * t * (1.0 - t)
    };
    let mut score = base + 40.0 * unusable * cap;

    // Perfect fit reward, scaled by stream progress (tighter packing late in stream).
    let tightness = 1.0 - (pr / cap);
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * progress;
    }

    // Lookahead coupling: reward residual that still fits the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 10.0 * (1.0 - (pr - ni) / cap);
        } else {
            score += 8.0 * (ni - pr) / cap;
        }
    }

    // Prefer filling bins when many bins are open; new-bin candidate gets a mild
    // penalty that grows with open_bins_count, softened late in the stream.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64 * (1.0 - progress);
    }

    // Mean-residual coupling: penalize deviating from the fleet average.
    score += 0.1 * (pr - mean_residual).abs();

    // Smooth progress interaction: quadratic in progress damps late-stream risk aversion.
    score *= 1.0 - 0.15 * progress * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Dead-space penalty: residuals in (0, 10) are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic class buckets on capacity fraction: residuals that are
    // integer-division-friendly (multiples of common item classes 10, 20, 25, 50)
    // are more likely reusable.
    let reusable = post_residual % 10 == 0 || post_residual % 25 == 0;
    if reusable {
        score -= 8.0;
    } else {
        score += 6.0;
    }

    // Lookahead coupling: reward if next item fits the post residual exactly
    // or within a harmonic class.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 45.0;
            } else if gap < 10 {
                score -= 15.0;
            } else {
                score -= 10.0 * (gap as f64 / cap);
            }
        } else {
            // Next item cannot use this bin's leftover: penalize large wasted space.
            score += 0.15 * pr;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // (high mean residual consumption) or item is large relative to capacity.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap; // higher = emptier open bins
        let item_frac = item_size as f64 / cap;
        // Penalize new bin when open bins are fairly empty; reward when tight.
        score += 40.0 * (1.0 - pressure) - 20.0 * item_frac;
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // Late in stream, avoid opening bins for small items.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - item_frac) * (1.0 - progress);
    }

    // Mild preference for filling fuller bins (tighter packing) as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 12.0 * (1.0 - frac) * (0.5 + 0.5 * progress);

    // Small tie-break toward bins whose residual is close to mean (balance).
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (small slivers unlikely to host future items) are heavily penalized.
    let dead_zone_lo = 1.0f64;
    let dead_zone_hi = 12.0f64;
    let pr = post_residual as f64;
    if pr > 0.0 && pr <= dead_zone_hi {
        // Peak penalty near the smallest residuals, tapering to zero at the band edge.
        let t = 1.0 - (pr - dead_zone_lo) / (dead_zone_hi - dead_zone_lo);
        score += 30.0 * t * t;
    }

    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits relative to bin capacity.
    score -= 10.0 * (item_size as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Open-bin pressure: discourage proliferation of bins; new empty bin
    // (bin_residual == bin_capacity) gets this pressure too, but a genuinely
    // full-ish usage of existing bins offsets it via the fit rewards above.
    score += 1.5 * open_bins_count as f64;

    // Mild pressure from mean residual: prefer bins below the mean residual
    // (pack fuller bins), leave larger-residual bins for bigger items.
    score += 0.5 * (mean_residual - post_residual as f64);

    // Lookahead: if the next item fits the post-residual exactly-ish, reward;
    // if post-residual is just barely too small for the next item, penalize.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n && pr - n <= 10.0 {
            score -= 6.0; // next item slots in snugly
        } else if pr > 0.0 && pr < n {
            score += 4.0 * (1.0 - pr / n); // dead space relative to next item
        }
    }

    // Slight early-stream conservatism: keep bins flexible early on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residual too small to hold even the smallest item (1)
    if post_residual == 0 {
        score -= 25.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score -= 12.0; // near-perfect fit, barely unusable space
    } else {
        score += 3.0; // mild penalty for leaving moderate slack
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // chain fit: this placement enables a perfect follow-up
        } else if next_item_size < post_residual {
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            // next item cannot use the remaining space: penalize proportionally
            let waste = (next_item_size - post_residual) as f64;
            score += 2.0 + 5.0 * (waste / bin_capacity as f64);
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are badly fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 - 10.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        // discourage new bin if an open bin fits reasonably well
        if bin_residual >= item_size && fitting_bins_count > 0 && post_residual <= 20 {
            score += 40.0;
        }
    }

    // Late-stream consolidation: tighten packing as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: later on, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Relative fill of this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    let post_ratio = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits (small post_residual relative to capacity).
    score -= 40.0 * (1.0 - post_ratio) * (0.5 + progress);

    // Penalize dead space that no future item (10..80 range) can use:
    // residuals below 10 are pure waste; residuals just above a small item are fine.
    if post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual > 80 {
        // Large residual is flexible; mild reward, stronger early in the stream.
        score -= 15.0 * post_ratio * (1.0 - progress);
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // Next item fits: residual is reusable.
            score -= 20.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item will NOT fit here: this placement strands residual
            // relative to the immediate future.
            score += 12.0 + 0.2 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item of the stream: minimize waste only.
        score += 0.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 55.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is justified when the item is large or the fit
        // elsewhere is terrible. Penalize opening new bins by default,
        // scaled by how many bins are already open and mean residual availability.
        let mean_usable = mean_residual / bin_capacity as f64;
        score += 35.0
            + 5.0 * open_bins_count as f64 * (1.0 - progress)
            + 30.0 * mean_usable;
        // But if the item is huge, a fresh bin is natural.
        if fill_ratio > 0.7 {
            score -= 45.0;
        }
    }

    // Prefer bins whose residual deviates from the mean in a useful way:
    // bins tighter than average are more precious, use them when they fit.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 25.0 * dev * (0.3 + 0.7 * progress);

    // Mild preference for fewer open bins (consolidation), stronger early.
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr_norm = pr / cap; // 0..1 normalized post residual
    let pr2 = pr_norm * pr_norm;
    let pr3 = pr2 * pr_norm;
    // Early in the stream: tolerate large residuals slightly less (keep bins flexible);
    // late in the stream: strongly prefer small post residuals (tight packing).
    let w_early = (1.0 - progress) * (1.0 - progress);
    let w_late = progress * progress;
    score += 8.0 * w_late * pr2 * cap;
    score -= 6.0 * w_early * pr2 * cap;
    // Smooth cubic interaction: reward very tight fits more as stream progresses.
    score -= 10.0 * progress * pr3 * cap;

    // Dead-space penalty: post residual that cannot fit the next item is wasted.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let unusable = ((nx - pr) / cap).max(0.0);
        let unusable2 = unusable * unusable;
        score += 12.0 * unusable2 * cap * (0.5 + 0.5 * progress);
        // Smooth bonus if post residual is a near-perfect cradle for the next item.
        let fit_gap = (pr - nx).abs() / cap;
        score -= 5.0 * (1.0 - fit_gap) * (1.0 - fit_gap) * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    } else if fitting_bins_count > 2 {
        // Many alternatives: mildly penalize to prefer best-fit discrimination.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Coupling with mean residual: prefer bins whose post residual stays near the mean
    // early (balance flexibility), but deviate toward tight fits late.
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * cap * (1.0 - progress);
    score -= 2.0 * dev.abs() * progress;

    // Mild penalty on spreading across many bins early (encourage consolidation).
    score += 0.4 * open_bins_count as f64 * (1.0 - progress) * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residue modulo 10 as a "waste quantum".
    let residue = post_residual;
    let harm = (residue % 10) as f64;
    // Penalize leftovers that are not multiples of 10 (dead space that small items can't cleanly fill).
    score += harm * 0.9;

    // Integer-division threshold classes on post_residual.
    if residue == 0 {
        score -= 30.0; // perfect fit
    } else if residue < 10 {
        score += 25.0; // unusable sliver
    } else if residue <= 20 {
        score += 6.0;  // only tiny items fit
    }

    // Fraction-of-capacity classes: leftover bucket via integer division.
    let bucket = residue / 25; // 0..4
    score += bucket as f64 * 4.0;

    // Lookahead coupling: does the next item fit harmonically into the post-residual?
    if next_item_size > 0 {
        if next_item_size == residue {
            score -= 40.0; // next item exactly fills this bin
        } else if next_item_size < residue {
            let nxt_res = residue - next_item_size;
            // Reward if next placement also leaves a multiple-of-10 residue.
            if nxt_res % 10 == 0 { score -= 12.0; }
            score += (nxt_res % 10) as f64 * 0.5;
        } else {
            // Next item won't fit here; mild penalty scaled by overshoot class.
            score += ((next_item_size - residue) / 10) as f64 * 1.5;
        }
    } else {
        // Last item: prefer exact fills strongly.
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: neutral-ish baseline, but prefer opening a new bin
    // when existing bins would leave bad harmonic residues.
    if bin_residual == bin_capacity {
        // Fresh bin: score = post_residual (= cap - item), adjusted by item class.
        score -= 8.0;
        // Penalize opening new bins late in the stream slightly less (stream effect).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 2.0;
    }

    // Mean-residual coupling: if open bins are generally tight, prefer reusing.
    score -= (mean_residual / cap) * 3.0;

    // Modulo coupling between item size and capacity thirds.
    if (item_size % 50 == 0) && residue % 50 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    // Treat residuals in (0, 10] as pure dead space and penalize them heavily,
    // scaled by how "unusable" they are relative to the smallest plausible item.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0) + 15.0;
    } else if post_residual > 10 && post_residual < 20 {
        // Marginal zone: partially usable, mild penalty
        score += 12.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    }

    // Reward tight fits (low post_residual) super-linearly.
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 25.0 * tightness * tightness;

    // Perfect fit: exact fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless the fit would create dead space.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        if post_residual <= 10 {
            score += 20.0; // dead space in last bin still bad, but new bin is worse
        } else {
            score -= 35.0;
        }
    }

    // Open-bin pressure: discourage scattering across many bins; consolidate
    // when mean residual suggests there is room elsewhere.
    score += 2.0 * open_bins_count as f64;

    // If residual is far below mean residual, this bin is already cramped;
    // prefer bins closer to the mean residual for balanced packing.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly favor this placement (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            // next item would create dead space here; mild penalty
            score += 8.0;
        }
    }

    // New-bin candidate handling: an empty bin has maximal residual. Only
    // prefer it when no existing bin offers a decent fit; make the empty-bin
    // baseline score moderately high so tight fits in open bins win.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Late in the stream, opening fresh bins is more acceptable (fewer
        // future items to consolidate into).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via non-linear post-residual shaping.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: residuals that are too small to hold even the
    // smallest plausible future item are wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual exists but cannot fit next item: penalize proportionally.
        score += 8.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is attractive only when
    // global residual pressure is high or the current item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = mean_residual / bin_capacity as f64;
        let large_item_bonus = (item_size as f64 / 100.0) * 15.0;
        score += 20.0 + 15.0 * (1.0 - pressure) - large_item_bonus - 10.0 * progress;
    } else {
        // Slight preference for bins already below mean residual (balancing).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    // Fragmentation-aware term: bins with mid-range residuals are versatile,
    // bins with tiny residuals are nearly dead.
    let r = post_residual as f64;
    if r > 0.0 {
        let versatility = ((r - 50.0).abs()) / 50.0;
        score += 6.0 * versatility * versatility;
    }

    // Mild scaling with open bin count: discourage spreading across many bins
    // early, allow more dispersion later in the stream.
    let horizon = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - horizon) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Smooth polynomial coupling: residual value decays non-linearly with stream progress
    let progress_decay = 1.0 - 0.6 * t * t - 0.2 * t * t * t;
    score *= progress_decay;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + t);

    // Penalize large dead space quadratically, amplified by mean residual context
    score += 0.05 * norm_pr * norm_pr * cap * (1.0 + mean_residual / cap);

    // Last-chance bin bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + t);
    }

    // Lookahead: reward leaving room for the next item smoothly
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let room = pr / (n + 1.0);
        let room_fit = if room >= 1.0 { 1.0 } else { room };
        score -= 5.0 * room_fit * room_fit;
    }

    // Mild penalty for spreading across many open bins late in the stream
    score += 0.3 * (open_bins_count as f64).ln() * (0.5 + t);

    // New-bin candidate adjustment: prefer opening new bin when residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).tanh();
        score -= 6.0 * fragmentation * (1.0 - t) + 2.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: the fuller the bin becomes, the better (steeper than linear).
    let fill_frac = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 45.0 * fill_frac.powi(4);

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Dead-space penalty: small nonzero residual is likely unusable by future items.
    if post_residual > 0 && post_residual < 12 {
        score += 35.0;
    }

    // Harmonic classes: partition post_residual into residue classes mod 10.
    // Residuals just below a "round" capacity fraction (e.g. 50, 100 boundaries)
    // are more reusable; penalize awkward residue classes.
    let class = post_residual % 10;
    score += 2.5 * class as f64;
    // Integer-division thresholds: residual in [25,50) vs [50,75) vs [75,100)
    let band = post_residual / 25;
    score += match band {
        0 => 6.0,   // tiny residual: nearly dead
        1 => 0.0,   // mid residual: okay
        2 => -4.0,  // large residual: roomy
        _ => -2.0,
    };

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Lookahead coupling (k=2): reward if the next item also fits after placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.25 * next_item_size as f64;
        } else {
            // Next item won't fit here; leaving a large orphan residual is worse
            // than a tight one.
            if post_residual > 0 && post_residual < next_item_size {
                score += 6.0;
            }
        }
    }

    // Mild pressure against hoarding many half-empty bins.
    score += 0.4 * mean_residual * (open_bins_count as f64).sqrt() / 15.0;

    // New-bin candidate (empty bin): rebase score, discourage early in stream,
    // encourage only when nothing fits or stream is nearly done.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = post_residual as f64 + 28.0 - 12.0 * progress;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: must open
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: unusable small gaps are heavily penalized.
    // A gap is "dead" if it cannot fit even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 6.0;
    }

    // Reward near-perfect packing (post_residual == 0 is ideal).
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead-space check against lookahead: if the leftover can't fit the next
    // item, the gap is likely wasted; penalize proportionally.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Reward bins whose residual is large enough to still be useful later.
    if post_residual >= next_item_size && next_item_size > 0 {
        score -= 10.0;
    }

    // Open bins pressure: when many bins are open, prefer tightening existing
    // bins rather than spreading; penalize placements that leave slack.
    let open_pressure = open_bins_count as f64;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64) * 4.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current bins would leave bad dead space. Make the empty-bin baseline
    // moderately unattractive so it's chosen only for poor fits.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Exception: if no open bin fits (this is the only candidate), the
        // new bin is unavoidable; the last-chance branch doesn't apply here.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild stream-progression coupling: late in the stream, tighten more
    // aggressively to close out open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 * 0.15);

    // Prefer bins tighter than the mean residual (they are closer to closing).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but not too tight (dead space).
    if post_residual == 0 {
        score -= 1000.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score -= 300.0; // near-perfect fit, likely dead space anyway
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // next item will perfectly fill this bin
        } else if post_residual >= next_item_size {
            // next item still fits: reward proportional to leftover after it
            let two_step_left = post_residual - next_item_size;
            score -= 0.5 * (two_step_left as f64);
            if two_step_left == 0 {
                score -= 400.0;
            }
        } else {
            // next item won't fit here: penalize small unusable remainder
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.4 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // penalize new bin unless item is large relative to capacity
        score += 50.0 + 0.5 * (item_size as f64);
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    } else if bin_residual == bin_capacity {
        score -= 100.0; // first bin of the stream
    }

    // Late in the stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already favored via base score.
    // Penalize dead space that no future item can plausibly use.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead coupling: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use leftover space: penalize proportionally to waste.
        score += 0.35 * post_residual as f64;
    }

    // Last-chance bonus: only one bin fits; avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 8.0 + 10.0 * (item_size as f64 / bin_residual as f64);
    }

    // Penalize creating very small unusable residuals unless near-perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // dead space trap
    }

    // Prefer bins with below-mean residual (tighter bins) slightly.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: mildly discourage opening new bins early,
    // more acceptable when open bins are fragmented (high mean residual spread).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - bin_capacity as f64 / (open_bins_count.max(1) as f64)).abs();
        score += 6.0 - 4.0 * progress - 0.05 * fragmentation;
    }

    // Time horizon: late in the stream, consolidate aggressively.
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = norm_post * norm_post * (1.0 - norm_post) * (1.0 - norm_post);
    score += 40.0 * poly * (0.5 + progress);

    // Reward tight fits more strongly as stream progresses.
    let tightness = 1.0 - norm_post;
    score -= 25.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Penalize dead space that cannot fit the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post < nx {
            score += 15.0 * (nx - post) / cap * (1.0 + progress);
        } else {
            score -= 8.0 * (1.0 - (post - nx) / cap) * norm_post;
        }
    } else {
        score -= 10.0 * tightness;
    }

    // Last-chance bin bonus.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - norm_post);
    } else if fitting_bins_count > 2 {
        score += 5.0 * (fitting_bins_count as f64 - 2.0).min(3.0) * norm_post;
    }

    // Spread-aware penalty: avoid fragmenting bins when mean residual is low.
    let mean_gap = (mean_residual - post).abs();
    score += 6.0 * mean_gap / cap * (0.5 + progress);

    // Mild penalty for opening new bins early vs late.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 4.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into modulo classes.
    let class = post_residual % 10;
    let class_bonus: f64 = match class {
        0 => 8.0,   // perfect class: residual divisible by 10, highly reusable
        5 => 5.0,   // half class
        2 | 4 | 6 | 8 => 2.5, // even class
        _ => 0.0,   // odd/awkward class
    };
    score -= class_bonus;

    // Integer-division threshold on post_residual: small residuals are dead space.
    let q = post_residual / 20; // coarse harmonic band
    if q == 0 && post_residual > 0 {
        score += 15.0; // residual < 20 is nearly unusable
    } else if q == 1 {
        score += 5.0;
    }

    // Lookahead: does the next item fit in post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
        // exact fit for next item is ideal
        if next_item_size == post_residual {
            score -= 12.0;
        }
    } else if next_item_size > 0 {
        // next item does not fit here; penalize wasting a good bin
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish but should only win when open bins are bad.
    if bin_residual == bin_capacity {
        // prefer new bin only if mean residual across open bins is tiny
        score = 60.0 - mean_residual * 0.8 - (fitting_bins_count as f64) * 2.0;
        if post_residual >= 50 {
            score -= 10.0;
        }
    }

    // Progress coupling: late in stream, prefer tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 4.0;

    // Penalize bins whose residual deviates strongly from mean (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible future item (typical item range 1..100, but small fragments
    // below ~10 are hard to reuse) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps below half the minimum typical item are semi-dead.
    if post_residual > 0 && post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward fits that leave room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if lookahead fits *snugly* (small leftover after it).
        let after_next = post_residual - next_item_size;
        if after_next <= 10 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual can't hold the next item: mild dead-space penalty.
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new
    // bins and encourage consolidating into existing ones.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: pay the open-bin pressure tax.
        score += 25.0 + pressure;
        // Late in the stream, opening a new bin is less costly (fewer future
        // items to fill it), so relax the tax as the stream progresses.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * progress;
        // If no existing bin fits well (large post_residual everywhere),
        // opening a new bin becomes attractive.
        if mean_residual > 0.0 && (bin_residual as f64 - mean_residual) > 30.0 {
            score -= 10.0;
        }
    } else {
        // Existing bin: reward choosing it, scaled by how much it reduces
        // mean residual (i.e., it's one of the fuller bins).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
        score -= pressure * 0.5;
    }

    // Prefer bins whose post_residual stays reusable (>= 30 covers most items).
    if post_residual >= 30 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: penalize wasted space relative to capacity.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste * waste;

    // 2-step lookahead: strongly reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0; // perfect chain: fills bin completely over two steps
        } else if next_item_size <= post_residual {
            let leftover = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - leftover / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin: penalize proportionally to overshoot.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 20.0 * (overshoot / bin_capacity as f64);
        }
    }

    // Reward tight fits of the current item.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Compare against mean residual: bins with residual below mean are scarcer — favor filling them.
    score -= 10.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // Early in the stream, be more willing to open new bins for large items (keep flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when item is large or stream is young.
        score -= 15.0 * (item_size as f64 / bin_capacity as f64);
        score -= 10.0 * (1.0 - progress);
    } else if progress < 0.3 && tightness < 0.5 {
        score += 15.0 * (1.0 - progress); // discourage sloppy fits early
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (waste minimization).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize large dead space, especially small residuals that become unusable (< 10).
    if post_residual < 10 {
        score -= 6.0; // perfectly sealed bin is good
    } else if post_residual <= 20 {
        score += 3.0; // awkward dead zone
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Lookahead: if the next item fits into post_residual, reward; else penalize.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 5.0 * (1.0 - (next_item_size as f64 / 100.0));
        } else {
            score += 2.0;
        }
    }

    // New-bin candidate handling: make empty bins attractive only when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = fit_ratio < 0.7;
        // Prefer new bin early or when existing bins would waste a lot.
        score -= if poor_fit { 4.0 + 4.0 * (1.0 - fit_ratio) } else { -6.0 };
        // Late in stream, consolidate instead of opening bins.
        score += 10.0 * progress;
        // Many open bins with slack: discourage new bins.
        if mean_residual > 40.0 && open_bins_count > 3 {
            score += 8.0;
        }
    }

    // Mild preference for fuller bins relative to global mean residual.
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    // Prefer bins that are already quite full (consolidation).
    let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 3.0 * fullness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;
    let fit_ratio = fitting_bins_count as f64 / (open_bins_count.max(1) as f64);

    let mut score = pr;

    // Smooth polynomial coupling of post-residual with stream progress
    let pr2 = norm_pr * norm_pr;
    let pr3 = pr2 * norm_pr;
    score += 12.0 * pr2 * (0.5 + progress) * cap;
    score += 8.0 * pr3 * cap;

    // Penalize dead space that no plausible next item can use (smooth)
    let usable = (norm_next - norm_pr).max(0.0);
    score += 20.0 * usable * usable * cap * (0.4 + 0.6 * progress);

    // Reward tight fits smoothly
    let tight = 1.0 - norm_pr;
    score -= 15.0 * tight * tight * norm_item * cap;

    // Last-chance bonus: prefer using a bin when few alternatives fit
    score -= 25.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio) * (1.0 + 0.5 * progress);

    // Mild preference for bins below/above mean residual depending on progress
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev * (0.3 + 0.7 * progress);

    // Slight bias against opening new bins early, stronger late
    let new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += new_bin * (8.0 + 30.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity wasted after placement
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac * waste_frac;

    // Harmonic class: post_residual buckets via integer division
    let class = post_residual / 10;
    score += match class {
        0 => -25.0,                       // near-perfect fit
        1 => -10.0,                       // good fit
        2 => -3.0,
        3 => 2.0,
        4 => 6.0,
        _ => 10.0,
    } as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: does next item fit the residual exactly?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let next_waste = post_residual - next_item_size;
            score -= 15.0 * (1.0 - next_waste as f64 / 100.0);
        } else {
            // next item cannot use residual: penalize proportionally
            score += 8.0 * (next_item_size as f64 / bin_capacity as f64);
        }
        // modulo harmony between next item and residual
        if post_residual > 0 && (next_item_size % 10) == (post_residual % 10) && next_item_size <= post_residual {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when current bin would leave big dead space
    if bin_residual == bin_capacity {
        let base = 25.0 + 0.4 * open_bins_count as f64;
        if post_residual as f64 > mean_residual.max(20.0) {
            score = base - 30.0; // prefer fresh bin over bad fit
        } else {
            score = base + post_residual as f64; // keep using open bins
        }
    }

    // Mild pressure toward consolidating bins over stream progression
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly useless.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0; // unusable dead space (min item is 1..100, but small gaps rarely fit)
        } else if post_residual <= 20 {
            score += 25.0;
        } else if post_residual <= 35 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward tight fits relative to bin residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Open-bin pressure: prefer consolidating into fewer bins when many are open.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - next_fit / bin_capacity as f64);
    }

    // New-bin candidate handling: an empty bin has neutral residual utility.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; overcome only if open bins fit poorly.
        score = 70.0 + (post_residual as f64) * 0.2;
        if fitting_bins_count == 0 {
            score -= 100.0; // no existing bin fits: must open new bin
        }
        // Late in the stream, discourage proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
