pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic bonus for small post-residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Penalize dead space that is too small for any plausible item (1..=100).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        // dead space that only small items can fill — mild penalty,
        // but reduced if the lookahead item can actually use it.
        let usable = next_item_size > 0 && next_item_size <= post_residual;
        if !usable {
            score += 12.0;
        } else {
            score -= 10.0;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this is a great chain placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large and fits poorly everywhere else.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit_elsewhere = fitting_bins_count == 0 || (fitting_bins_count == 1 && (bin_residual - item_size) < 10);
        if poor_fit_elsewhere {
            score -= 20.0; // opening new bin is justified
        } else {
            score += 15.0 + 25.0 * (1.0 - progress); // early on, prefer filling open bins
        }
        // Large items deserve fresh bins more than small ones.
        score -= 0.1 * item_size as f64;
    }

    // Global state: many open bins with high mean residual -> encourage
    // consolidating into existing space.
    let open_f = open_bins_count as f64;
    score += 0.05 * open_f * (mean_residual / bin_capacity as f64);

    // Time horizon: late in the stream, close out bins aggressively —
    // favor bins that end near-empty.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Prefer bins with residual close to item size (minimal waste ratio).
    let waste_ratio = post_residual as f64 / (bin_residual.max(1) as f64);
    score += 6.0 * waste_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Non-linear coupling with stream progress: tighten packing as stream advances
    let tight = 1.0 + 1.5 * progress * (1.0 - progress) * 2.0;
    score *= tight;

    // Reward near-perfect fits smoothly (dead-space penalty grows quadratically)
    score += 8.0 * norm_pr * norm_pr * cap * (0.2 + progress);

    // Last-chance bin: strongly favor using it when few fitting bins remain
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 + 20.0 * (1.0 - norm_pr);
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 6.0 * (1.0 - gap / cap);
        } else {
            score += 3.0 * (-gap / cap);
        }
    }

    // Penalize bins that deviate from mean residual (smooth variance pressure)
    score += 0.05 * (pr - mean_residual).abs();

    // Mild pressure against hoarding many open bins late in the stream
    score += 0.3 * open_bins_count as f64 * progress;

    // New-bin candidate: keep it neutral-to-slightly-costly so it's chosen
    // only when no open bin offers a good fit
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * progress - 4.0 * (fitting_bins_count as f64).recip();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: classify residual space by capacity fractions (1/4, 1/3, 1/2).
    let quarter = bin_capacity / 4;
    let third = bin_capacity / 3;
    let half = bin_capacity / 2;

    // Dead space: residuals too small to ever be useful (item sizes >= 1, but
    // classically tiny slivers are waste). Penalize residuals in (0, 10).
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    }

    // Reward landing in harmonic class boundaries: post_residual that is a
    // multiple of a common divisor class is more reusable.
    let class_bonus = if post_residual % 10 == 0 {
        40.0
    } else if post_residual % 5 == 0 {
        20.0
    } else if post_residual % 2 == 0 {
        8.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Reward residuals falling exactly on quarter/third/half thresholds.
    if post_residual == quarter || post_residual == half || post_residual == third {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        if post_residual == next_item_size {
            score -= 200.0;
        } else {
            let gap = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        }
    } else if next_item_size > post_residual {
        // Next item cannot use this bin's leftover; mild penalty scaled by waste.
        score += 0.3 * post_residual as f64;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: make empty bins moderately attractive only when the
    // current item is large and no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        if item_size > half && (post_residual as f64) < 0.25 * bin_capacity as f64 {
            score -= 80.0;
        } else {
            score += 100.0;
        }
    }

    // Slight progression term: later in the stream, tighten packing more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (10)
    // are pure waste; penalize them heavily with a super-linear ramp.
    let dead = if post_residual < 10 { (10 - post_residual) as f64 } else { 0.0 };
    score += dead * dead * 2.0;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 15.0;

    // Perfect (zero-waste) fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // but allow it early in the stream or when few bins exist.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 8.0 - progress * 10.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a forced new-bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Dead space is worse if it can't host the lookahead item either.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size * 2 {
        score -= 10.0; // leaves a usable slot for the next item
    }

    // Slight pull toward bins with residuals near the mean (balanced packing).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    // Penalize leaving gaps in the awkward 11..=19 range (hard to fill later).
    if post_residual >= 11 && post_residual <= 19 {
        score += (19 - post_residual) as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (zero waste).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Reward small post residuals non-linearly (best-fit core).
        score -= 50.0 / (post_residual as f64).sqrt();
    }

    // 2-step lookahead: reward if the next item exactly fills the post residual,
    // penalize if the leftover is "almost" but not exactly usable by the next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0; // chain a perfect second placement
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 / (1.0 + slack);
        } else {
            // Next item cannot use the leftover: dead space likely.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.3 * overshoot;
        }
    }

    // Compare against mean residual: placing into a bin whose residual is far
    // below average preserves large residuals elsewhere (harmonic-style).
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 0.5 * (mean_residual - resid_f);
    } else {
        score += 0.5 * (resid_f - mean_residual);
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins fit poorly (large post residual) or few bins are open.
    if bin_residual == bin_capacity {
        let best_existing_penalty = 150.0; // default cost of opening a new bin
        let pressure = if fitting_bins_count == 0 { 400.0 } else { 0.0 };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += best_existing_penalty - pressure - 100.0 * progress;
        // If current item leaves a large unusable gap in existing bins, new bin looks better.
        if post_residual == 0 {
            score -= 500.0; // fresh bin gives a "perfect" placement trivially
        }
    }

    // Mild penalty for scattering across many open bins when residuals are small.
    if open_bins_count > 4 && post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: later on, prefer tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let urgency = 1.0 + 2.0 * progress;

    // Reward small post-residuals, especially if they create "dead space"
    // that is hard for future items (post_residual < 10 is nearly unusable).
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0; // near-perfect fit: strong reward
    } else {
        score -= 8.0 / (1.0 + pr * 0.05);
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // this is a great placement; if next item leaves huge waste, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0 + 4.0 * (item_size as f64 / bin_residual as f64);
    }

    // Many open bins: discourage fragmentation; prefer filling existing bins.
    let load_factor = open_bins_count as f64 / (1.0 + total_items as f64 * 0.1);
    score += load_factor * urgency * 2.0;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a "small" bin; filling small bins first keeps large residuals
    // available for large items.
    let diff = mean_residual - bin_residual as f64;
    score -= diff * 0.2 * urgency;

    // New-bin candidate logic: penalize opening a new bin unless the item
    // is large and fits snugly (reserving it for big items).
    if bin_residual == bin_capacity {
        let snug = (bin_capacity - item_size) as f64;
        score += 15.0 - snug * 0.1;
        if item_size > 70 {
            score -= 10.0; // large items deserve fresh bins
        }
    }

    // Slight preference for bins whose residual is just above item size
    // (best-fit style), modulated by stream progress.
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * 0.05 * urgency;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: quadratic waste penalty on post-residual
    let mut score = pr + (pr * pr) / (cap * cap) * 30.0;

    // Cubic coupling with stream progress: late in the stream, waste hurts more
    let p3 = progress * progress * progress;
    score += p3 * (pr * pr) / cap * 0.8;

    // Reward tight fits (small post_residual) with smooth exponential term
    score -= (1.0 - pr / cap).powi(6) * 12.0;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * (1.0 - progress);
    }

    // Lookahead: bonus if the next item fits the resulting residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 6.0 * (1.0 - (pr - next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        // next item won't fit: penalize dead space proportionally
        score += 4.0 * (pr / cap) * (next_item_size as f64 / cap);
    }

    // Prefer bins below mean residual (consolidate fullness), smooth coupling
    score += 0.5 * (mean_residual - pr);

    // Slight preference for using existing bins over opening new ones early
    score += (pr / cap) * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 2.0;

    // New-bin candidate: make empty bins moderately attractive only for poor fits elsewhere
    if bin_residual == bin_capacity {
        score = 25.0 - 10.0 * progress + 0.3 * (item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 defines "usable slot class".
    let post = post_residual as i64;
    let cap = bin_capacity as i64;

    // Class 0 residuals (exact multiples of 10) are gold: heavily reward.
    let class = post % 10;
    if class == 0 {
        score -= 18.0;
    } else if class <= 2 || class >= 8 {
        // Near-miss classes: nearly reusable by typical small items, mild reward.
        score -= 4.0;
    } else {
        // Mid-class dead zones (3..7): penalize proportionally to residual size.
        score += 3.0 + 0.08 * (post as f64);
    }

    // Integer-division thresholds: can post_residual host the lookahead item?
    if next_item_size > 0 {
        let nxt = next_item_size as i64;
        if nxt <= post {
            score -= 10.0;
            // Perfect pair: post == next exactly, or post - nxt lands in class 0.
            if post == nxt || (post - nxt) % 10 == 0 {
                score -= 12.0;
            }
        } else {
            score += 6.0;
        }
    } else {
        // Last item: just minimize waste, prefer tightest fit.
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && post >= 0 {
        score -= 15.0;
    }

    // Fraction of capacity used: reward high fill fraction nonlinearly.
    let fill = (cap - post) as f64 / cap as f64;
    score -= 8.0 * fill * fill;

    // New-bin candidate handling: only attractive when nothing fits well.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        // Penalize opening a new bin unless stream is early or bins are crowded.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 14.0 - 10.0 * progress + 2.0 * (open_bins_count as f64).ln();
        if item_size > bin_capacity / 2 {
            score -= 6.0; // big items are fine in fresh bins
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 8.0; // fresh bin can host item + lookahead pair
        }
    } else {
        // Slight preference for existing bins relative to mean residual state.
        score -= 0.05 * (mean_residual - post as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for any future item
    // (items >= 1, but realistically >= 10..) are pure waste.
    let dead_threshold: f64 = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64);
    }

    // Tight-fit reward: small post_residual is good (first-fit-decreasing style).
    score -= 2.0 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward it;
    // if next item can't fit but post_residual is large, mild penalty.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            if (post_residual - next_item_size) < 10 {
                score -= 10.0; // chained tight fit
            }
        } else {
            score += 3.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize so we only open when open bins are truly bad.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if no existing bin fits well, allow new bin.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Prefer bins with residual below mean (consolidate large gaps).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Near-match: next item would still leave a small gap after the lookahead item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let lookahead_gap = post_residual - next_item_size;
        score -= 12.0 / (1.0 + lookahead_gap as f64);
    }

    // Penalize if next item cannot use the residual at all (dead space risk).
    if next_item_size > 0 && next_item_size > post_residual {
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Reward tight fits relative to mean residual of open bins.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.3;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize tiny unusable remnants (<10) that become dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Slight bias toward keeping few open bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    // New-bin candidate: neutral-ish baseline, only chosen when fits are bad.
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post-residuals non-linearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    // Perfect or near-perfect fill gets a strong bonus.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Dead-space penalty: residuals too small for the smallest item are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 / (1.0 + slack);
        } else {
            // Next item won't fit here: mild penalty proportional to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.3;
        }
    } else {
        // Last item: strongly prefer filling existing bins to the max.
        score -= 200.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let fit_quality = item_size as f64 / bin_residual as f64;
        if fit_quality > 0.5 {
            score -= 150.0 * fit_quality;
        } else {
            score += 30.0;
        }
    }

    // New-bin candidate logic: opening a new bin is only attractive when the item
    // fits poorly everywhere else or open bins are already fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        // Penalize new bins moderately; less so late in the stream or when fragmented.
        score += 60.0 - 40.0 * progress - 10.0 * fragmentation.min(5.0);
        // If the item is large relative to capacity, a fresh bin is natural.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 30.0;
        }
    }

    // Global pressure: when many bins are open with low mean residual, prefer
    // consolidating into existing bins.
    let consolidation_bonus = (mean_residual - post_residual as f64).abs();
    score += consolidation_bonus * 0.05;

    // Time horizon: early in the stream, be conservative with bins; late, pack greedily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual as f64 - post_residual as f64) * 0.2;

    // Slight preference for bins with more residual used so far (keeps emptier bins flexible).
    score += (bin_capacity as f64 - bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Normalized post-residual and its smooth polynomial shaping
    let r = post / cap;
    let r2 = r * r;
    let r3 = r2 * r;

    // Base: prefer small post-residual (tight fit), with non-linear curvature
    let mut score = post * (1.0 + 0.35 * r + 1.1 * r2 - 0.4 * r3);

    // Stream-progress coupling: early on tolerate larger residuals; later punish them
    let prog_coupling = 1.0 + 0.6 * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score *= prog_coupling;

    // Interaction: post_residual * progress polynomial (smooth, no piecewise)
    score += 8.0 * r2 * progress;
    score -= 5.0 * r * progress * (1.0 - progress);

    // Penalize bins whose post-residual cannot fit the next item
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 6.0 + 10.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        // Reward bins that will still be useful for the next item
        score -= 3.0 * (next_item_size as f64 / cap) * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // mild penalty spread across many candidates to break ties toward tight fits
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer bins below mean residual (already tighter than average)
    score += 1.5 * ((post - mean_residual) / cap);

    // New-bin candidate: make it mildly attractive early, expensive late
    if bin_residual == bin_capacity {
        score = 18.0 - 14.0 * (1.0 - progress) + 10.0 * progress;
        // discourage new bins when good existing candidates exist
        if fitting_bins_count >= 2 {
            score += 6.0;
        }
        if next_item_size > 0 && (post_residual as u32) < next_item_size {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are multiples of 10
    // (natural pairing classes for items sized 1..100), penalize odd residues.
    let post = post_residual as u32;
    let class = post % 10;
    if class == 0 {
        score -= 8.0;
    } else if class == 5 {
        score -= 3.0;
    } else {
        score += (10 - class) as f64 * 0.6;
    }

    // Lookahead: penalize if next item cannot fit in post_residual.
    if next_item_size > 0 {
        if next_item_size > post {
            score += 6.0 + (next_item_size - post) as f64 * 0.15;
        } else {
            // Reward if the leftover after the next item lands on a good class
            let next_left = post - next_item_size;
            if next_left % 10 == 0 {
                score -= 5.0;
            } else if next_left % 5 == 0 {
                score -= 2.0;
            }
            // tight fit for the next item is good
            if next_item_size as f64 >= 0.8 * post as f64 {
                score -= 4.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin would leave
    // tiny dead space or open bins are nearly full.
    if bin_residual == bin_capacity {
        score += 10.0;
        if post <= 5 {
            score -= 25.0; // almost perfect pack, definitely open new bin
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Fractional capacity coupling: reward tight fills.
    let fill_ratio = item_size as f64 / cap;
    score -= fill_ratio * 10.0;

    // Progress: as stream advances, prefer tighter bins (less room for error).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post as f64) * 0.05;

    // Prefer bins below mean residual (use fuller bins first).
    if (post as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space: residuals in (0, 10) are worthless,
    // residuals in (10, 20) are risky since min item is small but gap must match.
    let pr = post_residual as f64;
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // pure dead space
        } else if post_residual < 20 {
            score += 25.0; // marginal gap
        } else if post_residual < 30 {
            score += 8.0;
        }
    } else {
        score -= 30.0; // perfect fit, no waste
    }

    // Reward tight fits: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * tightness;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 + 2.0 * open_bins_count as f64;
    } else {
        score += 1.0 * open_bins_count as f64 * 0.1;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            score -= 5.0;
        } else {
            score += 10.0; // next item won't fit here; residual likely dead
        }
    }

    // Mean residual coupling: placing into a bin far below mean residual
    // (large residual) is good; avoid leaving outlier residuals.
    score += 0.3 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let mut score = post * 1.0;

    // Strongly reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post / cap);
    score -= tightness * tightness * 18.0;

    // Penalize dead space that cannot fit even the smallest plausible item (<= 1..100 unknown, use small threshold)
    if post > 0.0 && post < 12.0 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: if the next item fits the post-residual exactly or well, reward heavily
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let next_fit = 1.0 - (post - nxt) / cap;
            score -= next_fit * 22.0;
            if (post - nxt).abs() < 3.0 {
                score -= 15.0; // near-perfect two-item packing
            }
        } else {
            // next item won't fit here; slight penalty proportional to wasted opportunity
            score += 4.0;
        }
    }

    // Last-chance bonus: only this bin can fit the item
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Many fitting bins: this bin is not special; dampen its advantage slightly
    if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Prefer filling bins with low residual relative to the mean (consolidate waste)
    score += (post - mean_residual) * 0.15;

    // Time horizon: early in the stream, be more willing to open new bins (explore);
    // late in the stream, squeeze into existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0;          // later => favor existing bins
    score += (1.0 - progress) * 6.0;   // earlier => mild penalty for using existing bins

    // New-bin candidate handling: empty bin gets a base cost that tight fits elsewhere beat,
    // but which becomes attractive when the item is large and fits nowhere tightly.
    if bin_residual == bin_capacity {
        let mut new_bin_cost = 20.0;
        // Large items are hard to place later; open a fresh bin for them more readily
        new_bin_cost -= (item / cap) * 18.0;
        // If few bins can fit this item, opening fresh is safer
        if fitting_bins_count <= 1 {
            new_bin_cost -= 12.0;
        }
        // Late in stream, avoid opening new bins
        new_bin_cost += progress * 15.0;
        // Next item large too? reserve space in a fresh bin for both
        if next_item_size > 0 && (next_item_size as f64) + item <= cap {
            new_bin_cost -= 8.0;
        }
        score += new_bin_cost;
    }

    // Mild preference for bins with smaller current residual (fill nearly-full bins first)
    score += (bin_residual as f64 / cap) * 4.0;

    // Scale by number of open bins: too many open bins -> consolidate
    if open_bins_count > 8 {
        score += 2.0 * ((open_bins_count as f64 - 8.0).min(10.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: quadratic penalty on post residual (dead space), amplified over stream progress.
    let mut score = pr * pr / cap + pr * (0.5 + progress);

    // Strong reward for tight fits (near-zero post residual).
    let tightness = 1.0 - pr / cap;
    score -= 30.0 * tightness * tightness * tightness;

    // Last-chance bonus: strongly prefer the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when other bins can fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 20.0 + 10.0 * (fitting_bins_count as f64).ln();
        } else {
            score -= 5.0;
        }
    }

    // Lookahead coupling: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 8.0 * (nx / cap) * (1.0 - progress);
        } else {
            score += 3.0 * (nx / cap);
        }
    }

    // Mild penalty for spreading across many open bins; smooth non-linear coupling with mean residual.
    let mean_coupling = (pr - mean_residual) / cap;
    score += 2.0 * mean_coupling * mean_coupling;
    score += 0.5 * (open_bins_count as f64).sqrt();

    // Smooth progress-dependent fill pressure.
    score -= 5.0 * progress * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "large unusable" classes are penalized; small leftovers are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Integer-division thresholds on post_residual (harmonic classes of 10)
    let class = post_residual / 10; // 0..10
    match class {
        0 => score -= 18.0,           // near-perfect fit, tiny dead space
        1 => score -= 12.0,           // excellent
        2 => score -= 6.0,            // good
        3 => score -= 2.0,            // ok
        4 => score += 0.0,            // neutral
        5 => score += 3.0,            // half-empty bin, mediocre
        6 => score += 6.0,
        7 => score += 9.0,
        8 => score += 13.0,
        _ => score += 18.0,           // mostly empty, wasted slot
    }

    // Modulo-5 sub-class: leftovers that are multiples of 5 are more
    // "reusable" for typical item sizes; odd fragments are penalized.
    if post_residual % 5 == 0 {
        score -= 2.5;
    } else if post_residual % 2 == 0 {
        score -= 1.0;
    } else {
        score += 1.5;
    }

    // Lookahead coupling: does the leftover accommodate the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect-chaining bonus scaled by tightness of the chain
            let tightness = 1.0 - (post_residual as f64 - next_item_size as f64) / cap;
            score -= 8.0 + 6.0 * tightness;
        } else {
            // Leftover too small for next item: penalize proportionally to gap
            let gap = (next_item_size - post_residual) as f64;
            score += (gap / cap).min(1.0) * 5.0;
        }
    } else {
        // Last item: any bin works, prefer tightest fill (already via post_residual)
        score -= 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // existing residuals are fragmented (high mean residual relative to item)
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = cap * 0.85;
        // If current bin would leave a large awkward residual, new bin competes
        let awkward = pr / cap;
        score -= awkward * 30.0;
        // Few open bins => cheaper to open new bin (spreading load)
        score -= (open_bins_count as f64).ln().max(0.0) * 4.0;
        // Early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 8.0;
        // Next item is large: fresh bin may serve it better
        if next_item_size >= 50 {
            score -= 6.0;
        }
    } else {
        // Mild reward for using existing bins as open count grows
        score -= (open_bins_count as f64) * 0.15;
    }

    // Mean-residual context: when open bins are on average roomy, avoid
    // dumping items into already-tight bins (keep roomy bins roomy is bad,
    // so prefer placing into the bin closest to full -> handled by pr).
    let dev = (mean_residual - pr).abs() / cap;
    score += dev * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Mid-range dead space (10..=20) is moderately penalized since few item
    // sizes (>=10) can still use it productively.
    if post_residual >= 10 && post_residual <= 20 {
        score += 12.0;
    }

    // Perfect fit reward: strongly favor bins that are exactly filled.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bins pressure: more open bins => prefer reusing existing bins over
    // opening new ones, but only mildly so dead-space logic still dominates.
    score += open_bins_count as f64 * 0.35;

    // New-bin candidate handling: an empty bin has full residual. Penalize it
    // unless the current bin would leave a bad gap; the fixed penalty keeps
    // open-bin reuse preferred in typical cases.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Late in the stream, opening fresh bins is less attractive.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using
    // it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward
    // this placement (chaining good fits).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // If next item cannot fit in the post-residual but would fit an empty bin,
    // slightly penalize leaving a gap that strands the next item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 6.0;
    }

    // Prefer bins tighter than average (below-mean residual = good packing).
    score += (mean_residual - bin_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: exact fill leaves zero dead space.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: reward when the next item exactly matches the post residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 15.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        // Penalize if next item cannot fit into post residual (chain break risk),
        // unless post residual is tiny (acceptable dead space).
        if next_item_size as f64 > post_residual as f64 {
            score += 8.0 * (post_residual as f64 / 40.0).min(1.0);
        }
    }

    // Prefer bins already tighter than the mean residual (compact packing).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    // and lookahead suggests the fresh bin is more useful.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 50.0;
        let lookahead_wants_new = next_item_size > 0
            && (next_item_size as f64) > post_residual as f64
            && (next_item_size as f64) <= bin_capacity as f64;
        if poor_fit || lookahead_wants_new {
            score -= 20.0;
        } else {
            score += 30.0;
        }
    }

    // Slight preference to fill larger residuals early in the stream.
    score += 0.1 * (step_index as f64 / (total_items.max(1) as f64)) * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit: post residual below next item size is dead space unless tiny
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + (next_item_size - post_residual) as f64 * 0.15;
    }

    // Lookahead: reward bins whose residual after placement can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.1 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening bins unless existing fits are poor
    if bin_residual == bin_capacity {
        let prog = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 - 15.0 * prog;
        if item_size > 50 {
            score -= 10.0; // big items: fresh bin often good
        }
    }

    // Prefer bins with low residual relative to mean (fill emptier bins less)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Prefer bins with residual close to item size (best fit flavor)
    score += (bin_residual as f64 - item_size as f64).abs() * 0.2;

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Base: post residual, with non-linear polynomial shaping in progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Smooth coupling: penalize large post-residual less early, more late
    score += 20.0 * pr_norm * pr_norm * (1.0 - progress);

    // Reward tight fits with a smooth cubic term
    score -= 15.0 * (1.0 - pr_norm).powi(3) * (0.5 + 0.5 * progress);

    // Dead-space penalty: post-residual too small to ever fit (smooth soft barrier)
    let dead = ((item_norm * 0.5 - pr_norm) / (item_norm * 0.5 + 0.01)).max(0.0);
    score += 10.0 * dead * dead;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: smooth reward if next item fits the post-residual
    if next_item_size > 0 {
        let fits_next = (post_residual as i64 - next_item_size as i64) as f64;
        if fits_next >= 0.0 {
            score -= 8.0 * (1.0 - fits_next / cap);
        } else {
            score += 4.0 * (-fits_next / cap).min(1.0);
        }
    }

    // Mild preference for consolidating into fewer bins as stream progresses
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // Deviation from mean residual: prefer bins near average fill (smooth quadratic)
    score += 0.05 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // New-bin candidate: make it attractive only when post-residual would be large
    if bin_residual == bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Harmonic classes: reward post_residuals that are "usable" for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Next item fits here: strong reward scaled by tightness of the fit.
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 + 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Dead space for the lookahead item: penalize by how far off the residue class is.
        let gap = (next_item_size - post_residual) as f64;
        score += 4.0 + gap * 0.15;
    }

    // Modulo-10 harmonic banding of post_residual: residues 0..5 are prime targets,
    // residues 6..9 are awkward slivers (penalize progressively).
    let r = (post_residual % 10) as f64;
    if post_residual > 0 {
        if r <= 5.0 {
            score -= 3.0 - r * 0.4; // small residues (0..5) favored
        } else {
            score += (r - 5.0) * 0.6; // 6..9 slivers penalized
        }
    }

    // Integer-division thresholds: bins whose residual drops into the lowest
    // quarter of capacity are nearly closed — mild reward for finishing bins.
    if post_residual <= bin_capacity / 4 {
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the post fit would be terrible.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 14.0;
    }

    // New-bin candidate: default penalty so we only open when fits are poor.
    if is_new_bin {
        let mut penalty = 22.0 + 10.0 * progress;
        // If the item is large relative to capacity and nothing fits well, a fresh
        // bin becomes attractive: relax the penalty.
        if fitting_bins_count == 0 {
            penalty -= 30.0;
        }
        // If post_residual of the new bin leaves a large awkward remainder, discourage.
        if next_item_size > 0 && post_residual < next_item_size {
            penalty += 8.0;
        }
        score += penalty;
    }

    // Slight pressure toward consolidating bins when many are open.
    score += open_bins_count as f64 * 0.05;

    // Tie-break with mean residual: prefer bins that deviate toward tightness.
    score += (mean_residual - post_residual as f64) * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item (1..=9)
    // are effectively unusable; penalize them heavily.
    if post_residual < 10 {
        score += 200.0 * (10.0 - post_residual as f64);
    } else if post_residual <= 20 {
        // Small but potentially usable gaps: mild penalty to prefer tighter fits.
        score += 1.5 * (20.0 - post_residual as f64) as f64;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, tolerate spreading out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure;

    // Prefer bins whose residual is below the mean (tighter bins get filled first).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Lookahead: if the next item can use the post_residual exactly or nearly,
    // reward leaving that gap; otherwise penalize leaving a gap the next item
    // cannot use.
    if next_item_size > 0 {
        let gap = post_residual as f64;
        let n = next_item_size as f64;
        if n <= gap {
            let slack = gap - n;
            if slack < 10.0 {
                score -= 80.0 * (10.0 - slack); // next item fits snugly
            } else {
                score += 0.4 * slack; // next item leaves more dead space
            }
        } else {
            score += 0.5 * (n - gap); // next item cannot use this gap
        }
    }

    // New-bin candidate: only attractive when current item is large and
    // existing residuals are poor fits; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let base_penalty = 60.0 + 40.0 * (open_bins_count as f64).sqrt();
        let fit_scarcity = if fitting_bins_count == 0 { 0.0 } else { base_penalty };
        let large_item_bonus = if item_size > 50 { 30.0 } else { 0.0 };
        score += base_penalty + fit_scarcity - large_item_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // 2-step lookahead: reward when the next item exactly fills the remaining space.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for next item is highly desirable.
        score -= 40.0 * (1.0 - gap / bin_capacity as f64).max(0.0);

        // If next item fits exactly or leaves a tiny remainder, extra bonus.
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual {
            // Next item cannot follow here; penalize slightly more if gap is small
            // (wasted opportunity for perfect pairing).
            let miss = (next_item_size - post_residual) as f64;
            score += 0.3 * miss.min(30.0);
        } else {
            // Next item fits but leaves residual; penalize leftover dead space.
            let leftover = (post_residual - next_item_size) as f64;
            score += 0.15 * leftover;
        }
    }

    // Compare post_residual against mean residual: leaving below-average residual
    // means this bin becomes less useful than others; discourage extreme imbalance.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.10 * (pr - mean_residual);
    } else {
        score -= 0.05 * (mean_residual - pr);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has huge post_residual, which
    // naturally scores high (bad). Only allow it when open bins would be left
    // with very awkward residuals, or when there are no open bins.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 1000.0; // must open a bin
        } else {
            // Penalize new bins, but less when the stream is early (room to grow)
            // or when current bins have poor remaining utility.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 30.0 + 20.0 * progress;
        }
    }

    // Small bonus for using bins later in their life (more fragmented already).
    score -= 0.02 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / (bin_capacity as f64));
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space that next item cannot use: penalize proportionally.
        score += 0.5 * (post_residual as f64) / (next_item_size as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Penalize leaving residuals that are awkward (small but unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    // Prefer filling bins with larger-than-mean residuals (consolidate waste).
    score -= 0.3 * ((bin_residual as f64) - mean_residual);

    // Late in the stream: prefer closing bins tightly, discourage opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and many bins open.
        score += 10.0 + 15.0 * progress + 0.5 * open_bins_count as f64;
        // But if this bin would be filled nearly perfectly, allow it.
        if item_size >= bin_capacity - 2 {
            score -= 25.0;
        }
    } else {
        score -= 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap;

    // Core best-fit term with non-linear shrinkage: small residuals strongly favored.
    let mut score = x * x * (3.0 - 2.0 * x) * cap; // smoothstep on normalized residual
    score += 0.5 * post; // linear component

    // Polynomial coupling of post_residual with stream progress:
    // later in stream, residual waste matters more (amplified quadratically).
    let prog_amp = 1.0 + 2.0 * progress * progress;
    score += prog_amp * (x * x) * 10.0;

    // Reward tight fits relative to item size (coupling item & residual).
    let tightness = item_size as f64 / cap;
    score -= 20.0 * tightness * (1.0 - x) * (1.0 - x);

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 25.0 * progress;
    }

    // Penalize bins whose residual diverges from mean residual (keep pool balanced),
    // with smooth quadratic coupling.
    score += 0.05 * (post - mean_residual) * (post - mean_residual) / cap;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let fill = nx / post.max(1.0);
            score -= 12.0 * fill * fill;
        } else {
            score += 3.0;
        }
    }

    // New-bin candidate (empty bin): post_residual is large; add explicit penalty
    // that decays when few bins fit the item (forcing occasional new bins).
    if bin_residual == bin_capacity {
        score += 25.0 - 8.0 * (fitting_bins_count as f64).min(3.0);
        score += 10.0 * (1.0 - progress);
    }

    // Mild penalty for proliferating bins late in the stream.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" residue classes (<=10, or in [20,30]) are near-perfect fills.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: strongly reward
    } else if pr <= 10 {
        score -= 25.0; // dead space below minimum item size is harmless
    } else {
        // class = which capacity fraction band the leftover lands in
        let cls = pr / 10; // integer division threshold: 1..=9
        score += cls as f64 * 4.0;
        // leftover in [20,30] pairs well with mid-size items (30..40)
        if pr >= 20 && pr <= 30 && next_item_size >= 20 && next_item_size <= 30 {
            score -= 18.0;
        }
        // leftover in [50,60] pairs with large items
        if pr >= 50 && pr <= 60 && next_item_size >= 50 {
            score -= 15.0;
        }
        // odd/even harmonic: even residues chain better with even next items
        if pr % 2 == 0 && next_item_size % 2 == 0 && next_item_size > 0 && next_item_size <= pr {
            score -= 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize slightly so we prefer tight fits into open
    // bins, but allow opening when all open bins would leave bad residue.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + mean_residual * 0.3;
        // early in stream, opening bins is cheap; late, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 12.0;
        // if next item is large, a fresh bin is valuable
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Penalize bins far below mean residual (fragmented bins) mildly.
    if (bin_residual as f64) < mean_residual - 15.0 {
        score += 5.0;
    }

    // Reward using nearly-full bins (waste minimization via tightness ratio)
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item (min size 1..=10 typical) can
    // usefully fill are heavily penalized. A gap below the smallest plausible item
    // is pure waste; a zero gap is a perfect fit and gets a big reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score += 25.0; // nearly unusable sliver
    } else if post_residual < 10 {
        score += 15.0;
    } else if post_residual <= 20 {
        score += 6.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it before a new bin is opened.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., mean residual is small relative to the item).
    if bin_residual == bin_capacity {
        let tight_open = mean_residual / bin_capacity as f64;
        if tight_open < 0.15 {
            score -= 10.0; // open bins are nearly full; prefer a fresh bin
        } else {
            score += 18.0 + 10.0 * tight_open; // keep using open space
        }
    }

    // Mild preference for bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this residual: penalize dead space relative to next size
            score += 0.3 * (next_item_size as f64 - post_residual as f64).min(40.0);
        }
    } else {
        // Last item: minimize residual directly (already base), extra reward for exact fill.
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Relative-to-mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // Penalize opening new bins mildly; heavy penalty when open bins exist and fit.
        score += if open_bins_count == 0 { 0.0 } else { 35.0 + 10.0 * (open_bins_count as f64).sqrt() };
        if pressure > 0.0 {
            score -= 25.0; // no alternative: new bin is fine
        }
        // Late in stream, avoid opening bins unless really needed.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Penalize leaving tiny unusable residuals (unless next item matches them).
    if post_residual > 0 && post_residual < 10 && next_item_size != post_residual {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let dead = if next_item_size > 0 && post_residual >= next_item_size { 0.0 }
                   else { (post_residual as f64 / bin_capacity as f64).powf(0.5) };
        score += 25.0 * dead;
    }

    // Lookahead: if the next item fits exactly in the leftover, strongly reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Prefer bins with below-average residual (keep high-residual bins flexible).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Early in the stream: encourage consolidation into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // relative to all residuals or the fit here is very poor.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = mean_residual < item_size as f64 * 1.05;
        if poor_fit_elsewhere {
            score -= 20.0; // opening a fresh bin is fine when nothing fits well
        } else {
            score += 15.0 + 0.3 * mean_residual; // discourage wasteful new bins
        }
    }

    // Slight preference for filling larger residual bins when item is large.
    if item_size > bin_capacity / 2 {
        score -= 0.1 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let prn = pr / cap; // normalized post residual in [0,1]
    let p = progress;
    // Smooth polynomial interaction: weight dead space more as stream advances.
    let coupling = prn * prn * (0.5 + 1.5 * p) + prn * (1.0 - p) * 0.5;
    score += 20.0 * coupling;

    // Reward tight fits (small post_residual) with a smooth saturating term.
    score -= 15.0 * (1.0 - prn) * (1.0 - prn) * (1.0 + p);

    // Penalize opening a new bin unless current residuals are large.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        let mean_rn = (mean_residual / cap).clamp(0.0, 1.0);
        score += 25.0 * (1.0 - mean_rn) * (1.0 + p);
        // If a next item exists and current bin would be nearly full, opening is fine.
        if next_item_size > 0 {
            let nxt = next_item_size as f64 / cap;
            score -= 20.0 * prn * nxt;
        }
    } else {
        // Last-chance bin: strong reward to use it.
        if fitting_bins_count == 1 {
            score -= 18.0 * (1.0 - prn);
        }
        // Lookahead: reward if next item fits the post residual exactly-ish.
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            let waste = (post_residual - next_item_size) as f64 / cap;
            score -= 12.0 * (1.0 - waste);
        } else if next_item_size > 0 {
            score += 6.0 * prn;
        }
    }

    // Mild penalty for many open bins with large residuals to encourage consolidation.
    score += 0.05 * open_bins_count as f64 * mean_residual / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

