    // for typical item sizes (min size 1 in general, but small residuals waste).
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0; // perfect fit is ideal
    } else if pr <= 5 {
        score += 8.0; // tiny dead space: acceptable but not great
    } else if pr <= 10 {
        score += 15.0; // classic dead zone
    } else if pr <= 20 {
        score += 5.0;
    } else if pr <= 50 {
        score -= 3.0; // useful mid residual
    } else {
        score -= 6.0; // large residual keeps flexibility
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 40.0;
        } else if slack <= 10 {
            score -= 20.0;
        } else {
            score -= (slack as f64) * 0.2;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this residual; penalize proportional to mismatch.
        let miss = next_item_size - post_residual;
        score += (miss as f64).min(30.0) * 0.4;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless item is
    // large relative to capacity or current bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / 10.0;
        let big_item_bonus = if item_size >= bin_capacity / 2 { 10.0 } else { 0.0 };
        score += 30.0 + crowding * 3.0 - big_item_bonus - progress * 5.0;
        // If next item is small, new bin keeps room; slight discount.
        if next_item_size > 0 && next_item_size <= 20 {
            score -= 10.0;
        }
    }

    // Slight preference for bins whose residual is far from mean (keeps diversity).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    // Harmonic modulo bonus: residual divisible into nice chunks (multiples of 10/25)
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0) {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
