    // Mean residual coupling: if this bin is far below mean residual, it is a good dump target.
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Stream progression: later in stream, be more conservative about new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
