    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Smooth polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let prn = pr / bin_capacity as f64;
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;

    // Later in the stream, dead space is increasingly penalized (quadratic + cubic in progress).
    score += prn * (progress * 30.0 + prog2 * 40.0 + prog3 * 30.0);

    // Reward tight fits smoothly: subtract a bell-like term centered on small post_residual.
    let tight = (1.0 - prn).powi(6);
    score -= tight * (item_size as f64) * (0.5 + progress);

    // Lookahead coupling: if next item fits the post residual, reward this placement smoothly.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_frac = next_item_size as f64 / pr.max(1.0);
        score -= (1.0 - (fit_frac - 1.0) * (fit_frac - 1.0)) * 8.0 * (1.0 + progress);
    }

    // Last-chance bonus: penalize alternatives when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + prog2);
    } else {
        score += (fitting_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);
    }

    // Mean residual dispersion: prefer bins whose residual deviates from the mean smoothly.
    let dev = pr - mean_residual;
    score += dev * dev / (bin_capacity as f64 * bin_capacity as f64) * 10.0;

    // Mild penalty on opening many bins early; smooth in open_bins_count and progress.
    score += (open_bins_count as f64) * progress * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: how well it divides the capacity ---
    // Residuals that are exact divisors of capacity are "harmonic" and reusable.
    let pr = post_residual;
    if pr > 0 {
        let mut harmonic_bonus = 0.0;
        for d in [10u32, 20, 25, 50, 100, 80, 40] {
            if pr >= d && pr % d == 0 {
                harmonic_bonus += 6.0;
            }
        }
        // Small harmonic residuals (multiples of 10) are easy to fill later.
        if pr <= 30 && pr % 10 == 0 {
            harmonic_bonus += 8.0;
        }
        score -= harmonic_bonus;
    } else {
        // Perfect fit: best possible outcome.
        score -= 200.0;
    }

    // --- Dead space penalty: non-harmonic small residuals are wasted ---
    if pr > 0 && pr < 10 {
        score += 25.0; // tiny sliver, nearly unusable
    }

    // --- Lookahead coupling: does next_item_size fit the post-residual? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits perfectly-ish into this bin's remainder.
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 + 0.5 * (10.0 - slack.min(10.0));
            // Harmonic chain: next item leaves a multiple-of-10 residual again.
            if (pr - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here; penalize slightly, scaled by overflow gap.
            let gap = (next_item_size - pr) as f64;
            score += 0.3 * gap.min(40.0);
        }
    }

    // --- Capacity fraction thresholds on bin_residual (integer division) ---
    let quarter = bin_capacity / 4; // 25
    let half = bin_capacity / 2;    // 50
    if bin_residual / quarter >= 3 {
        // Bin is mostly empty; filling it now is valuable (avoid sprawl).
        score -= 5.0;
    } else if bin_residual < quarter {
        // Bin nearly full; finishing it off is good unless it creates slivers.
        score -= 4.0;
    }

    // --- Last-chance bin: strongly prefer using the only fitting bin ---
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Many options: reward tighter fits relatively more.
        score -= 3.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline penalty so it's only chosen when it beats
        // genuinely bad fits. Cheaper early in the stream, costlier late.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 40.0 + 30.0 * progress;
        // If next item is large, a fresh bin guarantees a home for it.
        if next_item_size > 0 && next_item_size >= half as u32 {
            new_bin_score -= 12.0;
        }
        // If many open bins already, discourage sprawl.
        new_bin_score += open_bins_count as f64 * 2.0;
        // Mean residual high => open bins have room; discourage new bin.
        new_bin_score += 0.2 * (mean_residual - cap * 0.5).max(0.0);
        score = score.max(0.0) + new_bin_score;
    }

    // --- Mean residual alignment: prefer bins close to the average state ---
    let drift = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * drift;

    // --- Progress-aware tightening: late in stream, waste is more costly ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized,
    // medium gaps (11..=25) mildly penalized, larger gaps are fine.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0;
        } else if post_residual <= 25 {
            score += 15.0;
        } else {
            score -= 10.0; // generous leftover space is a good outcome
        }
    } else {
        // perfect fill: strongly reward
        score -= 80.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Last chance before opening a new bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 5.0 * pressure;

    // New-bin candidate handling: only attractive when current bin would leave a tiny dead gap
    // or the item barely fits nothing well.
    if bin_residual == bin_capacity {
        let tiny_gap = post_residual > 0 && post_residual <= 10;
        if tiny_gap {
            score -= 20.0; // opening fresh bin avoids creating dead space here
        } else {
            score += 25.0; // prefer existing bins otherwise
        }
    }

    // Lookahead: if next item can exactly use the post_residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // post_residual too small for the next item: mild penalty (dead space likely)
        score += 8.0;
    }

    // Stream progression: late in stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when post_residual exactly or nearly
    // matches the next item size, so the follow-up item fills this bin too.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let match_bonus = (-gap / 20.0).exp(); // 1.0 at perfect match
        score -= 25.0 * match_bonus;

        // Penalize leaving a residual that is too small for the next item
        // (dead space) unless it is near zero.
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0 * (post_residual as f64 / next_item_size as f64);
        }
        // Perfect chain: next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item: strongly prefer minimal residual.
        score += 0.0;
        score -= 40.0 * tightness;
    }

    // Relative-to-mean coupling: prefer bins with residual below mean
    // (fill the emptier-for-this-item bins first, keep big residuals flexible).
    score += 0.15 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize opening a new bin when open bins could fit, unless residual
    // would be a very awkward dead space.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 10.0;
        // But a new bin is fine if it enables a perfect 2-step chain.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 30.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
    }

    // Mild penalty for very small unusable residuals (dead space < 10).
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 30.0;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual wasted relative to the known next item.
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: opening a new bin is attractive only when
    // mean residual across open bins is small (open bins are nearly full)
    // or the item fits badly everywhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = mean_residual / bin_capacity as f64;
        // Penalize opening new bins when open bins still have room.
        score += 20.0 + openness * 60.0 - progress * 10.0;
        // But if the item is large relative to mean residual, new bin less bad.
        let tight = (item_size as f64 / mean_residual.max(1.0)).min(2.0);
        score -= tight * 15.0;
    }

    // Prefer filling bins that deviate below mean residual (balance vs. consolidation).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Mild consolidation pressure as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize excessive bin proliferation mildly.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: tight fit is good (low post_residual lowers score).
    let mut score = pr;

    // Quadratic dead-space penalty, normalized by capacity.
    score += 0.9 * (pr / cap) * (pr / cap) * cap;

    // Cubic term: heavily punish mid-range wasted space, mildly tolerate near-full bins.
    let x = pr / cap;
    score += 25.0 * x * (1.0 - x) * (1.0 - x);

    // Stream-progress coupling: as the stream progresses, tighten preference for
    // near-perfect fits (multiply post_residual weight up), and reward using
    // existing bins more aggressively.
    let tight_bias = 1.0 + 0.8 * progress;
    score *= tight_bias;
    score -= 3.0 * progress * it / cap * 10.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Scarcity pressure: many open bins with high mean residual -> prefer filling
    // existing bins over opening new ones.
    let scarcity = open_bins_count as f64 * (mean_residual / cap);
    score -= 0.5 * scarcity;

    // Lookahead coupling: if the next item could use the post_residual exactly,
    // reward leaving that residual; otherwise penalize residuals close to next item size.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = (pr - ni).abs();
        score += 0.3 * gap;
        if pr >= ni {
            score -= 5.0; // residual is reusable by next item
        }
    }

    // New-bin candidate: penalize opening a new bin unless it's early in the stream
    // or the item is huge relative to typical residuals.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 60.0 * (1.0 - progress) - 20.0 * progress;
        score += new_bin_penalty.max(-30.0);
        // If no existing bin fits, opening is fine: fitting_bins_count==0 handled by caller,
        // but if only new bin fits item well, soften.
        if it / cap > 0.6 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: perfect fits (0), tiny slivers (1..=5),
    // and mid-range residuals that are "reusable" classes get strong rewards.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    if post_residual == 0 {
        score -= 60.0; // perfect fit — best possible outcome
    } else if post_residual <= 5 {
        score += 25.0; // dead sliver: unusable for typical items
    } else {
        // Reward residuals that fall into useful harmonic classes (multiples of 10/20),
        // which future items from a wide distribution can exploit.
        if post_residual % 10 == 0 {
            score -= 12.0;
            if post_residual % 20 == 0 { score -= 8.0; }
        }
        // Fraction-of-capacity coupling: residuals near 1/4, 1/3, 1/2 of capacity are versatile.
        let frac = pr / cap;
        if (frac - 0.25).abs() < 0.05 || (frac - 0.5).abs() < 0.05 {
            score -= 6.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Prefer bins whose leftover still accommodates the next item,
            // weighted by how snugly it fits (harmonic residue of the pair).
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
            if slack <= 5.0 { score -= 10.0; }
        } else {
            // Next item cannot use this leftover: penalize large stranded residuals.
            score += 0.05 * pr;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it moderately
    // attractive only when the current bin would leave a large, awkward residual.
    if bin_residual == bin_capacity {
        // Empty bin baseline: score proportional to wasted capacity of the first placement.
        score = 100.0 - item_size as f64;
        // If many bins are open and one is a tight fit, discourage spreading.
        if fitting_bins_count > 0 && item_size >= 50 {
            score += 15.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild pressure to prefer tighter bins overall via mean residual context.
    score += 0.02 * (mean_residual - pr).max(0.0);

    // Small tie-breaker toward bins with less residual before placement (tighter bins).
    score += 0.01 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than large leftovers.
    if post_residual > 0 {
        let gap = post_residual as f64;
        let min_item = 1.0f64;
        // A gap is "dead" if it is smaller than the smallest conceivable next item (min_item)
        // or too small to be useful relative to typical items.
        if gap < 10.0 {
            // Fully dead space: hard penalty proportional to tightness.
            score += (10.0 - gap) * 6.0;
        } else {
            // Usable gap: mild reward for tightness, but avoid over-fragmentation.
            score += gap * 0.15;
        }
        // Nonlinear penalty for gaps that no realistic item (1..=100) can usefully fill:
        // a gap just below a "typical" item band wastes capacity.
        if gap > min_item && gap < 20.0 {
            score += (20.0 - gap) * 1.5;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.3;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item cannot use this bin's gap: penalize leaving stranded space.
        score += (post_residual as f64) * 0.8;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones;
    // the new-bin candidate has bin_residual == bin_capacity, so penalize large residual
    // proportionally to open_bins_count.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 12.0 + 20.0;
        // Early in stream, opening bins is fine; later, very costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates below the mean
    // (tighter packing) when the mean is high (fragmented state).
    if mean_residual > 30.0 && bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score -= dev * 0.2;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 60.0;
        } else {
            score += diff * 0.6;
        }
        // If next item also fits after this placement, mild reward.
        if post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Dead-space penalty: small unusable post_residual (below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Exact fill of the bin is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: only one bin can fit the item -> favor it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize bins with residuals far below the mean (fragmented bins).
    let res = bin_residual as f64;
    if res < mean_residual {
        score += (mean_residual - res) * 0.3;
    } else {
        score -= (res - mean_residual) * 0.1;
    }

    // New-bin candidate: make it attractive only when current bin would leave big waste
    // or when no good fit exists (fitting_bins_count small and poor post-fit).
    if bin_residual == bin_capacity {
        // Baseline competitive score; open new bin if existing bins are poor fits.
        let waste = post_residual as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0; // don't open new bin if this bin chains nicely
        }
        if fitting_bins_count <= 1 {
            score += 100.0; // never open a new bin when it's the only option
        } else {
            score += waste * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is good; super-gauss coupling.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight.powi(4);

    // Penalize dead space: residuals too small for the minimum item (1) matter less,
    // but residuals in the awkward band (1..=10) are nearly unusable.
    if post_residual >= 1 && post_residual <= 10 {
        score += 6.0; // dead-space band
    }

    // Lookahead: if the next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain fit
        } else if next_item_size < post_residual {
            // next item fits, but how much slack remains after it?
            let chain_slack = post_residual - next_item_size;
            score -= 15.0 * (1.0 - chain_slack as f64 / bin_capacity as f64);
        } else {
            // next item would not fit here; slight penalty for wasting capacity
            score += 4.0;
        }
    }

    // Last-chance bonus: only one bin can fit this item — strongly prefer it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Time horizon: early in the stream, be conservative (favor opening bins to
    // keep flexibility); late in the stream, squeeze existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 12.0 * progress * tight;

    // Global state: many open bins with high mean residual -> encourage filling them.
    if open_bins_count > 2 {
        score -= 0.15 * (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate: an empty bin has perfect flexibility but wastes capacity
    // if open bins fit well. Penalize new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        let best_possible = post_residual as f64; // = capacity - item_size
        let _ = best_possible;
        // Poor fit if item leaves large residual AND other bins exist.
        let waste = item_size as f64 / bin_capacity as f64;
        score += 18.0 * waste; // big items in a fresh bin are fine, small items wasteful
        if open_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0; // fresh bin keeps room for the lookahead item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth polynomial coupling: penalize large post-residuals more as stream progresses
    let coupling = norm_pr * norm_pr * (0.5 + progress) * cap;
    score += 1.5 * coupling;

    // Reward tight fits (small post_residual) with a smooth quadratic bonus
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 20.0 * (1.0 + progress);

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 30.0 * gap * gap;
        // Reward leaving exactly enough room for the next item
        let fit_err = (pr - next_item_size as f64).abs() / cap;
        score -= 10.0 * (1.0 - fit_err) * (1.0 - fit_err) * norm_item;
    }

    // Last-chance bin: smooth reward scaled by scarcity of fitting bins
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + norm_item);
    } else {
        score += 5.0 / (fitting_bins_count as f64 + 1.0);
    }

    // Interaction with mean residual: prefer bins near the mean (smooth penalty on deviation)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Mild preference for filling existing bins as bins accumulate
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 4.0;

    // New-bin candidate: penalize opening a new bin unless residual is large
    if bin_residual == bin_capacity {
        score += 15.0 + 40.0 * (1.0 - progress) * norm_item;
        if next_item_size > 0 && (cap - item_size as f64) >= next_item_size as f64 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: classify by capacity fractions
    let frac = item_size as f64 / bin_capacity as f64;
    let item_class = if frac <= 0.25 { 0 } else if frac <= 0.5 { 1 } else { 2 };

    // Harmonic class of the resulting post_residual (dead space quality)
    let post_frac = post_residual as f64 / bin_capacity as f64;
    let dead_class = if post_frac <= 0.1 { 0 } else if post_frac <= 0.25 { 1 } else if post_frac <= 0.5 { 2 } else { 3 };

    // Reward exact harmonic fills: post_residual divisible into small classes
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else if post_residual % 10 == 0 {
        score -= 12.0; // dead space is a "clean" multiple of 10, reusable by common items
    }

    // Penalize dead space by its class
    score += match dead_class {
        0 => -6.0,
        1 => 0.0,
        2 => 8.0,
        _ => 18.0,
    };

    // Reward tight fits scaled by item class
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * (10.0 + 6.0 * item_class as f64);

    // Lookahead coupling: if next item fits the post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let lookahead_tight = next_item_size as f64 / post_residual as f64;
        score -= 14.0 + 10.0 * lookahead_tight;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 4.0; // dead space unlikely reusable
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer filling bins with small residuals relative to mean
    score += 0.15 * (post_residual as f64 - mean_residual).max(-30.0).min(30.0);

    // Modulo threshold logic on post_residual: penalize odd/prime-ish leftovers
    if post_residual % 2 == 1 && post_residual > 5 {
        score += 3.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 5.0; // tiny unusable sliver
    }

    // Late in stream: consolidate aggressively
    let progress = step_index as f64 / total_items as f64;
    score -= 10.0 * progress * (1.0 - post_frac);

    // Deter opening new bins when open bins exist that fit reasonably
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 + 3.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps too small to hold even the
    // smallest plausible item (<= 12) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0;
    }
    // Gaps that cannot fit the lookahead item are less useful than ones that can.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward perfect and near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }
    // Reward bins that can also host the lookahead item (chained fits).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 20.0 + 10.0 * pressure;
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * (1.0 - progress);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Prefer bins with residual below the mean (tighter packing consolidation).
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // 2-step lookahead: if next item exactly matches post_residual, big reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 25.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // Next item won't fit here: penalize dead space relative to gap.
            score += 0.5 * diff;
        }
    }

    // Compare post_residual against mean residual: avoid creating outliers.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when it enables a perfect 2-step chain
    // or no existing bin fits well; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && (bin_capacity as i64 - item_size as i64 - next_item_size as i64) == 0 {
            score -= 80.0;
        }
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual (waste) non-linearly.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        let waste = post_residual as f64 / bin_capacity as f64;
        score += waste * waste * 30.0;
    }

    // Lookahead coupling: if next item fits in post-residual, reward strongly.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 15.0 + 10.0 * (next_item_size as f64 / 100.0);
        } else if (post_residual as f64) < (next_item_size as f64) * 0.5 {
            // Dead space for the upcoming item; penalize.
            score += 8.0;
        }
    } else {
        // Last item: prefer filling existing bins completely.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 3 {
        score += 3.0 * (fitting_bins_count as f64 - 3.0).min(5.0);
    }

    // Time horizon: early on, allow opening new bins for better future packing;
    // late in the stream, strongly prefer existing bins.
    let horizon_bonus = (1.0 - progress) * 12.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, unattractive late.
        score += progress * 25.0 - horizon_bonus * 0.5;
        // Discourage new bins when many open bins already have room.
        if mean_residual >= item_size as f64 {
            score += 10.0;
        }
    }

    // Prefer bins with residual below mean (consolidate emptier space).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 2.0;
    }

    // Mild pressure against accumulating too many open bins.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // base: prefer low post_residual
    let mut score = pr;

    // smooth non-linear coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) * cap;
    score += coupling;

    // late-stream: penalize large residuals more strongly (waste compounds)
    let late = progress * progress * norm_pr * cap * 0.5;
    score += late;

    // last-chance bin reward: avoid opening new bins when only one fits
    if fitting_bins_count == 1 {
        score -= 20.0 + 30.0 * progress;
    }

    // lookahead: bonus if next item can use the post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= (1.0 - (pr - nxt) / cap) * 10.0;
        } else {
            score += 5.0;
        }
    }

    // prefer bins tighter than mean residual (good fit)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * cap * 0.3;

    // spread across many open bins: mild penalty for very full bins early
    score -= (open_bins_count as f64).ln().max(0.0) * norm_pr * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is divisible by
    // common item sizes are more reusable later.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward residuals that are "harmonic" (divisible by small item classes).
    let mut harmonic_bonus = 0.0;
    if post_residual % 10 == 0 { harmonic_bonus += 6.0; }
    if post_residual % 20 == 0 { harmonic_bonus += 4.0; }
    if post_residual % 25 == 0 { harmonic_bonus += 3.0; }
    if post_residual % 50 == 0 { harmonic_bonus += 3.0; }
    score -= harmonic_bonus;

    // Penalize dead space: residual smaller than the smallest plausible item (1)
    // is fine, but small odd residuals (1..9) are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // next item cannot fit here; mildly penalize tiny leftovers
            score += (pr / cap) * 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // are badly fragmented. Penalize the fresh bin unless residuals are large.
    if bin_residual == bin_capacity {
        let avg_frag = mean_residual / cap;
        // If mean residual of open bins is small (fragmented), opening new bin
        // is attractive -> subtract; otherwise penalize.
        if avg_frag < 0.15 {
            score -= 10.0 * (0.15 - avg_frag) / 0.15;
        } else {
            score += 12.0;
        }
    }

    // Prefer packing into bins with below-mean residual (tighter bins first),
    // classic best-fit with mean correction.
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    // Late in the stream, consolidation matters more: favor bins that end
    // near-empty or near-full (avoid mid-range waste).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mid_range_penalty = 1.0 - ((pr / cap - 0.5).abs() * 2.0);
    score += mid_range_penalty * 5.0 * progress;

    // Mild penalty for many open bins already: encourage closing bins out.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (1..=10) are nearly useless.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    } else if post_residual > 10 && post_residual <= 25 {
        score += 15.0;
    }

    // Reward tight fits: small positive post_residual relative to item size.
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 25.0 * tightness;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading (favor new bins less).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // New-bin candidate: only attractive when item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        let good_fit = item_size as f64 >= 0.9 * bin_capacity as f64;
        if good_fit {
            score -= 10.0;
        } else {
            score += 45.0 + 3.0 * (100 - item_size) as f64;
        }
    }

    // Lookahead: if next item could use the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Prefer bins with residual below the mean (consolidate space).
    let dev = mean_residual - bin_residual as f64;
    score += 0.5 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is highly rewarded.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // exact 2-step match: bin becomes perfectly full next step
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover after the hypothetical next placement
            score += slack * 0.35;
            if slack <= 10.0 {
                score -= 12.0; // near-perfect 2-step match
            }
        } else {
            // next item cannot fit here: post_residual becomes final dead space
            let dead = post_residual as f64;
            score += dead * 0.9;
        }
    } else {
        // last item: prefer minimal post residual (tightest fit)
        score += (post_residual as f64) * 0.5;
    }

    // Compare against mean residual: prefer consuming above-average residual space
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Penalize tiny unusable fragments (dead space < 10 can rarely host items)
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.0;
    }

    // Last-chance bonus: if this is the only fitting bin, opening a new bin wastes it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current bin fits are bad
    if bin_residual == bin_capacity {
        score += 30.0;
        // open a new bin if the item would leave a very tight fit elsewhere
        if post_residual < 15 && next_item_size > 0 && post_residual != next_item_size {
            score -= 45.0;
        }
    }

    // Late in the stream, prefer closing bins tightly (fewer bins overall)
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post_residual non-linearly.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * tightness * 40.0;

    // Lookahead: if the next item fits into this bin's post_residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // Extra reward proportional to how well the next item fills the remaining space.
        let next_fill = (next_item_size as f64) / (post_residual as f64);
        score -= next_fill * 10.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space the next item cannot use: mild penalty, stronger for large dead space.
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent fits exist; new-bin candidate has full residual.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // New bin acceptable when item is large relative to capacity or few fitting bins.
        let item_frac = (item_size as f64) / (bin_capacity as f64);
        score += 45.0 - item_frac * 30.0 - (fitting_bins_count as f64) * 8.0;
        // Later in the stream, prefer consolidating into open bins.
        score += progress * 15.0;
        // If mean residual across open bins is large, opening new bins is wasteful.
        score += mean_residual * 0.2;
    }

    // Mild penalty for spreading across many open bins when residuals are fragmented.
    if bin_residual != bin_capacity && open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 0.5;
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Non-linear waste penalty: squared normalized residual, scaled by stream progress
    score += 18.0 * norm_pr * norm_pr * (0.5 + progress);
    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;
    // Interaction: post_residual vs mean residual (avoid leaving more than average waste)
    score += 4.0 * norm_pr * (mean_residual / cap);
    // Lookahead coupling: penalize if next item fits well in the post residual (reserve space)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - ((pr - nxt) / cap).abs();
            score -= 6.0 * fit_quality * (0.4 + 0.6 * progress);
        } else {
            // next item won't fit here; slight penalty scaled by gap
            score += 3.0 * ((nxt - pr) / cap);
        }
    }
    // Last-chance bin bonus: strongly favor the only bin that can fit the item
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }
    // Mild penalty for spreading across many open bins late in the stream
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * progress;
    // New-bin candidate handling: make fresh bins moderately attractive only when
    // existing fits are poor or residual is large
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) - 5.0 * progress;
        if item_size as f64 / cap > 0.6 {
            score -= 8.0;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity fractions.
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;

    // Reward near-perfect fits: residual in {0,1,2,3} gets strong bonus.
    if pr <= 3 {
        score -= 40.0 + (4 - pr) as f64 * 8.0;
    } else if pr <= 8 {
        score -= 20.0;
    }

    // Harmonic classes: post_residual divisible by common item-size divisors
    // (10, 20, 25, 50) means future items may tile it perfectly.
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 50 == 0 { score -= 8.0; }
        // Penalize dead zones: residual just below small-item sizes (1..10 range
        // gaps) is unusable dead space; residual in (0,10) is worst.
        if pr < 10 {
            score += 12.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 5 {
            score -= 15.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            // This bin's leftover is too small for next item: penalize mildly
            // unless residual is tiny anyway.
            score += (post_residual.min(30)) as f64 * 0.3;
        }
        // Harmonic check: next item divides post_residual evenly.
        if next_item_size > 0 && pr % (next_item_size as i64) == 0 && pr > 0 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is penalized unless
    // existing bins would waste a lot (large mean residual mismatch).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64
            - 15.0 * (1.0 - progress)
            + if post_residual < 20 { 20.0 } else { 0.0 };
        // If mean residual of open bins is large, keeping them is fine; new bin ok.
        if mean_residual > 40.0 {
            score -= 10.0;
        }
    }

    // Prefer filling bins below mean residual (tighter bins first).
    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score -= 4.0;
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps that are too small to be useful later are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // --- Reward bins that can still host the lookahead item ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Bonus if post_residual is a tight wrap around next item.
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 8.0;
            }
        } else {
            score += 6.0;
        }
    }

    // --- Open bins pressure: discourage hoarding many open bins ---
    score += 1.5 * open_bins_count as f64;

    // --- Last-chance bin: strongly favor using it before opening a new one ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive for large items / many open bins,
        // but discouraged when a decent existing fit exists.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 45.0 + 0.8 * open_bins_count as f64 - 10.0 * progress;
        if item_size >= 60 {
            score -= 15.0;
        }
        if fitting_bins_count > 0 && post_residual >= 15 {
            score += 20.0; // keep using existing bins when fit isn't terrible
        }
    }

    // --- Mean residual coupling: prefer bins below mean residual (tighter bins) ---
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item still fits with small leftover.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack * 1.5;
    }
    // Next item cannot use the leftover: penalize proportional dead space.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Reward tight fits relative to capacity.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 10.0;

    // Penalize bins whose residual is far below the mean (they are already tight;
    // using them wastes scarce space) — favor bins with larger residuals.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: default mild penalty; but if no open bin offers
    // a good 2-step match and residuals are fragmented, allow opening a new bin.
    if bin_residual == bin_capacity {
        let good_match = next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) as f64 <= 10.0;
        if good_match {
            score += 100.0; // never open a new bin when a match exists
        } else {
            // Prefer new bin when open bins are fragmented and item is large.
            let progress = step_index as f64 / total_items.max(1) as f64;
            let fragmentation = (mean_residual - post_residual as f64).abs();
            score -= 15.0 + fragmentation * 0.4 + progress * 10.0;
        }
    }

    // Late in stream: consolidate into fewer bins.
    if open_bins_count > 0 {
        score += open_bins_count as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post_residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; penalize leaving a large awkward gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins with slack: discourage spreading into already-loose bins
    // unless the fit is very tight; encourage consolidation.
    if open_bins_count > 2 {
        let relative_fit = item_size as f64 / bin_residual as f64;
        score -= 5.0 * relative_fit;
        // penalize bins far looser than the mean (fragmentation risk)
        let dev = bin_residual as f64 - mean_residual;
        if dev > 0.0 {
            score += 0.05 * dev;
        } else {
            score -= 0.03 * (-dev);
        }
    }

    // Time horizon: early in the stream, be conservative (prefer new bins for large items
    // to keep flexibility); late in the stream, squeeze into existing bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.3 {
        // early: prefer new empty bins for big items
        if bin_residual == bin_capacity {
            score -= 10.0 + 0.2 * item_size as f64;
        }
    } else if progress > 0.7 {
        // late: new bins are expensive, avoid opening them
        if bin_residual == bin_capacity {
            score += 20.0;
        } else {
            score -= 6.0 * progress;
        }
    }

    // Mild penalty for new bin when plenty of open bins exist mid-stream.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 3.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize leftover, with non-linear penalty on tiny residuals (dead space)
    let mut score = pr as f64;
    score += 8.0 * norm_pr * norm_pr * cap;

    // Smooth coupling: as stream progresses, increasingly reward tight fits
    score -= (1.0 - progress) * 0.5 * pr;

    // Reward using existing bins more when many bins are open
    let open_factor = (open_bins_count as f64).ln().max(0.0);
    score -= 2.0 * open_factor * (cap - pr) / cap;

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: penalize leaving residual that barely fails to fit next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 3.0 * (pr - nxt) / cap;
        } else {
            let gap = nxt - pr;
            score += 4.0 * (gap / cap) * (gap / cap) * cap;
        }
    }

    // Mean residual context: prefer bins near the mean to keep flexibility
    score += 0.3 * (pr - mean_residual).abs();

    // New-bin candidate: penalize mildly unless it's clearly better
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Dead-space penalty: residual that cannot fit even the smallest item is pure waste.
    if post_residual > 0 && post_residual < 1 {
        score += 1000.0;
    }
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // residual unusable by the lookahead item -> extra penalty proportional to lock-in
        score += 5.0 + 0.3 * (next_item_size as f64 - pr);
    }

    // Reward tight fits: post_residual small relative to capacity.
    score -= 40.0 * (1.0 - pr / cap).powi(3);

    // Harmonic class of post_residual (modulo arithmetic on capacity fractions):
    // residuals divisible by large classes (20, 50) are more reusable.
    let cls = if post_residual % 50 == 0 {
        6.0
    } else if post_residual % 25 == 0 {
        4.0
    } else if post_residual % 20 == 0 {
        3.0
    } else if post_residual % 10 == 0 {
        2.0
    } else {
        0.0
    };
    score -= cls * (1.0 + 0.5 * (step_index as f64 / (total_items as f64 + 1.0)));

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 150.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item still fits: mild reward scaled by how much slack remains
        score -= 10.0 * (post_residual - next_item_size) as f64 / cap;
    }

    // New-bin candidate handling: penalize opening a new bin by default.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 60.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
        // If the new bin would leave a nicely classed residual (harmonic), slightly better.
        if post_residual % 10 == 0 {
            new_bin_score -= 8.0;
        }
        // If no open bin fits at all, opening a new bin is necessary.
        if fitting_bins_count == 0 {
            new_bin_score -= 500.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        new_bin_score += 10.0 * mean_residual / cap;
        score += new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size)
    // are pure waste; penalize them quadratically.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        // Moderately risky gap: next items (>=1..100 unknown dist) may not fit.
        score += (20 - post_residual) as f64 * 1.5;
    } else {
        // Large usable leftover: mild reward relative to mean residual.
        score -= ((post_residual as f64) - mean_residual).max(0.0) * 0.3;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bins pressure: discourage opening a new bin when many bins are open.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 3.0;
        // But if existing fits are all poor (small gaps), opening new bin is fine.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits exactly in post_residual, bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here anyway; dead space is locked in — penalize.
        score += post_residual as f64 * 0.4;
    }

    // Early in stream: be conservative, keep bins flexible (avoid tiny gaps).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly (non-linear).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.95 {
        score -= 60.0 * (fill - 0.95) / 0.05;
    } else if fill > 0.8 {
        score -= 15.0 * (fill - 0.8) / 0.15;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this placement chains perfectly — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 10.0 {
                score -= 25.0 * (1.0 - slack / 10.0);
            }
        } else {
            // Next item won't fit here; penalize wasted residual relative to mean.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.4 * waste.min(30.0);
        }
    }

    // Compare post_residual against mean residual: leaving less than average
    // is good (tight packing), leaving more is wasteful.
    if (post_residual as f64) < mean_residual {
        score -= 0.3 * (mean_residual - post_residual as f64).min(20.0);
    } else {
        score += 0.2 * ((post_residual as f64) - mean_residual).min(20.0);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let urgency = if next_item_size > 0 && next_item_size > item_size { 1.0 } else { 0.0 };
        // Penalize opening new bins by default; discount when stream is early
        // or many bins open (cheap to spread).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 - 10.0 * urgency - 15.0 * (1.0 - progress);
    }

    // Tiny post-residuals are dead space; reward avoiding them.
    if post_residual > 0 && post_residual < 5 {
        score -= 20.0;
    } else if post_residual == 0 {
        score -= 80.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Exact or near-exact fits are gold.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Penalize leaving dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: reward residual that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else {
            // Residual wasted w.r.t. lookahead; penalize proportionally.
            score += 4.0 * (1.0 - post_residual as f64 / next_item_size as f64).max(0.0);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global pressure: many open bins -> prefer consolidation (favor small residuals).
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Mean residual anchoring: bins deviating far below mean residual are scarce space.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 8.0 * dev;

    // Time horizon: early in stream, be picky (penalize loose fits); late, just fill.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * 15.0;

    // New-bin candidate: keep it attractive when fits are poor / no good residual exists.
    if bin_residual == bin_capacity {
        let good_fit_exists = mean_residual > item_size as f64 + 15.0;
        if good_fit_exists {
            score += 45.0; // discourage opening when open bins fit well
        } else {
            score -= 20.0; // encourage opening a fresh bin
        }
        // Late stream: avoid proliferating bins.
        score += progress * 30.0;
        // If many bins already open, discourage another unless item is large.
        score += 3.0 * (open_bins_count as f64) - 0.2 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    // Early: prefer tight fits; Late: tolerate larger residuals (keep slack for future items)
    let poly = norm_pr * norm_pr * (1.0 - progress) - norm_pr * progress;
    score += 40.0 * poly;

    // Dead-space penalty: residuals too small to ever be useful
    let dead = (norm_pr - (next_item_size as f64 / cap)).max(0.0);
    score += 15.0 * dead * dead;

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Penalize bins far from mean residual (favor homogeneity)
    score += 2.0 * (pr - mean_residual).abs() / cap;

    // Mild pressure against opening many bins early
    score += 0.5 * (open_bins_count as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover space is.
    // Class 0: post_residual == 0 -> perfect closure, heavily reward.
    // Class 1: post_residual in 1..=10 -> small dead space, mild reward.
    // Class 2: post_residual divisible by 25 -> quarter-capacity harmonics, reusable.
    // Class 3: post_residual divisible by 10 -> decile harmonic, decent.
    // Otherwise: awkward remainder, penalize.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 10 {
        score -= 12.0;
    } else if pr % 25 == 0 {
        score -= 25.0;
    } else if pr % 10 == 0 {
        score -= 10.0;
    } else if pr % 5 == 0 {
        score -= 4.0;
    } else {
        score += 8.0;
    }

    // Integer-division threshold on post_residual: large leftovers (> 40) waste capacity
    // unless the bin is fresh; scale penalty with fraction of capacity wasted.
    if pr > 40 {
        score += (pr as f64 / bin_capacity as f64) * 15.0;
    }

    // Lookahead coupling: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr && pr - next_item_size <= 10 {
            score -= 18.0;
        } else if next_item_size > pr {
            // next item cannot use this leftover: penalize proportionally to leftover size
            score += (pr as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Fractional capacity thresholds on bin_residual (harmonic bands).
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if bin_residual <= quarter {
        score -= 6.0; // nearly full bin: good place to dump
    } else if bin_residual <= half {
        score -= 2.0;
    }

    // Stream progression: early on, prefer opening bins less (consolidate);
    // late in stream, closing bins cleanly matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // Mean residual coupling: if this bin's residual is far below mean, it is tighter
    // than average -> prefer filling it.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 && res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.25;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // but if many bins are open and mean residual is low, opening is fine
        if open_bins_count > 3 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 {
        // Dead-space threshold: gaps too small for the smallest plausible item.
        let dead_threshold = 12.0;
        if (post_residual as f64) < dead_threshold {
            score += 60.0 * (dead_threshold - post_residual as f64) / dead_threshold;
        }
        // Exact fit is ideal.
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Penalize residual that cannot fit the lookahead item (creates stranded space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // Reward residual that can still accommodate the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer filling bins with larger existing residuals (tight packing).
    score -= 0.1 * (bin_residual as f64 - mean_residual);

    // Mild late-stream tightening: waste matters more as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small dead space)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 30.0;

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= (1.0 - lookahead_gap / bin_capacity as f64).max(0.0) * 25.0;
        // Perfect lookahead match
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Bad: residual slightly larger than next item wastes space
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Last chance bin: strong bonus to use it instead of opening a new bin
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Early in stream: be pickier, prefer spreading items (keep flexibility)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.1;

    // Penalize leaving dead space that nothing (>=10) can use
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Mild preference for consolidating into fewer bins when many are open
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual was close to item size.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Lookahead: if the next item fits into this bin's post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let pressure = mean_residual / bin_capacity as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * pressure * (0.5 + t);
        score += 2.0 * open_bins_count as f64 * (1.0 - t);
    } else {
        // New-bin candidate: attractive only when mean residual is low or stream is early.
        score += 15.0 * pressure;
        score -= 8.0 * (1.0 - t);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0 * (1.0 - next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Mild preference for more-full bins overall.
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let fit = if bin_residual >= item_size { 1.0 } else { 0.0 };
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = (1.0 - t) * (pr / cap) * (pr / cap) + t * (pr / cap).powi(3);
    score += poly * cap * 0.5;
    // Reward tight fits, more strongly as stream progresses
    score -= fit * (1.0 + 2.0 * t) * (item_size as f64 / cap);
    // Penalize last-chance waste: if this is the only fitting bin, discourage bad fits
    if fitting_bins_count == 1 && fit > 0.0 {
        score += (pr / cap) * 20.0 * (1.0 - item_size as f64 / cap);
    }
    // Lookahead: favor bins whose post-residual can hold the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (1.0 - t);
    } else if next_item_size > 0 {
        score += (next_item_size as f64 - pr).min(cap) * 0.1 * t;
    }
    // New-bin candidate handling: mild bias toward reuse early, openness late
    if bin_residual == bin_capacity {
        score += 5.0 - 10.0 * t;
    }
    // Coupling with mean residual across open bins
    score += (mean_residual / cap - pr / cap).abs() * 4.0;
    // Slight penalty for many open bins late in stream
    score += (open_bins_count as f64).ln().max(0.0) * t * 2.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of 10, small slivers) are favored.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit
    } else if pr % 10 == 0 {
        -25.0 // leftover usable by typical item sizes
    } else if pr % 5 == 0 {
        -10.0
    } else {
        8.0 // awkward dead space
    };
    score += class_bonus;

    // Integer-division threshold on post_residual: leftover <= 10 is nearly dead.
    if pr > 0 && pr <= 10 {
        score += 20.0;
    }
    // Very large leftover means the bin was barely used; mild penalty vs tight packing.
    if pr > 60 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual
    // (harmonic pairing), strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            score -= 12.0 * (next_item_size as f64 / pr as f64);
        } else {
            score += 5.0; // next item won't fit here anyway
        }
        // Modulo harmony: next item leaves another clean multiple of 10.
        if next_item_size <= pr && (pr - next_item_size) % 10 == 0 {
            score -= 15.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
        if pr <= 10 && item_size < 30 {
            score += 25.0; // poor fit in last bin -> let new bin win
        }
    }

    // New-bin candidate handling: empty bin gets a baseline that keeps it
    // competitive only when existing bins would waste space.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Early stream or many items left: fresh bins are cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * (1.0 - progress);
        // Big upcoming item: keep a fresh bin around.
        if next_item_size > 60 {
            score -= 20.0;
        }
    }

    // Spread pressure: if mean residual is high, prefer filling the fullest bins
    // (i.e., bins with small residual get extra reward).
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.15;
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.05;

    // Many open bins: consolidate, penalize spreading into fresh space.
    if open_bins_count > 8 {
        score += if bin_residual == bin_capacity { 15.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (non-linear "dead zone" coupling).
    let dead_threshold = 10.0f64; // smallest item that could arrive
    if (post_residual as f64) < dead_threshold {
        // Unusable sliver: penalize proportionally to how close to zero it is.
        score += 25.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    } else {
        // Reward good packing: tight fits (small but usable residual) get a bonus.
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 6.0 * tightness * tightness;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // Next item cannot use the leftover: this residual is likely dead space.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid
    // opening a new bin for an item that already has a home.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Open-bin pressure: discourage proliferation of bins; mildly prefer
    // filling existing bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual deviates below the mean (filling the emptiest
    // usable bins first keeps a pool of tight bins).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate: neutral baseline with mild penalty so it is chosen
    // only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score = 30.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Near-perfect match: next item fits with tiny slack left.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / 30.0).max(0.0);
    }
    // Penalize leaving dead space too small for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - post_residual as f64 / 100.0);
    }

    // Reward tight fits relative to bin capacity.
    score -= 15.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Penalize large post_residual relative to mean residual (wasteful spread).
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-high unless current bin is very tight.
    if bin_residual == bin_capacity {
        score += 5.0;
        // Opening a new bin is good early in the stream (reserve flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 6.0 * (1.0 - progress);
        // If the next item is large and no open bin can host both, new bin is attractive.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 10.0;
        }
    }

    // Mild penalty on bin proliferation late in the stream.
    score += 0.15 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early steps favor consolidation, late steps favor tight fits.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward near-perfect fits (post_residual small) more strongly over time.
    let fit_bonus = ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powf(3.0 + 4.0 * t);
    score -= 12.0 * fit_bonus;

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits: reward this bin as a chain enabler.
            let chain = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 6.0 * chain;
        } else {
            // Dead space: penalize proportionally to unusable gap.
            let gap = post_residual as f64 / bin_capacity as f64;
            score += 8.0 * gap * (1.0 + 2.0 * t);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Many fitting bins: prefer the tightest one; add mild competition penalty.
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Global residual pressure: if mean residual is small, be frugal with open bins.
    let pressure = mean_residual / bin_capacity as f64;
    score += 3.0 * pressure * (1.0 - t);

    // Prefer filling bins that are already heavily loaded (fewer open bins overall).
    let load = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
    score -= 5.0 * load * (0.5 + 0.5 * t);

    // Open-bin count discipline: penalize selection when many bins are open.
    score += 0.4 * open_bins_count as f64 * (1.0 - t) * (1.0 - load);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 10.0 - 8.0 * scarcity - 4.0 * big_item * (1.0 + t);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0; // fresh bin can host the lookahead too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear penalty on wasted space, amplified by stream progress
    score += 12.0 * norm_pr * norm_pr * (0.4 + 0.6 * progress);

    // Reward tight fits (small post_residual) more strongly as the stream advances
    score -= 18.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Coupling with mean residual: prefer bins whose residual deviates below mean
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * (1.0 - 2.0 * progress);

    // Last-chance bin bonus (smoothly weighted by progress)
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Lookahead: reward if next item fits the resulting residual, penalize otherwise
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            score -= 10.0 * (gap / cap) * (1.0 - gap / cap);
        } else {
            score += 8.0 * (-gap / cap);
        }
    }

    // Mild penalty for opening a new bin when many bins are already open
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (3.0 + 5.0 * progress) * (open_bins_count as f64).sqrt();

    // Small jitter-free polynomial in item size to break ties toward larger items packed first
    score += 0.02 * (item_size as f64 / cap).powi(3);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: divide capacity into 5 classes
    let class_size = bin_capacity / 5; // 20
    let post_class = (post_residual / class_size) as f64;

    // Reward placements that land post_residual in a "useful" harmonic class
    // (post residual close to multiples of 20 keeps space reusable by mid-size items)
    score -= post_class * 6.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 200.0;
    }

    // Penalize small dead space (1..=class_size/2): unusable for most items
    if post_residual > 0 && post_residual < class_size / 2 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item harmonizes with post residual
            let next_class = (next_item_size / class_size) as f64;
            score -= 10.0 + next_class * 4.0;
        } else {
            // next item won't fit here; penalize small residuals more
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Many open bins: prefer tightening existing bins over spreading
    if open_bins_count > 4 {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // Modulo arithmetic on post_residual: reward residuals divisible by 10
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Stream progression: early on, prefer opening bins for large items (future flexibility)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.3 && item_size > bin_capacity / 2 {
        score += 15.0;
    }

    // New-bin candidate: neutral-ish baseline, only attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        score = 60.0 + mean_residual * 0.2 - (fitting_bins_count as f64) * 5.0;
        if fitting_bins_count == 0 {
            score = -10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100) are wasted.
    // Penalize post_residuals that fall into "unusable" tiny gaps harshly.
    if post_residual > 0 {
        // dead space that can never fit another item (min item size 1 => any gap usable,
        // but small gaps (<10) are effectively dead for typical distributions)
        if post_residual < 10 {
            score += 40.0 * (10.0 - post_residual as f64);
        } else if post_residual < 20 {
            score += 12.0;
        }
    } else {
        // perfect fit: strong reward
        score -= 30.0;
    }

    // Reward tight fits generally: smaller post_residual relative to capacity is better.
    score += 0.15 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Open-bins pressure: discourage opening new bins when many bins are open
    // unless the fit is very good. New-bin candidate has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // candidate new bin: penalize more as open_bins_count grows
        score += 8.0 + 0.6 * open_bins_count as f64;
        // but if no other bin fits well, allow it: handled by fitting_bins_count
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
        // lookahead: if next item is large, a fresh bin is valuable
        if next_item_size > 60 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mean residual coupling: prefer bins whose post_residual stays near mean
    // (keeps residual distribution tight, avoiding stranded small gaps)
    let drift = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * drift;

    // Late in stream: be more conservative with new bins (less time to recover)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 4.0 * progress;
    }

    // Lookahead synergy: if next item fits exactly into post_residual, reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 18.0;
        } else if slack < 15.0 {
            score -= 7.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // accommodates the next item (perfect 2-item packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here afterwards: strong reward, scaled by tightness.
            let tightness = (next_item_size as f64) / (post_residual as f64);
            score -= 40.0 + 30.0 * tightness;
            if post_residual == next_item_size {
                // Perfect 2-item fill: bin becomes exactly full after next item.
                score -= 25.0;
            }
        } else {
            // Next item cannot use the leftover: penalize dead space, worse
            // when leftover is tiny (unusable sliver).
            let sliver = post_residual as f64;
            if sliver < next_item_size as f64 {
                score += 10.0 * (1.0 - sliver / (next_item_size as f64));
            }
        }
    }

    // Reward tight fits of the current item relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio * fill_ratio;

    // Penalize bins far below mean residual (fragmenting) unless lookahead fits.
    if post_residual as f64 > mean_residual + 5.0 && next_item_size == 0 {
        score += 5.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: keep it attractive only when no open bin offers a
    // good 2-step fit (i.e., when residual slack across bins is large).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty so new bins lose to good fits; reduced late in stream
        // or when many bins are open and mean residual is small.
        let mut new_bin_score = 55.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A new bin can always host the next item too: mild discount.
            new_bin_score -= 10.0;
        }
        if mean_residual < 20.0 {
            new_bin_score -= 15.0;
        }
        new_bin_score -= 10.0 * progress;
        score = score.min(new_bin_score);
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize leaving dead space that is too small for the average next item.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 10.0 + 0.25 * post_residual as f64;
        } else if post_residual >= next_item_size {
            // Reward bins that can also host the lookahead item.
            score -= 6.0 * (post_residual as f64 - next_item_size as f64).min(20.0) / 20.0;
        }
    } else {
        // Last item: strongly prefer filling an existing bin completely.
        score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0;
    }

    // New-bin candidate handling: make empty bins attractive only when
    // existing residuals are fragmented or the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let large_item_bonus = if item_size > bin_capacity / 2 { 8.0 } else { 0.0 };
        score += 12.0
            - 5.0 * fragmentation / bin_capacity as f64
            - large_item_bonus
            - 3.0 * progress;
    } else {
        // Mild penalty for spreading load thin across many open bins.
        score += 0.6 * (open_bins_count as f64).ln().max(0.0);
    }

    // Time-horizon modulation: early on, be conservative (keep bins balanced);
    // late in the stream, prioritize closing bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 0.15 * (mean_residual - post_residual as f64).abs();
    score -= progress * 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth non-linear coupling: quadratic in normalized post_residual scaled by progress
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Penalize dead space relative to mean residual
    score += 8.0 * (pr - mean_residual) / cap;

    // Last-chance bin bonus (only fitting bin)
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Lookahead: favor bins whose post_residual can fit the next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if pr >= next {
            score -= 12.0 * (1.0 - (pr - next) / cap);
        } else {
            score += 10.0 * (next - pr) / cap;
        }
    }

    // Slight penalty for many open bins with large residuals
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // New-bin candidate: penalize mildly so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by common item sizes
    // (10, 20, 25, 50) are more likely to be filled by future items.
    let r = post_residual;
    let harmonic_bonus = if r == 0 {
        -40.0 // perfect fit
    } else if r % 50 == 0 {
        -18.0
    } else if r % 25 == 0 {
        -10.0
    } else if r % 10 == 0 {
        -6.0
    } else if r % 5 == 0 {
        -2.0
    } else {
        // awkward dead space, penalize small odd residuals
        if r < 10 { 25.0 } else { 0.0 }
    };
    score += harmonic_bonus;

    // Lookahead coupling: if next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 30.0;
        } else if next_item_size <= r {
            let nr = r - next_item_size;
            // prefer chains leaving harmonic residuals
            if nr % 10 == 0 || nr == 0 {
                score -= 8.0;
            }
            score -= (nr as f64) * 0.05;
        } else {
            // next item cannot use this residual: penalize proportionally
            score += (r as f64) * 0.10;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let penalty = 12.0 + 30.0 * (1.0 - progress) + (open_bins_count as f64) * 0.5;
        // acceptable if mean residual is low (bins nearly full)
        let relief = (mean_residual / bin_capacity as f64) * 20.0;
        score += penalty - relief;
    }

    // Tight fit reward: fraction of capacity used by this item.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 10.0;

    // Discourage leaving tiny unusable gaps more aggressively over time.
    if r > 0 && r < 5 {
        score += 20.0 + 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Tight fit reward: item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Penalize leaving a gap that no plausible item can use well.
    if post_residual >= 10 && post_residual < item_size {
        score -= 10.0; // gap still usable by smaller items
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 2.5 * progress);

    // New-bin candidate: only attractive when item fits poorly everywhere
    // or the residual would become dead space in the chosen bin.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score += 30.0 + open_bins_count as f64 * 4.0;
        // but a fresh bin wastes nothing now
        score -= 15.0;
        // if no open bin gives a good fit (this call context: few fitting bins), ease opening
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // early stream: opening bins is cheaper to enable future pairings
        score -= (1.0 - progress) * 10.0;
    }

    // Lookahead: if next item would fit the post-residual exactly or well, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= next_fit_quality * 20.0;
    }
    // If next item cannot fit the post-residual, the leftover is likely dead space.
    if next_item_size > post_residual && post_residual > 0 {
        score += 12.0;
    }

    // Mean residual coupling: bins far below mean residual are "loose"; prefer them slightly.
    score -= (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: post_residual exactly matches the next item (perfect 2-step chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Reward: next item fits in the post-residual (2-step lookahead feasibility).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // Penalize dead space the next item cannot use.
        score += 0.8 * (next_item_size - post_residual) as f64;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Penalize bins with residuals far below the mean (fragmented bins),
    // but only mildly, so tight fits still win.
    score += 0.3 * (mean_residual - bin_residual as f64).abs();

    // Penalize very small unusable post-residuals (dead space < 10).
    if post_residual < 10 {
        score += 40.0;
    }

    // New-bin candidate: prefer it only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 60.0;
    }

    // Slight preference for keeping fewer open bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual) with a nonlinear discount.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 2 {
        score -= 20.0;
    }

    // Lookahead: penalize residuals that no plausible next item can use.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            // Dead space relative to the upcoming item.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        } else if post_residual >= next_item_size {
            // Reward bins that can also host the lookahead item.
            score -= 0.25 * next_item_size as f64;
        }
        // If the lookahead item exactly fills the post residual, big reward.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        score += 25.0;
        // More open bins -> higher cost of yet another bin.
        score += 1.5 * open_bins_count as f64;
        // Late in the stream, consolidation matters more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // If mean residual across bins is large, prefer reusing them.
        score += 0.2 * mean_residual;
        // Exception: if no existing bin can fit (this is the only candidate),
        // fitting_bins_count would be 1 for the new bin too; soften via item size.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild preference for filling bins with larger residual when many bins are open.
    score += 0.05 * (open_bins_count as f64) * (bin_residual as f64) / (bin_capacity as f64);

    // Prefer bins whose residual is close to the mean (avoid outlier hoarding).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual (tight fits)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals less; later, avoid wasting space even more.
    let progress_coupling = norm_pr * norm_pr * (1.0 + 3.0 * progress)
        + norm_pr * (progress * (1.0 - progress) * 4.0);
    score += 12.0 * progress_coupling;

    // Cubic term: heavily penalize large dead space as stream matures
    score += 30.0 * norm_pr.powi(3) * (0.5 + progress);

    // Reward last-chance bins (avoid opening new bin unnecessarily)
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits into the post residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0 + 6.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // penalize if next item likely cannot use the residual
        score += 4.0 * (1.0 - (next_item_size as f64 / cap).min(1.0));
    }

    // Penalize placements far below the mean residual (creates outlier dead space)
    score += 2.0 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: mild penalty so it's chosen only when open bins are poor fits
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "reusable" size classes (multiples of common item sizes).
    let class = post_residual % 10;
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else {
        // Dead space penalty: residuals too small for the smallest item
        if post_residual < 10 {
            score += 25.0;
        }
        // Reward residuals in harmonically friendly classes (0,5 mod 10)
        if class == 0 {
            score -= 8.0;
        } else if class == 5 {
            score -= 4.0;
        } else {
            score += (class as f64) * 0.6;
        }
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // extra reward for near-exact pairing
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 10.0;
            }
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin wastes a lot
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score += 20.0 + waste * 0.5;
        if fitting_bins_count > 0 {
            score += 10.0; // prefer existing bins when any fit
        }
    }

    // Tight fit reward
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    // Mean residual context: avoid dumping into bins far below mean residual
    score += 0.1 * (mean_residual - bin_residual as f64);

    // Progress: slightly more conservative late in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

