        // Next item won't fit here anyway; slight penalty if we leave a near-miss gap.
        let gap = (next_item_size - post_residual) as f64;
        if gap < 10.0 {
            score += 8.0;
        }
    }

    // Mild attraction to bins near mean residual (balanced usage).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect / near-perfect fit reward (non-linear).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0 + (5 - post_residual) as f64 * 30.0;
    } else if post_residual <= 15 {
        score -= 60.0 * (1.0 - post_residual as f64 / 15.0);
    }

    // Lookahead: reward if the leftover space exactly (or nearly) fits the next item.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 400.0;
        } else if gap > 0 && gap <= 10 {
            score -= 120.0 * (1.0 - gap as f64 / 10.0);
        } else if gap < 0 && (-gap) as u32 <= item_size {
            // next item could combine with a future small one; mild penalty for stranding
            score += 20.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fits more aggressively.
        score += 8.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Penalize opening a new bin when decent fits exist, unless current bin leaves bad residue.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost grows with number of open bins (fragmentation control).
        score += 90.0 + 6.0 * open_bins_count as f64;
        // But a new bin is attractive if all open residuals are small (nothing useful to pack into).
        if mean_residual < item_size as f64 * 0.9 {
            score -= 120.0;
        }
        // Late in stream, avoid opening new bins (fewer chances to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 * progress;
        // If next item is large, a fresh bin may be valuable.
        if next_item_size >= 60 && post_residual == bin_capacity as u32 {
            score -= 40.0;
        }
    } else {
        // Reward using bins whose residual is far from capacity (consolidation).
        let tightness = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 40.0 * tightness;
    }

    // Global state coupling: prefer bins below mean residual when mean is high (balance load),
    // prefer above-mean bins when mean is low (fill fat bins first).
    let dev = bin_residual as f64 - mean_residual;
    if mean_residual > bin_capacity as f64 * 0.5 {
        score += 0.3 * dev;
    } else {
        score -= 0.3 * dev;
    }

    // Penalize leaving awkward dead space (residues in 20..40 are hard to fill with items >=10... keep usable).
    if post_residual >= 20 && post_residual <= 39 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals slightly; later, penalize dead space harder.
    let w = 0.5 + 1.5 * progress * progress;
    score += w * cap * norm_pr * norm_pr;

    // Smooth cubic interaction: mid-stream, reward near-perfect fits extra
    let fit_term = (1.0 - norm_pr).powi(3);
    score -= 8.0 * fit_term * (0.25 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: if next item fits in post_residual, reward this placement smoothly
    if next_item_size > 0 && next_item_size <= post_residual {
        let ratio = next_item_size as f64 / pr.max(1.0);
        score -= 6.0 * ratio * (1.0 - ratio) * (0.5 + progress);
    } else if next_item_size > post_residual {
        score += 3.0 * (0.5 + progress);
    }

    // Mean residual coupling: penalize bins far from mean residual (smooth)
    let dev = (pr - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;

    // Mild penalty for opening a new bin when many bins are open
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // but reward new bin if item is large relative to capacity
        score -= 10.0 * (item_size as f64 / cap) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer tight fills (small post_residual).
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // usefulness buckets via integer division on capacity fractions.
    // Residual classes (relative to C=100): [0..9] perfect, [10..24] good,
    // [25..49] mediocre, [50..99] wasteful.
    let class = post_residual / 25; // 0,1,2,3
    let class_penalty = match class {
        0 => -8.0,  // near-perfect fit
        1 => 0.0,
        2 => 4.0,
        _ => 10.0,  // half-empty bin is wasteful
    };
    score += class_penalty;

    // Dead-space trap: post_residual too small for the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 12.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 15.0; // perfect closure
    }

    // Modulo coupling: does post_residual align with common item-size
    // harmonic classes (multiples of 5 and 10)?
    let aligned_10 = post_residual % 10 == 0;
    let aligned_5 = post_residual % 5 == 0;
    if aligned_10 && post_residual > 0 {
        score -= 3.0;
    } else if aligned_5 && post_residual > 0 {
        score -= 1.5;
    }

    // Lookahead: reward if next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // chain-perfect
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            // next item won't fit here; waste depends on how large the gap is
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Congestion: many open bins -> consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let congestion = (open_bins_count as f64).ln() * 2.0;
    if bin_residual < bin_capacity {
        score -= congestion * (0.5 + 0.5 * progress);
    }

    // New-bin candidate logic: empty bin gets a neutral-to-high baseline;
    // only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how bad existing
        // options are (large mean residual means open bins are roomy,
        // so opening a new bin is less necessary).
        let mut new_bin_score = 55.0;
        if fitting_bins_count == 0 {
            new_bin_score -= 60.0; // forced: no alternative
        } else {
            // penalize new bin more when open bins fit decently
            new_bin_score += mean_residual * 0.3;
            if next_item_size > 0 && next_item_size >= item_size {
                // opening fresh bin may serve the bigger next item too
                new_bin_score -= 8.0;
            }
            // late in stream, prefer consolidation
            new_bin_score += 20.0 * progress;
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can use are heavily penalized.
    // The smallest possible item is 1, but usable gaps should ideally fit the lookahead item
    // or at least a mid-range item. Penalize gaps that are "wasted".
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            // Gap cannot host the known next item: strong penalty proportional to the waste.
            score += 30.0 + 0.5 * post_residual as f64;
        }
        if post_residual < 10 {
            // Unusable micro-gap under any realistic item: near-total waste.
            score += 60.0;
        } else if post_residual <= 20 {
            // Small gap: only usable by tiny items; partial waste penalty.
            score += 20.0;
        }
    } else {
        // Perfect fit: strongly rewarded.
        score -= 50.0;
    }

    // Reward tight fits generally (small post_residual relative to item size).
    let tightness = item_size as f64 / (item_size + post_residual).max(1) as f64;
    score -= 10.0 * tightness;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading; prefer filling
    // existing bins over opening new ones. New-bin candidate has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // New bin: penalize more when many bins are already open.
        score += 10.0 + 2.0 * open_bins_count as f64;
        // If the next item is large, a fresh bin is attractive though.
        if next_item_size > 50 {
            score -= 15.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // Filling an existing bin: reward, more so when its residual is below the mean
        // (it is already "small" and should be finished off).
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        }
    }

    // If placing here leaves a gap exactly matching the next item, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly in the
    // post residual, this bin is an ideal two-item chain.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let two_step_waste = (post_residual - next_item_size) as f64;
            score -= 50.0 * (1.0 - two_step_waste / bin_capacity as f64);
            if two_step_waste <= 5.0 {
                score -= 100.0;
            }
        } else {
            // Next item cannot follow into this bin: penalize relative to
            // how much of the bin would be left dead.
            let dead = post_residual as f64 / bin_capacity as f64;
            score += 80.0 * dead;
        }
    }

    // Compare post_residual against mean residual of open bins: leaving a
    // residual far below the mean creates a hard-to-fill sliver bin.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 0.5 * (mean_residual - pr);
    } else {
        score -= 0.2 * (pr - mean_residual).min(50.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Late in the stream, consolidate: prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 40.0 * progress;
    } else {
        // New-bin candidate: only attractive when item is large relative to
        // capacity or open bins are mostly full.
        score += 30.0 + 50.0 * (1.0 - item_size as f64 / bin_capacity as f64);
        if mean_residual < item_size as f64 {
            score -= 60.0;
        }
    }

    // Mild preference for tighter existing bins overall.
    score += 0.1 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (near-exact packing).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 12 {
        score -= 10.0;
    }

    // Penalize residuals that are too small to be useful for future items
    // (dead space in the 1..9 range is nearly unusable).
    if post_residual >= 1 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.1 * (post_residual as f64 - next_item_size as f64);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise the item may force opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: mildly discourage opening a new bin when
    // decent open bins exist, but allow it when open bins are nearly full
    // (their mean residual is low) or the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = mean_residual / bin_capacity as f64;
        score += 15.0 - 10.0 * openness - 5.0 * progress;
        if item_size > 70 {
            score -= 10.0; // large items are fine starting a fresh bin
        }
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // discouraging extreme fragmentation.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Late in the stream, consolidate: favor filling existing bins tighter.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer minimal post residual (tight packing).
    let mut score = post;

    // Reward tight fits: quadratic coupling between post_residual and item size,
    // scaled by stream progress (tighter packing valued later in the stream).
    let tightness = 1.0 - (post / cap);
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize large dead space super-linearly, especially early (waste now hurts later).
    let dead_frac = post / cap;
    score += 20.0 * dead_frac * dead_frac * dead_frac * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - dead_frac);
    }

    // Prefer bins below mean residual (balance load), mild smooth coupling.
    score += 0.05 * (post - mean_residual);

    // Lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.3 * gap / cap;
        if next_item_size as u32 == post_residual {
            score -= 10.0;
        }
    }

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    // and when other bins can fit the item.
    if bin_residual == bin_capacity {
        let open_penalty = 8.0 + 6.0 * progress + 0.5 * open_bins_count as f64;
        score += open_penalty;
        // But if the item is large relative to capacity, a fresh bin is reasonable.
        score -= 6.0 * (item / cap) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: harmonic class of post_residual mod capacity
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit gets huge reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Reward small post_residual non-linearly
        score += (pr / c).powf(3.0) * 50.0;

        // Harmonic class: post_residual divisible by small numbers => likely reusable
        if post_residual % 10 == 0 {
            score -= 8.0;
        }
        if post_residual % 25 == 0 {
            score -= 5.0;
        }
        // Awkward residues (just above half capacity) are dead space
        if post_residual > bin_capacity / 2 && post_residual < bin_capacity {
            score += (pr - c * 0.5) * 0.5;
        }

        // Lookahead coupling: does the next item fit into the post residual?
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                score -= 12.0;
            } else if next_item_size == post_residual {
                score -= 30.0;
            }
            // next item shares harmonic class with item size
            if next_item_size % 10 == item_size % 10 {
                score -= 3.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening new bins when open bins exist with good mean residual
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if mean_residual > 0.0 && mean_residual >= item_size as f64 {
            score += 25.0;
        }
    }

    // Progression: be more conservative late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * progress * 0.3;

    // Mean residual alignment
    score += (mean_residual - pr).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps below the minimum item size are pure waste.
    if post_residual < 10 {
        // Unusable dead space: heavy penalty scaled by how close it is to a "perfect" fill.
        score += 40.0 + (10 - post_residual) as f64 * 2.0;
    } else {
        // Usable gap: mild reward for tighter fits (smaller post_residual already lowers score).
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 8.0 * tightness;
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves more fragmentation: small bonus proportional to fill.
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item will NOT fit here: penalize leaving a gap that blocks the lookahead.
            if post_residual >= 1 {
                score += 10.0;
            }
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones and
    // encourage consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open-bin pressure and mean residual.
        score += 15.0 + 5.0 * pressure + 0.1 * mean_residual;
    } else {
        // Existing bins get a mild consolidation bonus that grows with pressure.
        score -= 1.5 * pressure.min(6.0);
    }

    // Prefer bins whose residual is close to the item (best-fit style), scaled by mean residual.
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * gap * (mean_residual.max(1.0) / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits here after this placement: strong reward scaled by tightness
            let tight = (next_item_size as f64) / (post_residual as f64);
            score -= 50.0 + 100.0 * tight;
        } else {
            // next item would not fit: penalize wasted space, worse when post_residual small
            score += 30.0 + 0.5 * (post_residual as f64);
        }
    } else {
        // last item: just minimize post_residual
        score -= 20.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize unless current bin fit is very poor
    if bin_residual == bin_capacity {
        score += 150.0;
        // but if lookahead fails everywhere, new bin is attractive: reduce penalty
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 80.0;
        }
        if fitting_bins_count == 1 {
            score -= 100.0;
        }
    }

    // Late in stream: prefer closing out bins, keep fewer open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.2 * (open_bins_count as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 10.0; // small dead space is nearly a perfect fit
    }

    // Penalize large residual waste relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * waste_frac * waste_frac;

    // Lookahead: reward if next item fits in the post-residual (chaining placements).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 + 4.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Penalize leaving a residual just below the next item's size (near-miss waste).
            let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
            if post_residual < next_item_size {
                score += 2.0 * (1.0 - gap / bin_capacity as f64);
            }
        }
    } else {
        // Last item: strongly prefer any bin that avoids opening a new bin.
        score -= 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over a new bin.
    if fitting_bins_count == 1 {
        score -= 14.0;
    } else if fitting_bins_count > 1 {
        // With many options, push toward the tightest fit via fit_ratio (already done).
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        // Existing bin: reward when open bins are plentiful and residual-rich.
        score -= 3.0 * (open_bins_count as f64).ln().max(0.0) * (mean_residual / bin_capacity as f64);
        score -= 4.0 * progress; // later in stream, avoid new bins
    } else {
        // New-bin candidate: penalize more when open bins are underutilized or stream is late.
        score += 5.0 * (mean_residual / bin_capacity as f64).max(0.0);
        score += 6.0 * progress;
        // Early stream with few bins: opening a fresh bin is cheap.
        score -= 4.0 * (1.0 - progress) * (1.0 - open_bins_count.min(10) as f64 / 10.0);
        // A new bin is attractive if the item is large and no bin fits well.
        score -= 0.05 * item_size as f64;
    }

    // Mild penalty for leaving residual in a narrow awkward band (20..40) that
    // few item sizes can use efficiently.
    if post_residual >= 20 && post_residual <= 40 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with non-linear penalty on large residuals.
    let mut score = pr
        + 40.0 * pr_norm * pr_norm
        + 60.0 * pr_norm * pr_norm * pr_norm;

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, larger residuals are tolerable; later, penalize them more.
    let coupling = 1.0 + 1.5 * progress + 2.0 * progress * progress;
    score += 30.0 * (pr_norm - 0.5) * (pr_norm - 0.5) * coupling;

    // Reward tight fits: interaction of item_size with residual.
    let fill_ratio = item_size as f64 / cap;
    score -= 50.0 * fill_ratio * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    }

    // Dead-space avoidance: post-residual that is too small to be useful later.
    let min_useful = 10.0;
    if pr < min_useful {
        score -= 15.0; // perfectly filled bin is great
    } else {
        let waste = (pr - min_useful) / cap;
        score += 20.0 * waste * waste * (0.5 + progress);
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 20.0 + 15.0 * (1.0 - progress);
    }

    // Mild pressure from many open bins: encourage consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 + 2.0 * pr_norm);

    // Prefer bins whose residual is close to the mean (balanced packing),
    // with smooth quadratic interaction with progress.
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev * (0.3 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover is divisible
    // by common item granularities (10, 20, 25, 50) are more reusable.
    let mut harmonic_bonus = 0.0;
    if post_residual > 0 {
        if post_residual % 10 == 0 { harmonic_bonus += 6.0; }
        if post_residual % 20 == 0 { harmonic_bonus += 4.0; }
        if post_residual % 25 == 0 { harmonic_bonus += 3.0; }
        if post_residual % 50 == 0 { harmonic_bonus += 5.0; }
    } else {
        // Perfect fit: strongly reward.
        harmonic_bonus += 40.0;
    }
    score -= harmonic_bonus;

    // Dead-space penalty: post_residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Lookahead coupling: reward if the next item fits exactly into post_residual,
    // penalize if next item barely misses this bin's future space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 20.0; // perfect two-step chain
            } else if slack < 10 {
                score += 8.0;  // next item leaves dead space
            } else {
                score -= 4.0;  // still reusable after next item
            }
        } else {
            score += 2.0; // next item won't fit here; mild penalty
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are
    // nearly full or very fragmented. Empty-bin call has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        // Open a new bin when existing bins are well-filled (late stream, high fill)
        // or when there are no open bins at all.
        if open_bins_count == 0 {
            score -= 50.0;
        } else if avg_fill > 0.85 {
            score -= 15.0 * progress;
        } else {
            score += 12.0 + 10.0 * (1.0 - progress);
        }
        // Slight preference to keep bins count low when few bins open.
        score += open_bins_count as f64 * 0.5;
    } else {
        // Prefer tighter bins: scale by fullness fraction (integer-division style).
        let fullness_quotient = (bin_capacity - bin_residual) / 25; // 0..4 classes
        score -= fullness_quotient as f64 * 2.5;
    }

    // Mild penalty for spreading across many bins when mean residual is high.
    if mean_residual > 50.0 && bin_residual != bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1) are pure waste; residuals below a usable threshold
    // for typical items are heavily penalized non-linearly.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0; // unusable sliver penalty
    }

    // Non-linear tight-fit reward: strongly prefer near-perfect fills.
    let fill_ratio = 1.0 - (post_residual as f64) / bin_capacity as f64;
    score -= fill_ratio * fill_ratio * 40.0;

    // Penalize leaving a gap that the lookahead item cannot use.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0; // dead space relative to next demand
        } else {
            // reward if lookahead exactly consumes the gap
            let gap_gap = post_residual - next_item_size;
            if gap_gap < 10 {
                score -= 10.0;
            }
        }
    }

    // Open-bin pressure: encourage filling existing bins when many are open,
    // making the new-bin candidate relatively less attractive.
    score -= (open_bins_count as f64).sqrt() * 2.0;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is
    // badly fragmented (huge mean residual spread / low fill).
    if bin_residual == bin_capacity {
        score += 45.0
            + mean_residual * 0.3
            - (item_size as f64) * 0.4;
        // late in the stream, consolidate more aggressively
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += progress * 15.0;
        }
    }

    // Mild preference for bins with residual close to the item (best-fit core).
    score += (bin_residual as f64 - item_size as f64) * 0.15;

    // Penalize waste relative to the mean residual across open bins:
    // placing into a bin whose leftover deviates far below mean creates outliers.
    if post_residual as f64 > mean_residual * 1.5 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // Reward small post_residual nonlinearly
        score -= 60.0 / (post_residual as f64).sqrt();
    }

    // 2-step lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 400.0;
        } else {
            score -= 150.0 / (1.0 + gap / 10.0);
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // dead space relative to next item: penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Compare against mean residual: prefer bins whose residual is tighter than average
    score += (mean_residual - bin_residual as f64) * 0.8;

    // Last fitting bin: strong incentive to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a new bin, scaled by how many bins already fit the item
    if bin_residual == bin_capacity {
        score += 300.0 + 40.0 * fitting_bins_count as f64;
        // Early in stream, opening bins is cheaper; late in stream, prefer consolidation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 200.0 - progress * 50.0;
        // If next item is large and this new bin would take both, allow it
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space: residuals too small for any plausible future item
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Lookahead: reward if the next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // next item won't fit here; mildly penalize leaving a gap it nearly fits
            let gap = (next_item_size - post_residual) as f64;
            if gap < 10.0 {
                score += 15.0;
            }
        }
    }

    // Last-chance bonus: only one bin fits the item — avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 55.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor
    if bin_residual == bin_capacity {
        // base penalty so open bins with decent fits win
        score += 35.0;
        // but if this is the last chance or fits are all bad, new bin becomes attractive
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
        if post_residual as f64 > mean_residual + 30.0 {
            score -= 20.0;
        }
    }

    // Time horizon: early in the stream, be conservative with open bins;
    // later, prefer consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Many open bins: encourage filling existing bins rather than opening new ones
    score += 0.8 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: prefer bins whose post state approaches the mean
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - pr / cap; // fraction of bin used after placement
    let tight = 1.0 - (bin_residual as f64) / cap;

    let mut score = pr;

    // Non-linear polynomial coupling: reward high fill more strongly as stream progresses
    let fill2 = fill * fill;
    let fill3 = fill2 * fill;
    score -= 30.0 * fill3 * (0.5 + progress);
    score -= 12.0 * fill2 * (1.0 - progress);

    // Smooth penalty on very small residuals (dead space), quadratic in normalized residual
    let rn = pr / cap;
    score += 20.0 * (1.0 - rn) * (1.0 - rn) * (1.0 - rn);

    // Perfect/near-perfect fit bonus (smooth, saturating)
    score -= 15.0 * (-pr / 8.0).exp();

    // Last-chance bin: strong smooth reward
    if fitting_bins_count == 1 {
        score -= 10.0 + 8.0 * fill2;
    }

    // Lookahead coupling: reward leaving room for the next item smoothly
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 6.0 * (-gap / 15.0).exp();
        score += 4.0 * (next_item_size as f64 / cap) * (1.0 - fill3);
    }

    // Global state coupling: many open bins with high mean residual -> prefer consolidating
    let open_norm = (open_bins_count as f64).ln_1p();
    score += 2.0 * open_norm * (1.0 - fill2);
    score -= 3.0 * (mean_residual / cap) * fill3;

    // New-bin candidate: penalize mildly unless current fits are poor
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * (1.0 - tight) * (1.0 - tight);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: hard reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the post-residual: residues divisible by small
    // item sizes (e.g. 10, 20, 25, 50) are more reusable later.
    let r = post_residual;
    if r % 10 == 0 { score -= 6.0; }
    if r % 20 == 0 { score -= 4.0; }
    if r % 25 == 0 { score -= 3.0; }
    if r % 50 == 0 { score -= 5.0; }

    // Dead-space penalty: residuals that no plausible item (1..=100) can
    // be split into cleanly are penalized via integer-division thresholds.
    let small_zone = r / 10; // 0..10 class
    match small_zone {
        0 => score += 20.0,          // 1..9 residual: nearly dead
        1 => score += 8.0,           // 10..19: only tiny items fit
        2 => score += 3.0,
        3 | 4 => score -= 1.0,       // 30..49: decent mid-range zone
        5 | 6 => score -= 2.0,       // 50..69: good zone
        _ => score += 1.0,           // large residual: wasteful for small item
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= r {
            // Reward exact harmonic match between next item and residue class.
            if r % next_item_size.max(1) == 0 {
                score -= 8.0;
            } else {
                score -= 3.0;
            }
            // If next item would fit nearly exactly, strongly prefer.
            let gap = r - next_item_size;
            if gap <= 5 {
                score -= 6.0;
            }
        } else {
            // Next item cannot follow here: penalize, scaled by how badly it misses.
            let miss = (next_item_size - r) as f64;
            score += miss * 0.3;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin is a fallback. Prefer it only
    // when current-bin placement creates large dead space relative to mean.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted early in the stream
        // when many items remain to fill it.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 55.0 + 40.0 * progress;
        // If the current item would leave a very awkward residue in any open bin,
        // opening fresh is more attractive.
        if r > 0 && r < 12 {
            score -= 10.0;
        }
        // If next item is huge, a fresh bin may serve it better.
        if next_item_size >= 70 {
            score -= 8.0;
        }
    }

    // Slight preference for bins with below-average residual (tighter bins first),
    // keeping packing tight as the stream progresses.
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps heavily (dead space avoidance)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    } else if post_residual == 0 {
        // Perfect fit is highly desirable
        score -= 100.0;
    }

    // Reward tight fits: small post_residual relative to item size
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += tightness * 20.0;

    // Open bins pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New bin candidate: penalize unless open bins have poor residuals
    if bin_residual == bin_capacity {
        score += 25.0;
        // If mean residual is large, existing bins are wasteful; allow new bin
        if mean_residual > item_size as f64 * 1.5 {
            score -= 30.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 && next_item_size as f64 == post_residual as f64 {
        score -= 50.0;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here anyway; slight penalty for wasting space
        score += 5.0;
    }

    // Late in stream: prefer consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward exact 2-step lookahead match (post_residual == next_item_size).
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 4 {
        score -= 40.0 + 10.0 * (4 - (post_residual as i64 - next_item_size as i64).abs()) as f64;
    }

    // Penalize dead space relative to mean residual of open bins.
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize so we only open when fits are truly bad.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    // Prefer tight fits overall (low post_residual).
    score += 0.3 * (post_residual as f64).powi(2) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize small post-residuals that are still too small for typical future items
    // (dead space), but reward exact/near-exact fills.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += 12.0 * dead * (1.0 - (post_residual as f64 / bin_capacity as f64));
    } else {
        score -= 40.0; // perfect fill
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to wasted potential.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 + 0.5 * item_size as f64;
    }

    // New-bin candidate handling: opening a bin is only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base cost of opening a new bin, decaying with stream progress and bin count.
        score = bin_capacity as f64 * (0.9 + 0.5 * (1.0 - progress)) + 2.0 * open_bins_count as f64;
        // If many bins fit the item already, opening new is clearly worse.
        if fitting_bins_count > 0 {
            score += 25.0 * fitting_bins_count as f64;
        }
        // If the item is large relative to capacity, a fresh bin is more acceptable.
        score -= 0.3 * item_size as f64;
        // If mean residual across open bins is small, opening a new bin is more justified.
        score -= 3.0 * mean_residual;
    }

    // Global state coupling: when many open bins exist, prefer consolidating into
    // bins with below-average residual (fill the emptiest-feeling bins first).
    if open_bins_count > 1 && bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score -= 0.5 * dev;
    }

    // Time-horizon modulation: early in the stream, be more conservative (favor
    // tight fits even more); late in the stream, prioritize closing bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * (1.0 - progress);
    if progress > 0.8 && post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;

    // Base: wasted space after placement
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream, larger post-residuals are tolerable (more chances to fill);
    // later, small residuals are strongly preferred (tight packing matters).
    let pr_norm = pr / cap;
    let coupling = pr_norm * pr_norm * (1.0 - progress) * 30.0
                 - pr_norm * progress * 12.0;
    score += coupling;

    // Smooth interaction: favor bins whose post-residual matches the lookahead item
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let diff = (pr - nxt).abs() / cap;
        score -= (1.0 - diff * diff) * 6.0 * (1.0 - progress * 0.5);
    }

    // Penalize near-full bins slightly less (they waste little); smooth cubic term
    let fill = 1.0 - pr_norm;
    score -= fill * fill * fill * 4.0;

    // Last-chance bin bonus (smoothly weighted)
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * (1.0 - progress);
    }

    // Mean residual context: deviating from mean residual is penalized quadratically
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 10.0;

    // Slight preference to keep number of open bins moderate as stream progresses
    score += (open_bins_count as f64).ln() * progress * 0.5;

    // Item size interaction: large items prefer tightest fit (smaller post residual)
    score -= (item / cap) * (cap - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer minimal leftover space (tight fits).
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues near capacity fractions are
    // "usable" for typical items; classify dead-space severity.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let post = post_residual;

    // Penalize post_residuals that fall in "dead zones": too small for any
    // item (items >= 1 always fit, but very small residue is near-wasted),
    // and awkward middle ranges that few items match.
    if post > 0 && post < 10 {
        score += 15.0; // unusable sliver
    } else if post >= 10 && post < quarter / 2 {
        score += 4.0; // low utility
    } else if post >= quarter / 2 && post < quarter {
        score -= 3.0; // useful pocket
    } else if post >= quarter && post < half {
        score += 2.0; // moderately awkward
    } else if post >= half && post < (3 * quarter) {
        score -= 5.0; // very reusable
    }

    // Lookahead: if the next item cannot fit into this bin's post-residual,
    // the leftover is likely final dead space -> penalize proportionally.
    if next_item_size > 0 {
        if post < next_item_size {
            score += (next_item_size - post) as f64 * 0.6;
        } else {
            // Reward residuals that can still host the next item.
            score -= (post - next_item_size).min(20) as f64 * 0.3;
        }
        // If next item fits exactly into post_residual, big reward.
        if post == next_item_size && post > 0 {
            score -= 12.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: the empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin wastes the residual of all existing open bins.
        // Penalize new bins when open bins exist and mean residual is healthy.
        if open_bins_count > 0 {
            score += 20.0 + mean_residual * 0.15 + open_bins_count as f64 * 2.0;
        }
        // If no bin fits well elsewhere (this call still competes), allow it:
        // small bonus when the item is large relative to capacity.
        score -= item_size as f64 * 0.1;
    } else {
        // Reward placing into bins whose residual is close to the item size
        // (perfect-fill logic via integer division classes).
        let fit_gap = bin_residual - item_size;
        let bin_class = bin_residual / 10; // decile class of residual
        let item_class = item_size / 10;
        if bin_class == item_class {
            score -= 8.0; // same decile: near-perfect fill
        }
        // Reward depleting bins: residual after placement small relative to mean.
        if mean_residual > 0.0 {
            score -= (1.0 - post as f64 / mean_residual).max(-2.0) * 3.0;
        }
    }

    // Stream progression: late in the stream, avoid opening new bins even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical future items are nearly worthless -> heavy penalty.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward when the leftover can still fit the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // leftover too small for next item: mild dead-space penalty
        score += 3.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (0.8 + 0.7 * progress);

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: keep it attractive only when current fit is poor.
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        // tight fits (small post_residual) make new bin unattractive
        score += 25.0 * (1.0 - fit_quality) - 5.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 4.0; // existing bin serves next item too, avoid new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins that end with zero residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fills the post-residual,
    // this placement sets up a perfect follow-up match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }

    // Softer lookahead: next item fits into the post-residual (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 150.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space penalty: next item cannot use this leftover space.
        let wasted = if next_item_size > post_residual {
            (next_item_size - post_residual) as f64
        } else {
            0.0
        };
        score += 0.5 * wasted;
    }

    // Penalize residuals far below mean_residual (creating unusable slivers).
    let resid = post_residual as f64;
    if resid > 0.0 {
        let dev = resid - mean_residual;
        if dev < 0.0 {
            score += 0.3 * (-dev);
        } else {
            score -= 0.1 * dev;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only prefer it when all open bins would leave large waste.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        // Mild penalty so a decent existing fit beats opening a new bin,
        // but reduced when many bins are open with fragmented residuals.
        score += 120.0 - 0.5 * open_f;
        if next_item_size > 0 && next_item_size <= item_size {
            // New bin keeps room aligned with incoming demand early in stream.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score -= 100.0 * (1.0 - progress);
        }
    }

    // Slight preference for tighter existing fits overall.
    score += 0.05 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is already favored by base term,
    // but amplify it non-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize large leftover fragments that are hard to reuse
    if post_residual > 0 {
        let frag = post_residual as f64;
        if frag < 10.0 {
            score -= 8.0; // tiny dead space is fine (nearly full bin)
        } else {
            score += 0.35 * (frag - 10.0).min(40.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0;
    } else if next_item_size > 0 {
        // next item won't fit here; mildly penalize leaving awkward gap
        score += 0.2 * (next_item_size as f64 - post_residual as f64).min(30.0);
    }

    // Time horizon: early in stream, be more willing to open new bins
    // (keep bins tight); late in stream, consolidate to avoid waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * (1.0 - progress);

    // Global state: many open bins -> prefer filling existing ones
    score += 1.5 * (open_bins_count as f64).ln().max(0.0);

    // Mean residual coupling: if this bin's residual is far below mean,
    // it's a "small" bin; filling it balances residual distribution.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // or no open bin fits well.
    if bin_residual == bin_capacity {
        let big_item_bonus = if item_size >= 60 { -18.0 } else { 0.0 };
        let escape_penalty = if fitting_bins_count == 0 { -30.0 } else { 22.0 };
        score += 15.0 + escape_penalty + big_item_bonus;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 8.0; // new bin can host next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: penalize leftover space, with non-linear (quadratic) shaping
    let mut score = post * (1.0 + norm_post * (1.0 + progress));

    // Smooth coupling: as stream progresses, prefer tighter fills more strongly
    let poly = 0.5 + 1.5 * progress * progress;
    score += norm_post * norm_post * post * poly;

    // Reward near-perfect fits smoothly (small post_residual => big subtraction)
    score -= 40.0 * (-post / 10.0).exp() * (1.0 - progress);

    // Last-chance bin: strong reward so we don't open a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_quality = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 15.0 * fit_quality;
    } else if next_item_size > post_residual {
        score += 5.0 * progress;
    }

    // Discourage opening new bins when many open bins have slack
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64 + mean_residual * 0.05;
    }

    // Mild preference for bins below mean residual (balance-aware)
    score += 0.1 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues near multiples of small divisors
    // indicate "complementary" leftover space likely reusable by future items.
    let pr = post_residual as i64;
    let cap = bin_capacity as f64;

    // Reward post-residuals that fall into friendly harmonic classes
    // (multiples of 10 or 25 leave room for typical item sizes).
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 8.0;
        }
        if pr % 25 == 0 {
            score -= 6.0;
        }
        // Penalize awkward residues in the "dead zone" (1..10 leftover)
        if pr < 10 {
            score += 14.0;
        }
        // Mid-range leftovers (10..30) are moderately reusable
        if pr >= 10 && pr < 30 {
            score -= 4.0;
        }
    }

    // Perfect fit is supreme
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead coupling: if next item exactly fits post_residual, big reward
    if next_item_size > 0 && next_item_size as i64 == pr {
        score -= 120.0;
    }
    // Next item fits comfortably in post_residual
    if next_item_size > 0 && (next_item_size as i64) <= pr {
        score -= (pr - next_item_size as i64) as f64 * 0.5;
        // Harmonic bonus if (item+next) sums to a multiple of capacity/4
        if (item_size + next_item_size) % (bin_capacity / 4) == 0 {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we
    // only open when existing fits are poor, but reward it when the item
    // is large (harmonic class of big items pairs well with fresh space).
    if bin_residual == bin_capacity {
        score += 25.0;
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Tight-fill reward: item consuming >70% of residual is efficient
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.7 && bin_residual < bin_capacity {
        score -= 10.0 * fill_ratio;
    }

    // Penalize creating tiny unusable slivers relative to mean residual state
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.15 && bin_residual < bin_capacity {
        score += 12.0;
    }

    // Slight preference for older bins (first-fit flavor) as stream progresses
    score += (step_index as f64 / total_items.max(1) as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - post_residual as f64 * 2.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward post_residual values that can still host typical future items.
    if post_residual >= 10 {
        score -= 8.0;
        if post_residual >= (next_item_size as u32).min(bin_capacity) && next_item_size > 0 {
            score -= 12.0; // leaves room for the lookahead item
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when current bin would leave a bad gap
    // or the item barely fits nowhere well.
    if bin_residual == bin_capacity {
        let tight_fit_elsewhere = fitting_bins_count > 0
            && (bin_residual.saturating_sub(item_size) < 10 || post_residual == 0);
        if tight_fit_elsewhere {
            score += 80.0; // keep using existing bins when they fit well
        } else {
            score += 5.0; // slight default penalty for opening new bins
        }
    }

    // Penalize bins far below mean residual (fragmenting behavior) mildly.
    if (bin_residual as f64) > mean_residual + 20.0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    score += 0.5 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // 2-step lookahead: reward post_residual that matches the next item size exactly,
    // penalize wasted space that the next item cannot consume.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if gap == 0.0 {
            score -= 30.0; // perfect chain: next item fits exactly
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - gap / bin_capacity as f64); // next item still fits
        } else {
            score += 0.6 * gap; // next item won't fit here: dead space risk
        }
    }

    // Compare against mean residual: bins already fragmented are less valuable targets.
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item is large (little residual waste)
    // or the stream is early (many future items to fill it).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_capacity - item_size) as f64;
        score = waste * (1.5 - progress) + 20.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0; // new bin can also chain the next item
        }
        if fitting_bins_count == 1 {
            score += 40.0; // don't abandon the only fitting open bin
        }
    }

    // Slight preference for consolidating into fewer bins as bins accumulate.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect or near-perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Penalize large dead space that small future items could still use.
    if post_residual > 40 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted potential.
            score += 5.0 * (1.0 - post_residual as f64 / next_item_size as f64).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Time horizon: early in the stream, prefer consolidating into fewer bins;
    // later, be more selective about fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 8.0 * (1.0 - fit_ratio);
    score += progress * 4.0 * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> encourage filling them.
    if open_bins_count > 2 {
        score -= (mean_residual - post_residual as f64).abs() * 0.15;
    }

    // New-bin candidate handling: only attractive when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.75;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        } else {
            // Penalize opening a new bin when existing bins have good residuals.
            score += 40.0 * (1.0 - (mean_residual / bin_capacity as f64).min(1.0));
            if next_item_size > 0 && next_item_size >= item_size {
                score -= 20.0; // fresh bin can serve the next item too
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let norm_post = post / cap;

    // Base: quadratic waste penalty (smooth, non-linear in residual)
    let mut score = norm_post * norm_post * cap;

    // Cubic coupling with stream progress: later in the stream, waste hurts more
    score += norm_post.powi(3) * cap * (0.5 + progress);

    // Interaction between post_residual and mean residual: prefer bins whose
    // leftover after placement aligns with the fleet's average residual
    let mean_gap = (post - mean_residual) / cap;
    score += 12.0 * mean_gap * mean_gap;

    // Lookahead: reward residuals that can host the next item exactly-ish
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if post >= ns {
            let slack = (post - ns) / cap;
            score -= 8.0 * (1.0 - slack * slack); // smooth reward for good lookahead fit
        } else {
            score += 6.0 * ((ns - post) / cap); // penalize stranding next item
        }
    }

    // Last-chance bin: strong discount so we don't open a new bin needlessly
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (item_size as f64) / (bin_residual as f64).max(1.0);
    }

    // New-bin candidate: penalize mildly, more so early and when many bins are open
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score = cap * (1.2 + 0.15 * open_pressure + 0.8 * progress);
    }

    // Tie-breaker: slight preference for tighter existing bins
    score += (bin_residual as f64) / cap * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with a concave (harmonic) penalty
    // so that small dead space is punished disproportionately.
    let mut score = if post_residual == 0 {
        -50.0 // perfect closure is always excellent
    } else {
        pr + 40.0 / pr // harmonic term: harsh on pr=1..5 dead space
    };

    // Harmonic class of the post residual: residuals that are "nice" fractions
    // of capacity (multiples of 10, and especially 50/25/20) are reusable.
    let class_bonus = if post_residual % 50 == 0 {
        12.0
    } else if post_residual % 25 == 0 {
        9.0
    } else if post_residual % 20 == 0 {
        8.0
    } else if post_residual % 10 == 0 {
        6.0
    } else if post_residual % 5 == 0 {
        3.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Lookahead: reward if the next item fits exactly or well into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 30.0; // next item closes this bin perfectly
        } else {
            score -= 18.0 / gap; // strong reward for near-perfect chaining
        }
    } else if next_item_size > 0 {
        // Next item cannot use this residual: penalize proportionally to wasted space.
        score += 0.15 * pr;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 + 0.2 * (item_size as f64);
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when existing fits are bad (large post_residual)
        // or when there are no fitting bins at all. Otherwise discourage spreading.
        let pressure = if fitting_bins_count == 0 {
            -100.0
        } else {
            (pr - 15.0) * 0.8 + (open_bins_count as f64) * 1.5
        };
        score += pressure;
        // Late in the stream, slightly favor consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
    }

    // Mild preference to fill bins that are already relatively full
    // (low residual relative to mean): keeps many bins near closure.
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / cap;
        score -= 4.0 * rel;
    }

    // Penalize leaving residuals in the "dead zone" 1..=9 that few items (min size 1
    // but typical stream items) can use, scaled by how many bins are open.
    if post_residual >= 1 && post_residual <= 9 {
        score += 6.0 + 0.3 * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to ever fit anything are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward tight fits (small but usable leftover).
    if post_residual > 0 && post_residual <= 15 {
        score -= 12.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Prefer bins whose residual is close to the item (minimize fragmentation).
    let waste = (bin_residual as f64 - item_size as f64).max(0.0);
    score += 0.35 * waste;

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Mean-residual coupling: if open bins are already mostly full, keep using them.
    score -= 0.5 * mean_residual;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: bonus if the next item fits the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // creating a gap the next item cannot use
    }

    // New-bin candidate: make it attractive only when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = item_size as f64 > bin_residual as f64 * 0.8;
        if open_bins_count == 0 || (poor_fit && mean_residual < 20.0) {
            score -= 15.0;
        } else {
            score += 20.0 + 3.0 * open_bins_count as f64;
        }
    }

    // Early stream: slightly prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base: prefer tight fits (low post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Exact match: big bonus; near match: graded bonus
        let lookahead_bonus = if diff == 0.0 {
            120.0
        } else if diff <= 10.0 {
            80.0 - diff * 4.0
        } else if diff <= 25.0 {
            40.0 - diff
        } else {
            0.0
        };
        score -= lookahead_bonus;
        // Penalize leaving residual too small for next item (dead space)
        if post_residual < next_item_size {
            score += 15.0 + (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so mid-stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += 60.0 + 40.0 * progress;
        // But if lookahead would be perfectly served by a fresh bin, soften
        if next_item_size > 0 && (bin_capacity - item_size) as i64 == next_item_size as i64 {
            score -= 90.0;
        }
    }

    // Mild preference for filling bins when many are open
    score -= (open_bins_count as f64).ln().max(0.0) * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a superlinear penalty on slack.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness * (item_size as f64);

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize leaving dead space that is too small for typical items (1..=10 useless).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64));
        } else {
            // Next item won't fit here; slight penalty proportional to wasted potential.
            score += 5.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Time horizon: early in the stream, be more conservative (favor filling existing bins);
    // later, allow more exploration of new bins for better global packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, relax later; also penalize when many bins open.
        let mut new_bin_score = 30.0 - 25.0 * progress;
        new_bin_score += 2.0 * (open_bins_count as f64).sqrt();
        // If mean residual is large, existing bins have room; discourage new bin.
        new_bin_score += 0.3 * mean_residual;
        // If item is large and mean residual is small, new bin is attractive.
        new_bin_score -= 0.4 * (item_size as f64) * (1.0 - mean_residual / bin_capacity as f64);
        score += new_bin_score;
    } else {
        // Existing bin: mild reward grows with progress to consolidate.
        score -= 4.0 * progress;
    }

    // Prefer bins whose residual is below mean (consolidate the emptier bins less).
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score += 0.15 * (mean_residual - bin_res_f);
    } else {
        score -= 0.15 * (bin_res_f - mean_residual);
    }

    // Mild penalty for spreading across many open bins.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, but discount dead space non-linearly.
    let mut score = pr as f64;

    // Quadratic dead-space penalty: small residuals are disproportionately bad.
    score += 30.0 * norm_pr * norm_pr;

    // Smooth progress coupling: early on, be tolerant; later, punish waste more.
    score *= 0.6 + 0.8 * progress * progress;

    // Lookahead synergy: reward bins whose post-residual fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = 1.0 - ((post_residual - next_item_size) as f64) / cap;
        score -= 12.0 * snug * snug;
    } else if next_item_size > 0 {
        // Penalize leaving a residual just below the next item (dead space).
        score += 6.0 * (next_item_size as f64 - pr) / cap;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild pressure against scattering across many open bins.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins whose residual deviates from the mean (consolidate slack).
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but never let post_residual become a "dead zone".
    if post_residual > 0 {
        // Dead space penalty grows superlinearly for small, unusable residues.
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 6.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Harmonic class of post_residual modulo 10: residues divisible by 10 or 5
    // are more likely reusable by typical item sizes.
    let pr = post_residual;
    let class_bonus: f64 = match pr {
        0 => 25.0,
        x if x % 10 == 0 => 18.0,
        x if x % 5 == 0 => 8.0,
        x if x % 2 == 0 => 3.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size <= pr {
            // Next item fits: reward proportional to how well it fills.
            let fill = next_item_size as f64 / pr.max(1) as f64;
            score -= 10.0 + 25.0 * fill;
        } else {
            // Next item cannot fit: penalize proportionally to overshoot.
            let over = (next_item_size - pr) as f64;
            score += (over / 10.0).min(8.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
        if post_residual <= 20 {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer it when the item is large or no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Penalize opening new bins mildly; stronger early when bins are few.
        let new_bin_penalty = 55.0 + 20.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // But if item is huge relative to capacity, new bin is attractive.
        let big_item_relief = if item_size >= 60 { 45.0 } else { 0.0 };
        score += new_bin_penalty - big_item_relief;
        // If next item is also large, reserving a fresh bin helps.
        if next_item_size >= 70 {
            score -= 20.0;
        }
    }

    // Coupling with mean residual: bins far from the mean residual that would
    // end up very empty are less attractive (keep bins homogeneous).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Integer-division threshold: post_residual in [20, 40) is a "sweet spot"
    // that many mid-size items (20..40) can still fill.
    if (20..40).contains(&pr) {
        score -= 10.0;
    } else if (40..60).contains(&pr) {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest item are pure waste.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item + 9 {
        score += 60.0;
    }
    // Gap unusable for the lookahead item: strong penalty unless gap is large anyway.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits (low post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins with residual below the mean (consolidate space).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: neutral baseline, but discourage early / when good fits exist.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.85
            + 0.5 * open_bins_count as f64
            + 10.0 * (1.0 - progress);
        // If this is the only fitting option, allow opening.
        if fitting_bins_count <= 1 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect 2-item packing: strongly favored.
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Next item still fits: mild reward proportional to leftover after both.
            let two_step_left = post_residual - next_item_size;
            score -= 25.0 - (two_step_left as f64) * 0.3;
        } else {
            // Next item won't fit in residual: penalize dead space creation.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // Last item: prefer tightest fit, slight bonus for emptying bin.
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Relative to mean residual: placing in a below-average-residual bin is a good fit.
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate penalty: discourage opening a new bin unless current bins
    // are truly poor fits. Scale with stream progression.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 20.0 * progress;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Prefer filling nearly-full bins to close them out.
    if post_residual <= 5 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Reward leaving usable space for the next item, scaled by how well it fits.
            let nxt_fit = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 15.0 * nxt_fit;
        } else {
            // Penalize leaving space the next item cannot use (dead space risk).
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize opening new bins when many bins are already open and fit is mediocre.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a bin.
        score += 20.0;
        // Opening a new bin is more attractive late in the stream or when open bins are crowded.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
        if open_bins_count > 0 && mean_residual < item_size as f64 {
            score -= 12.0; // existing bins too full -> new bin reasonable
        }
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 15.0; // next item won't fit an empty residual? it will (residual=capacity); keep neutral
            score += 15.0;
        }
    } else {
        // Slight bonus for reusing existing bins to keep bin count low.
        score -= 5.0;
        // Penalize very small leftovers that are hard to reuse later.
        if post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
    }

    // Mild penalty when this bin's residual deviates far from the mean (fragmentation control).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    let mut score = pr as f64;

    // Non-linear coupling of post residual with stream progress:
    // early on, prefer tight fits (low post residual); later, dead space
    // matters even more as chances to reuse it shrink.
    let tightness = (1.0 - x) * (1.0 - x); // smooth quadratic tightness
    let urgency = progress * progress;
    score -= 12.0 * tightness * (1.0 + urgency);

    // Cubic penalty for very small unusable slivers (dead space), smoothly
    // scaled by how much of the stream remains.
    let remaining = 1.0 - progress;
    score += 20.0 * x * x * x * (1.0 + remaining);

    // Reward bins whose residual closely matches the item (smooth kernel).
    let fit_quality = 1.0 - ((bin_residual as f64 - item_size as f64) / cap).abs();
    score -= 8.0 * fit_quality * fit_quality;

    // Lookahead: if next item would fit in post residual, reward this bin.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let chain = next_item_size as f64 / cap;
        score -= 10.0 * chain * (1.0 - urgency);
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty when this bin's residual is far below the mean residual
    // (i.e., it's already tightly packed; save loose bins for future items).
    let dev = (mean_residual - bin_residual as f64) / cap;
    score += 3.0 * dev * dev.abs();

    // New-bin candidate: neutral baseline with slight late-stream penalty
    // to discourage proliferation of open bins as the stream ends.
    if bin_residual == bin_capacity {
        score += 2.0 + 6.0 * progress * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in low classes (1..10) is nearly unusable.
    let pr = post_residual;
    if pr > 0 && pr <= 10 {
        score += 12.0; // tiny sliver: strong penalty
    } else if pr <= 20 {
        score += 4.0;
    } else if pr <= 40 {
        score -= 2.0; // sweet spot: half-ish fills pair with mid-size items
    } else if pr <= 60 {
        score -= 1.0;
    }

    // Exact fit or modulo-friendly residual (divisible by common size classes 5,10,20)
    if pr == 0 {
        score -= 15.0;
    } else if pr % 10 == 0 {
        score -= 3.0;
    } else if pr % 5 == 0 {
        score -= 1.5;
    }

    // Lookahead coupling: if next item fits into post_residual, reward heavily.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 8.0;
        // bonus if next item lands in a harmonic class of post_residual
        if pr % next_item_size.max(1) == 0 {
            score -= 4.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // next item won't fit here anyway; slight reward for using residual now
        score -= 1.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let base = 25.0 + 2.0 * open_bins_count as f64;
        score = base + item_size as f64 * 0.3;
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a bin anyway
        }
        // large items early justify fresh bins
        if item_size > 60 {
            score -= 6.0;
        }
        // late in stream, prefer consolidation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Prefer tighter bins when residuals are plentiful overall
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_limit: f64 = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_limit {
        score += (dead_limit - post_residual as f64) * 6.0;
    }
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Reward tight fits (small but usable residual is better than large waste).
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 10.0 * tightness;
    }

    // Penalize residual that cannot fit the lookahead item (creates stranded space),
    // but reward residuals that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 5.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // when few bins are open, opening a new bin is less costly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 3.0;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Deviation from mean residual: prefer bins that are already low (consolidation).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.3;

    // New-bin candidate: only attractive when the item fits poorly everywhere else,
    // i.e., when this empty bin would yield a roomy post_residual and pressure is low.
    if bin_residual == bin_capacity {
        let waste_here = (bin_capacity - item_size) as f64;
        score = waste_here * 0.9 + pressure * 2.0;
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Aggressive 2-step lookahead: reward bins where next item fits perfectly after this one.
    if next_item_size > 0 {
        let lookahead_gap = post_residual as i64 - next_item_size as i64;
        if lookahead_gap == 0 {
            // Perfect 2-item packing: strongly favor this bin.
            score -= 80.0;
        } else if lookahead_gap > 0 {
            // Next item fits with slack; reward proportionally to tightness.
            let tight = 1.0 - lookahead_gap as f64 / bin_capacity as f64;
            score -= 40.0 * tight;
            if (lookahead_gap as u32) < 10 {
                score -= 15.0; // near-perfect chain
            }
        } else {
            // Next item won't fit after this placement; mild penalty scaled by overflow.
            score += (lookahead_gap.abs() as f64).min(50.0) * 0.5;
        }
        // Reward if post_residual is closest to next_item_size relative to mean residual.
        let dist = (post_residual as f64 - next_item_size as f64).abs();
        let mean_dist = (mean_residual - next_item_size as f64).abs();
        if mean_dist > 1e-9 {
            score -= 20.0 * (1.0 - (dist / mean_dist).min(1.0));
        }
    } else {
        // Last item: just minimize post residual, already done by base score.
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Prefer fuller bins relative to mean residual (best-fit flavor).
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Early in the stream, allow opening fresh bins slightly more readily;
    // late in the stream, squeeze every open bin harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses so we reuse bins late.
        score += 30.0 + 40.0 * progress;
        if next_item_size > 0 && bin_capacity as f64 - next_item_size as f64 >= item_size as f64 {
            // New bin can host a perfect 2-chain with next item; discount penalty.
            score -= 25.0;
        }
    }

    // Slight penalty for proliferating many open bins early.
    if open_bins_count > 8 && progress < 0.5 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 18.0 * tightness;

    // Penalize dead space: post_residual too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Lookahead: bonus if next item can fit into post_residual (chained packing)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 14.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty scaled by wasted potential
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Spread pressure: when many bins are open, prefer filling fuller bins
    let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score -= open_pressure * (bin_residual as f64 - post_residual as f64) * 0.05;

    // Global residual alignment: prefer bins whose residual is near mean
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    // Time horizon: late in stream, be more conservative (avoid new bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: only attractive if no good fit exists
    if bin_residual == bin_capacity {
        score += 20.0 + 12.0 * (1.0 - progress);
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer low post residual, smoothed non-linearly
    let x = post / cap;
    let mut score = post * (1.0 + 0.8 * x * x);

    // Reward tight fits (small post residual) more strongly as stream progresses
    let tightness = 1.0 - x;
    score -= tightness * tightness * item * (0.5 + 1.5 * progress);

    // Penalize dead space: post residual too small to fit any plausible item
    let dead = if post_residual < 10 { 1.0 } else { 0.0 };
    score += dead * (30.0 * (1.0 - progress) + 10.0);

    // Last-chance bonus: only bin that fits -> strong reward to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this bin's post residual is large (wasteful fit) and stream is early
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 - 10.0 * progress;
        // discourage new bin if next item could use the leftover here
        if (next_item_size as f64) <= post && next_item_size > 0 {
            score += 20.0;
        }
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        if gap >= 0.0 {
            score -= 5.0 * (1.0 - (gap / cap).abs());
        } else {
            score += 3.0 * (-gap / cap);
        }
    }

    // Mild penalty for proliferating bins relative to mean residual
    score += 0.05 * open_bins_count as f64 * (1.0 - progress) * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues that are hard to fill later
    // (small but nonzero) are penalized; zero residual is a perfect close.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    if post_residual == 0 {
        score -= 60.0; // perfect fit, strongly favored
    } else {
        // modulo classes on post_residual relative to capacity fractions
        let q = post_residual * 4 / bin_capacity; // quarter class 0..3
        match q {
            0 => score -= 25.0,  // residual <= cap/4: small leftover, good
            1 => score += 8.0,   // residual in (cap/4, cap/2]
            2 => score += 3.0,   // residual in (cap/2, 3cap/4]
            _ => score += 12.0,  // large leftover
        }
        // fine-grained harmonic penalty: leftover that no typical item (1..100)
        // can be guaranteed to fill; penalize residuals < 10 strongly
        if post_residual < 10 {
            score += 18.0;
        }
        // residue class mod 10: residuals that are multiples of 10 are easier
        // to fill exactly with common item sizes
        if post_residual % 10 == 0 {
            score -= 6.0;
        } else {
            score += (post_residual % 10) as f64 * 0.5;
        }
    }

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // partial lookahead fit: reward proportional to fill ratio
            score -= 10.0 * (next_item_size as f64 / pr.max(1.0));
        } else {
            // next item cannot use this leftover: penalize proportionally
            score += 5.0 * (1.0 - pr / cap);
        }
    }

    // Last chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin gives
    // a good fit (i.e., current best-fit residual is large relative to item)
    if bin_residual == bin_capacity {
        // virtual new bin: score = leftover capacity it would have
        // discourage unless existing fits are poor; the tightness of this item
        // in open bins is reflected through their (lower) scores already.
        score = (bin_capacity - item_size) as f64;
        // slight preference to open new bins early in the stream is unnecessary;
        // but avoid opening new bins when item is tiny and many bins are open
        if item_size < 20 && open_bins_count > 2 {
            score += 15.0;
        }
        // if next item is large, a fresh bin may be valuable
        if next_item_size > 70 {
            score -= 5.0;
        }
    }

    // mild preference for bins with below-mean residual (denser bins)
    if bin_residual < bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item
    // (min item size 1, but practically < 20 is hard to reuse) are heavily penalized.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 12.0; // up to +228 for worst dead space
    }
    // Zero residual = perfect fit: strong reward.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Reward tight fits generally (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= tightness * 40.0;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
        // but if it creates dead space that can't fit the next item, soften the discount
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 60.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 15 {
        score -= 30.0;
    }

    // Open-bin pressure: penalize creating more bins when many are already open.
    if bin_residual == bin_capacity {
        // candidate new bin: only attractive if no open bin fits well
        if fitting_bins_count == 0 {
            score -= 200.0;
        } else {
            // discourage opening new bins when fitting bins exist
            score += 80.0 + 6.0 * open_bins_count as f64;
            // even more if open bins are relatively empty (room to consolidate)
            if mean_residual / bin_capacity as f64 > 0.5 {
                score += 50.0;
            }
        }
    } else {
        // placing into existing bins reduces open-bin pressure slightly
        score -= 2.0 * open_bins_count as f64;
    }

    // Late in the stream: prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 25.0;
    }

    // Prefer bins whose residual is close to mean (keep residuals balanced),
    // unless a very tight fit is available.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let gap = (post_residual as f64 - nxt) / cap;
            score -= 60.0 * (1.0 - gap); // prefer post_residual close to next item
        } else {
            // next item won't fit here; penalize proportionally
            score += 25.0 * ((nxt - post_residual as f64) / cap);
        }
        // exact exact-match bonus
        if post_residual == next_item_size {
            score -= 80.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize creating small unusable dead space (< smallest item)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Early stream: be conservative, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress);

    // New-bin candidate: penalize so it's only chosen when open bins fit badly
    if bin_residual == bin_capacity {
        score += 150.0 + mean_residual * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize waste relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 30.0;

    // Penalize post-residuals that are small but unusable for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space for the known next item.
        score += 8.0;
    }

    // Time horizon: early in the stream, be conservative (prefer filling existing bins);
    // later, opening fresh bins is less costly so new-bin option becomes viable.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized more when few bins are open and early in stream.
        let open_penalty = 20.0 + 30.0 * (1.0 - progress);
        // But if mean residual across open bins is small (all bins nearly full),
        // opening a new bin is reasonable.
        let mean_relief = (mean_residual / bin_capacity as f64) * 25.0;
        score += open_penalty - mean_relief;
    }

    // Prefer placing into bins whose residual is close to the mean (balance load),
    // slightly discouraging extreme outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Mild pressure to consolidate when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits less aggressively; Late: strongly minimize post_residual.
    let tightness = norm_pr * norm_pr * (1.0 + 2.0 * progress);
    score += 12.0 * tightness;

    // Reward filling bins deeply, scaled by how much of the bin the item consumes.
    let fill_frac = item_size as f64 / cap;
    score -= 30.0 * fill_frac * (0.5 + 0.5 * progress) * (1.0 - norm_pr);

    // Dead-space penalty: small post_residual that next item can't use is bad.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            // unusable gap: penalize quadratically, worse late in stream
            let gap = (pr / nx) * (pr / nx);
            score += 8.0 * (1.0 - gap) * (0.3 + 0.7 * progress);
        } else {
            // next item fits exactly-ish: reward smooth cubic in fit quality
            let fit_q = 1.0 - ((pr - nx) / cap);
            score -= 6.0 * fit_q * fit_q * fit_q;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr) * (0.5 + 0.5 * progress);
    } else if fitting_bins_count > 2 {
        // many options: mild penalty for leaving very small fragments
        score += 4.0 * (1.0 - norm_pr) * norm_pr;
    }

    // Coupling with mean residual: prefer bins close to the mean (balance),
    // with smooth quadratic interaction and progress modulation.
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev * (1.0 - progress);

    // New-bin candidate: prefer opening fresh bins early; discourage late.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score += 10.0 * (1.0 - progress) * (1.0 - progress) - 5.0 * progress;
        // opening a bin when few exist is natural
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * progress;
    }

    // Mild preference for consolidating into fewer bins overall.
    score += 0.5 * (open_bins_count as f64) * norm_pr * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition residuals into capacity-fraction classes.
    // Class 0: post_residual == 0 (perfect fill) -> heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Integer-division thresholds: residual classes of capacity/8.
    let eighth = bin_capacity / 8; // 12
    let quarter = bin_capacity / 4; // 25
    let half = bin_capacity / 2; // 50

    // Dead-space penalty: residual too small for the smallest plausible item (1..100 range,
    // but tiny residuals < eighth are nearly unusable).
    if post_residual > 0 && post_residual < eighth {
        score += 60.0;
    }

    // Harmonic class: how well post_residual aligns with common item sizes.
    // Reward residuals that sit in "harmonic" slots (multiples of quarter classes),
    // since future items can tile them exactly.
    let class = post_residual / quarter;
    match class {
        0 => score -= 5.0,                 // 0..24: small but potentially fillable
        1 => score -= 15.0,                // 25..49: quarter-class, good slot
        2 => score -= 10.0,                // 50..74: half-class slot
        3 => score -= 2.0,                 // 75..99
        _ => {}
    }

    // Modulo arithmetic: residuals divisible by common item granularities are reusable.
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            // Reward proportionally to how tightly next item fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize large wasted residuals mildly.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is huge and
    // no open bin offers a good fit.
    if bin_residual == bin_capacity {
        let tight_exists = post_residual < eighth; // impossible for empty bin; use item fit logic
        let _ = tight_exists;
        // Base penalty for wasting a new bin; reduced if item is large relative to capacity.
        let frac = item_size as f64 / bin_capacity as f64;
        score += 180.0 - 120.0 * frac;
        // If many bins are open with slack, discourage new bin further.
        score += 4.0 * open_bins_count as f64;
    }

    // Stream progression: early on, prefer tight packing (minimize post_residual harder);
    // later, be more permissive to consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if this bin is far from the mean residual, adjust.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..~20)
    // are effectively unusable; penalize them super-linearly.
    let dead_threshold = 20.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * (dead_threshold - post_residual as f64) * 2.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score -= (1.0 - fit_ratio.min(1.0)) * 15.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
        if next_item_size == post_residual {
            score -= 30.0;
        }
    } else if next_item_size > post_residual {
        // Post-residual too small for next item: mild penalty scaled by how close.
        score += 5.0;
    }

    // Open-bin pressure: discourage spreading across many bins when alternatives exist.
    if fitting_bins_count > 1 {
        score += (open_bins_count as f64) * 0.5;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer new bin only when existing fits are terrible.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced late in the stream.
        score = 60.0 + (open_bins_count as f64) * 0.3;
        // If nothing fits well (large dead space would be created elsewhere), new bin is attractive.
        if (post_residual as f64) >= 0.0 && (bin_residual as f64) - (item_size as f64) >= dead_threshold {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
    }

    // Slight mean-residual coupling: prefer bins whose residual is below mean (tighter bins).
    score += ((mean_residual - bin_residual as f64) * 0.1).clamp(-5.0, 5.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: post residual of 0 is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space quadratically (hard-to-fill slivers).
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 5.0;
        }
    }

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            // Next item fits: good chain, but prefer tight chains.
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Next item does NOT fit after this placement: penalize
            // proportionally to the leftover gap wasted for next item.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Prefer bins with residual below mean (tighter bins first),
    // scaled by stream progress to consolidate early.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (bin_residual as f64 - mean_residual) * (0.3 + 0.7 * progress);

    // New-bin candidate: penalize opening a new bin unless the item is
    // large and no good fit exists (encourage filling open bins).
    if bin_residual == bin_capacity {
        score += 120.0 - 1.2 * item_size as f64;
        if fitting_bins_count <= 1 && item_size > bin_capacity / 2 {
            score -= 200.0;
        }
    }

    // Mild preference for placing into already-open bins as stream matures.
    score += open_bins_count as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Penalize leaving awkward dead space (small post-residuals that can't hold much).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * next_fit;
        } else {
            // Next item won't fit here: mild penalty proportional to leftover.
            score += 3.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor
    // or the stream is late and bins are scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        let poor_fits = (mean_residual - item_size as f64).abs() / bin_capacity as f64;
        let bonus = 25.0 * (1.0 - poor_fits) + 10.0 * scarcity + 8.0 * progress;
        score = bin_capacity as f64 - bonus;
    }

    // Global pressure: many open bins with high mean residual → prefer consolidation.
    if open_bins_count > 2 {
        score -= 2.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;
    }

    // Late-stream consolidation: favor filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * 4.0; // smooth bump peaking mid-residual
    score -= poly * cap * (0.35 + 0.5 * progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.0 + progress);
        } else {
            score -= 0.25 * (pr - nxt).min(20.0);
        }
    } else {
        // Last item: strongly prefer tightest fit
        score += 0.0;
    }

    // Last-chance bonus: only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0 + 12.0 * progress;
    }

    // Mild pressure to keep mean residual balanced
    score += 0.05 * (mean_residual - pr).abs();

    // New-bin candidate: prefer it only when open bins are nearly full
    if bin_residual == bin_capacity {
        let tight = (mean_residual / cap).max(0.0).min(1.0);
        score -= 3.0 * (1.0 - tight) * (1.0 - tight);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual buckets by capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac <= 0.001 {
        score -= 40.0; // perfect fit, huge reward
    } else if post_residual <= 10 {
        score -= 30.0; // near-perfect: dead space below min item size
    } else if post_residual <= 20 {
        score -= 12.0;
    } else if post_residual <= 30 {
        score -= 4.0;
    }

    // Modulo classes: residuals that are multiples of common item sizes pair well
    let m = post_residual % 10;
    if m == 0 {
        score -= 6.0; // residual on harmonic grid (items are multiples of 10-ish)
    } else if m <= 3 {
        score += 3.0 * (m as f64); // small awkward remainder
    }

    // Integer-division thresholds on next_item_size vs post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0; // lookahead item can also fit here
            let quot = post_residual / next_item_size.max(1);
            if quot >= 2 {
                score -= 4.0; // room for multiple future items
            }
        } else {
            // next item won't fit: penalize proportional to leftover awkwardness
            let gap = next_item_size - post_residual;
            score += 2.0 + gap as f64 * 0.05;
        }
    }

    // Last-chance bin before opening a new bin: strong bonus if decent fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin when fit is good elsewhere
    if bin_residual == bin_capacity {
        score += 25.0;
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        // late in stream, prefer consolidating
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * (1.0 - progress);
    }

    // Prefer filling bins below mean residual (tighter bins first)
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.1;
    } else {
        score += (res_f - mean_residual) * 0.05;
    }

    // Penalize large item into nearly-full bin leaving tiny residue handled above;
    // penalize wasting large residual on small item
    if item_size < post_residual / 4 && post_residual > 40 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, minimum item size)
    // are the worst outcome — penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Near-dead space: gaps that almost nothing can use later
    if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Reward tight fits (small post_residual relative to item size)
    if post_residual > 0 {
        score -= (item_size as f64 / post_residual as f64) * 8.0;
    } else {
        // Perfect fit: strongly rewarded
        score -= 45.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage
    // filling existing bins; few open bins -> allow opening new ones.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: only attractive when the item fits poorly
    // everywhere or bins are congested.
    if bin_residual == bin_capacity {
        // Base new-bin score: slightly worse than a perfect fit, better than dead space.
        score = bin_capacity as f64 * 0.35;
        // If this bin is the last chance among open bins, opening a new bin is bad.
        if fitting_bins_count == 1 {
            score += 70.0;
        }
        // Large item: prefer to start fresh so future small items can fill gaps.
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
        // Congestion: many open bins with high mean residual -> opening new bin
        // is wasteful.
        if mean_residual > 30.0 && open_bins_count > 3 {
            score += 25.0;
        }
    }

    // Lookahead: if the next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    }

    // Late in the stream: be more conservative, prefer filling existing bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += progress * 4.0 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = (post_residual - next_item_size) as f64;
        score -= 100.0 + slack_after_next * 0.5;
    }

    // Penalize dead space relative to mean residual: creating small residuals
    // that are below the mean wastes capacity.
    let dead = post_residual as f64 - mean_residual;
    if dead < 0.0 {
        score += (-dead) * 0.8;
    } else {
        score -= dead * 0.1;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin, but less when the item is
    // large (poor fit elsewhere) or many bins are already open.
    if bin_residual == bin_capacity {
        let large_item_bonus = item_size as f64 / 100.0;
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 300.0 - large_item_bonus * 200.0 - open_pressure * 20.0;
    }

    // Mild bonus for filling larger fraction of bin now.
    score -= (item_size as f64 / bin_capacity as f64) * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (dead space minimization).
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap; // 1.0 = perfect fill
    score -= 18.0 * tightness * tightness;

    // Penalize leaving residuals that no plausible item can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny sliver: almost unusable dead space
    } else if post_residual >= 10 && post_residual <= 80 {
        // residual in the item-size range is reusable; mild reward
        score -= 6.0;
    }

    // Lookahead coupling: reward if next item fits the post-residual exactly well.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
        score -= 30.0; // perfect chain fill
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't fit here anyway; slight penalty if we over-consumed
        score += 4.0;
    }

    // Last-chance bin logic: if this is the only fitting bin, strongly prefer
    // using it rather than opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
        // but if the fit creates big dead space, soften the reward
        if post_residual > 50 {
            score += 10.0;
        }
    }

    // New-bin candidate: only attractive when fit into open bins would be bad.
    if bin_residual == bin_capacity {
        // base cost of opening a bin; offset by how many alternatives exist
        let mut nb = 14.0 + 2.0 * (open_bins_count as f64).sqrt();
        if post_residual == bin_residual { // item placed alone in fresh bin
            if fitting_bins_count == 0 {
                nb = 0.0; // forced
            } else if item_size as f64 / cap > 0.75 {
                nb -= 12.0; // large item: fresh bin is fine
            }
        }
        score += nb;
    }

    // Global state: many open bins with high mean residual -> consolidate.
    if open_bins_count > 2 && mean_residual > (item_size as f64) * 1.5 {
        score -= 3.0;
    }

    // Time horizon: early in stream, keep flexibility (avoid bad fits);
    // late in stream, squeeze harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;
    score += 8.0 * (1.0 - progress) * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = pr / cap; // normalized post residual

    // Base: tight fits preferred, non-linear penalty on wasted space
    let mut score = pr as f64;
    score += 40.0 * fit_frac * fit_frac * cap;

    // Reward bins whose residual closely matches the item (smooth coupling)
    let slack = (bin_residual as f64 - item_size as f64) / cap;
    score -= 30.0 * (1.0 - slack * slack).abs();

    // Stream-progress coupling: as stream advances, penalize large residuals more
    score += 25.0 * progress * fit_frac * fit_frac;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - fit_frac);
    }

    // New-bin candidate: penalize opening new bins unless residual would be large waste
    if bin_residual == bin_capacity {
        let new_bin_penalty = 90.0 - 40.0 * progress;
        score += new_bin_penalty;
        // If item nearly fills a bin, opening is attractive
        score -= 70.0 * (item_size as f64 / cap);
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= pr {
            let tightness = 1.0 - (pr - next) / cap;
            score -= 45.0 * tightness * tightness;
        } else {
            // penalize leaving a residual nothing can use
            score += 15.0 * fit_frac;
        }
    }

    // Mild penalty for spreading across many bins
    score += (open_bins_count as f64) * 1.5;

    // Mean residual coupling: prefer bins near the mean (keeps residuals uniform)
    let dev = (pr - mean_residual).abs() / cap;
    score -= 10.0 * (1.0 - dev);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fraction via integer division thresholds.
    let item_class = item_size / 13; // 0..6 harmonic bands (13,26,39,52,65,78)
    let next_class = next_item_size / 13;

    // Base tightness reward: strongly prefer small post_residual.
    score -= 0.6 * (bin_capacity as f64 - post_residual as f64);

    // Dead-space penalty: post_residual too small for any future item (min size 1,
    // but practically below ~10 makes reuse unlikely in 10..80 streams; use 12).
    if post_residual < 12 && post_residual > 0 {
        score += 35.0;
    }

    // Harmonic pairing bonus: if next item fits exactly into post_residual,
    // this is a perfect harmonic complement (post_residual == next_item_size).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial harmonic: next item fits with small leftover.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover_after_next = post_residual - next_item_size;
        if leftover_after_next < 12 {
            score -= 25.0;
        } else {
            score -= 10.0 * (1.0 - leftover_after_next as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize proportionally to wasted complement.
        let mismatch = (post_residual as f64 - next_item_size as f64).abs();
        score += 0.15 * mismatch;
    }

    // Modulo arithmetic on post_residual: residues near capacity/2 are versatile
    // (can host mid-class items); residues near 0 or tiny are dead ends.
    let half = bin_capacity / 2;
    let dist_to_half = (post_residual as i32 - half as i32).abs();
    score += 0.05 * dist_to_half as f64;

    // Class-coupling: reward bins whose post_residual lands exactly on a class
    // boundary (multiple of 13), since future items quantize to these bands.
    if post_residual % 13 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placement is bad.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if no open bin gives a tight fit and item is large, new bin is fine.
        if post_residual <= 20 && fitting_bins_count == 0 {
            score -= 70.0;
        }
        // Late in the stream, opening fresh bins is riskier (residuals strand).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Spread control: prefer bins whose residual is near the mean (keeps many
    // bins usable), unless a very tight fit is available.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Prefer reusing crowded bins when many are open (bin consolidation).
    score -= 0.5 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Large items (top class) should go into the emptiest bins.
    if item_class >= 5 {
        score += 0.3 * (bin_capacity as f64 - bin_residual as f64);
    }

    // Small items (lowest class) fill gaps: reward small post_residual extra.
    if item_class == 0 {
        score -= 0.4 * (bin_capacity as f64 - post_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A residual gap is "dead" if it's smaller than the smallest plausible item (1..100 range),
    // but small gaps (1..=10) are especially wasteful.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual > 10 && post_residual <= 25 {
        score += 25.0;
    }

    // Perfect fit bonus: strongly reward filling a bin exactly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Penalize leaving a gap the next item just barely misses.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 15.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 20.0 + 5.0 * open_bins_count as f64;
    } else {
        score -= 3.0 * open_bins_count as f64;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Prefer bins tighter than the current mean residual (good fits).
    score += 0.5 * ((bin_residual as f64) - mean_residual);

    // Slight late-stream tightening: as stream progresses, be greedier about fills.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact / near-exact fits (low post residual)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect chain
        } else if next_item_size <= post_residual {
            // reward proportional to how much next item consumes of the leftover
            let consume_ratio = next_item_size as f64 / post_residual as f64;
            score -= 150.0 * consume_ratio;
        } else {
            // next item cannot use the leftover: penalize large dead space
            let waste = next_item_size - post_residual;
            score += (waste as f64) * 0.8;
        }
    }

    // Penalize creating dead space relative to mean residual of open bins
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Prefer denser bins (small residual before placement)
    score += (bin_residual as f64) * 0.05;

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let open_pressure = if open_bins_count > 0 { mean_residual } else { 0.0 };
        if open_pressure < item_size as f64 * 0.5 {
            score -= 80.0; // open bins are too full, new bin is fine
        } else {
            score += 150.0; // discourage opening when open bins have room
        }
    }

    // Slight early-stream bias toward filling bins greedily
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: squared penalty on wasted space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.25 * next_item_size as f64;
        } else {
            // Dead space for the known future item.
            score += 0.10 * (next_item_size as f64 - post_residual as f64).min(40.0);
        }
        // Perfect chain: next item exactly fills the bin afterwards.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when the item is large
    // (would leave little residue anyway) or no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 40.0;
        // Early stream: opening fresh bins is cheap; late stream: prefer filling.
        score -= large_item_bonus * (0.4 + 0.6 * (1.0 - progress));
        // Penalize opening bins when many are already open with slack.
        score += 0.8 * open_bins_count as f64;
        // If mean residual is high, existing bins have room; discourage new bin.
        score += 0.3 * mean_residual;
        // Small items into a fresh bin waste capacity.
        if item_size < 40 {
            score += 35.0;
        }
    } else {
        // Prefer bins that are already fairly full (small residual before placement).
        score += 0.15 * (bin_residual as f64 - mean_residual);
        // Reward using bins with many alternatives less (keep flexible bins open).
        if fitting_bins_count > 2 {
            score += 3.0;
        }
    }

    // Late-stream urgency: squeeze items into existing bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (post_residual == 0) as i32 as f64;

    // Exact fill is always ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Penalize dead space more as stream advances
    score += 20.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post residual) with a smooth quadratic bonus
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Last-chance bin: smooth exponential reward
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 10.0 * (1.0 - ((pr - nxt) / cap).abs()) * (1.0 - progress * 0.3);
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Mean residual coupling: prefer bins deviating below mean (compact bins)
    score += 5.0 * ((pr - mean_residual) / cap);

    // Slight penalty for spreading across too many bins early
    score += 2.0 * open_bins_count as f64 * progress / total_items.max(1) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 create "usable band" logic.
    let r = post_residual % 10;
    let q = post_residual / 10;

    // Dead-space penalty: residual < 10 is nearly unusable (min item size ~ small).
    // Scale penalty by which harmonic band the residual falls into.
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else if post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 2.0; // dead space
    } else {
        // Harmonic band reward: prefer residuals in friendly classes (multiples of 10/5).
        match r {
            0 => score -= 12.0,
            5 => score -= 6.0,
            _ => score += (r as f64) * 0.4,
        }
        // Mild decay: large residuals are less valuable to preserve.
        score += q as f64 * 0.3;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a neutral-ish baseline,
    // penalized when a decent fit exists, encouraged when fit is poor.
    if bin_residual == bin_capacity {
        score += 20.0;
        if post_residual as f64 > mean_residual {
            score += 10.0; // item is small relative to typical leftovers -> reuse bins
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Lookahead coupling: if next item can exactly fill this bin's post_residual,
    // reward heavily (perfect harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let npr = post_residual - next_item_size;
            if npr % 10 == 0 || npr < 10 {
                score -= 8.0;
            }
        } else {
            // next item won't fit here: slight penalty proportional to wasted lookahead
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Late in stream: consolidation pressure — prefer filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;
    score += (open_bins_count as f64) * 0.15;

    // Tie-break toward residuals close to mean (balance the pool).
    score += (post_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    }

    // Reward tight fits (post_residual very small but not zero).
    if post_residual <= 3 {
        score -= 25.0;
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bins pressure: with many open bins, prefer reusing existing space
    // and penalize opening yet another bin.
    let bin_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when few bins are open
        // or current bin would leave a large dead gap anyway.
        score += 30.0 + 4.0 * bin_pressure;
        if post_residual >= bin_capacity as f64 {
            score -= 0.0; // trivially the empty case
        }
        // If the item barely fits nowhere else, opening a new bin is fine.
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 20.0;
        }
    } else {
        // Existing bin reuse: reward when many bins are open (consolidation).
        score -= 0.5 * bin_pressure;
        // Last-chance bin: strongly prefer filling it rather than opening a new one.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
        // Prefer bins whose residual is above the mean (absorb slack into roomier bins).
        if (bin_residual as f64) > mean_residual {
            score -= 5.0;
        }
        // Lookahead: avoid consuming space the next item needs exactly.
        if next_item_size > 0 && post_residual as f64 > 0.0 && (next_item_size as f64) > post_residual as f64 && (next_item_size as f64) <= bin_residual as f64 {
            score += 15.0;
        }
        if next_item_size > 0 && (next_item_size as u32) == post_residual {
            score -= 30.0; // next item will perfectly fill this bin
        }
    }

    // Mild progression term: later in the stream, tighten packing discipline.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward near-perfect fills
    if post_residual == 0 {
        score -= 1000.0; // perfect fit, bin closed
    } else {
        // Dead-space penalty grows super-linearly for tiny residuals
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 60.0 - 5.0 * pr; // small gaps are wasted space
        }

        // 2-step lookahead: exact match with next item is gold
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if (pr - nxt).abs() < 0.5 {
                score -= 500.0; // next item fills this bin exactly
            } else if nxt <= pr {
                // next item fits: reward proportional to how tightly
                score -= 0.5 * (pr - nxt);
                if pr - nxt < 10.0 {
                    score -= 80.0; // both items nearly fill the bin
                }
            } else {
                // next item won't fit here: penalize leaving a gap next item can't use
                score += 0.3 * (nxt - pr).min(40.0);
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when item is huge
    // relative to residual and open bins are tight.
    if bin_residual == bin_capacity {
        let tight = (mean_residual / bin_capacity as f64).max(0.0);
        let big_item = item_size as f64 / bin_capacity as f64;
        // Penalize new bins generally; relax when item is large and mean residual small
        score += 200.0 - 180.0 * big_item * (1.0 - tight);
        if fitting_bins_count == 0 {
            score -= 400.0; // no alternative: new bin mandatory
        }
    } else {
        // Prefer fuller bins relative to mean residual
        score += 0.4 * (mean_residual - bin_residual as f64).max(-50.0);
    }

    // Early in stream: slightly favor consolidation; late: favor closing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: relative waste after placement.
    let waste_frac = post_residual as f64 / cap;
    score += 6.0 * waste_frac * waste_frac * cap;

    // Penalize bins that become nearly full in an awkward way
    // (tiny post residual that can never fit the smallest item ~1).
    if post_residual > 0 && post_residual < 5 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward; if next item would be stranded by this placement, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let slack_after_next = post_residual as f64 - nxt;
            score -= 4.0 * (1.0 - slack_after_next / cap);
        } else if (post_residual as f64) < nxt && post_residual > 0 {
            score += 3.0 * (1.0 - post_residual as f64 / nxt);
        }
    }

    // Global pressure: many open bins with high mean residual -> prefer
    // filling existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * mean_residual / (cap * (open_bins_count as f64 + 1.0));
    if bin_residual != bin_capacity {
        score -= 5.0 * pressure * (0.5 + 0.5 * progress);
    } else {
        // New-bin candidate: penalize proportional to existing slack so a
        // new bin only wins when open bins are nearly exhausted.
        score += 4.0 * pressure + 2.0 * mean_residual / cap;
    }

    // Mild preference for bins whose residual is close to item size (perfect packing).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 3.0 * tightness * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Smooth polynomial coupling: penalize large residuals more as stream progresses
    let poly = pr_norm * pr_norm * (0.5 + 2.0 * progress) + pr_norm * (1.0 - progress);
    score += 20.0 * poly;

    // Reward tight fits (small post_residual) with a smooth non-linear bonus
    let tight = (-pr_norm * 6.0).exp();
    score -= 15.0 * tight * (1.0 + progress);

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 10.0 * (1.0 - slack) * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 5.0 * progress;
    }

    // Last-chance bin: strong smooth bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + 0.5 * (1.0 - progress));
    }

    // Penalize scattering across many open bins relative to mean residual
    if open_bins_count > 0 {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 3.0 * dev * dev * (1.0 - progress);
    }

    // Mild penalty for opening a brand-new empty bin unless stream is early
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: reward post_residual values that are "good" residue classes.
    // Small post-residuals are best; exact classes divisible by small item sizes
    // (e.g. multiples of 10/20) remain reusable, penalize awkward odd gaps.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr % 10 == 0 {
        score -= 12.0; // clean class, still reusable by common sizes
        if pr <= 20 { score -= 10.0; } // tight but reusable class
    } else if pr % 5 == 0 {
        score -= 4.0;
    } else if pr < 10 {
        score += 25.0; // dead space below minimum item size
    } else {
        // odd gaps: penalize more the further from a multiple of 10
        let off = (pr % 10).min(10 - (pr % 10)) as f64;
        score += off * 1.5;
    }

    // Lookahead: exact match with next item is a jackpot.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0;
        } else if next_item_size <= pr && pr - next_item_size < 10 {
            score -= 20.0; // next item nearly fills the remainder
        } else if next_item_size > pr {
            score += 8.0; // remainder too small for lookahead, less attractive
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are tight.
    if bin_residual == bin_capacity {
        score += 45.0;
        // allow new bin late in stream when mean residual is small
        if mean_residual < 15.0 { score -= 30.0; }
    }

    // Slight preference for bins already below mean residual (tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Late-stream urgency: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps (< 10)
    if post_residual < 10 && post_residual > 0 {
        score += 50.0;
    }

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Dead-space penalty: quadratic in small residuals
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 20.0 {
            score += (20.0 - pr) * (20.0 - pr) * 0.3;
        }
    }

    // Open bins pressure: when many bins are open, prefer filling existing ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * 0.5 * (0.5 + progress);
    if bin_residual != bin_capacity {
        score -= pressure;
    } else {
        // New-bin candidate: penalize opening a new bin unless residuals are tight
        score += 10.0 + mean_residual * 0.2 + pressure * 0.3;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to lookahead
        score += 6.0;
    }

    // Prefer bins with residual close to mean (balanced packing)
    if bin_residual != bin_capacity {
        score += (bin_residual as f64 - mean_residual).abs() * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward bins whose post-residual exactly matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item can also fit here: reward tight two-item chains.
            score -= (30.0 - diff.min(30.0)) * 1.5;
        } else {
            // Dead space relative to next item: penalize.
            score += diff * 0.4;
        }
    }

    // Prefer bins tighter than average (best-fit flavor).
    let tightness = mean_residual - bin_residual as f64;
    score += tightness * 0.3;

    // Penalize leaving tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: keep it competitive only when current fit is bad.
    if bin_residual == bin_capacity {
        let fit_waste = post_residual as f64;
        score += 15.0 + fit_waste * 0.2;
    }

    // Late in stream: consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward placements that leave room for the lookahead item (chained fits).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Penalize dead space that the next item cannot use.
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a bin unless it's genuinely better.
    if bin_residual == bin_capacity {
        let new_bin_penalty = if fitting_bins_count == 0 {
            -100.0 // no alternative, must open
        } else if fitting_bins_count == 1 {
            25.0 // don't skip the last-chance bin
        } else {
            // Only attractive if open bins would leave lots of dead space.
            (mean_residual - post_residual as f64).max(0.0) * 0.5 + 10.0
        };
        score += new_bin_penalty;
    }

    // Mild preference for tight fits relative to the mean residual state.
    score += 0.1 * (mean_residual - post_residual as f64);

    // Time horizon: later in the stream, consolidate more aggressively
    // (avoid leaving many half-empty bins at the end).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * post_residual as f64 * 0.15;

    // Slight preference for bins already below mean residual (balancing).
    score -= 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling: quadratic dead-space penalty amplified by stream progress
    let dead = norm_pr * norm_pr;
    score += 12.0 * dead * (0.4 + 0.6 * progress) * cap * 0.1;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + 0.5 * progress);

    // Lookahead: penalize residual that cannot fit the next item (creates stranded space)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            // usable for next item: mild reward proportional to how snugly next item fits
            score -= 3.0 * (1.0 - (pr - nxt) / cap);
        } else {
            // next item cannot use this residual: penalty grows with waste fraction
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Crowding: many open bins -> prefer consolidating (penalize new-bin tendency)
    let crowding = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * crowding * norm_pr;

    // Mean residual coupling: placing into a bin far below mean residual wastes consolidation
    score += 1.5 * ((mean_residual - pr) / cap).abs();

    // New-bin candidate: penalize opening a fresh bin unless item is large relative to capacity
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / cap;
        score += 20.0 * (1.0 - large_item) * (1.0 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls in "useful" classes
    // (multiples of common small sizes 10/20/25/50) are rewarded.
    let pr = post_residual;
    let mut harmony = 0.0;
    if pr == 0 {
        harmony = 30.0; // perfect fill
    } else if pr % 50 == 0 {
        harmony = 22.0;
    } else if pr % 25 == 0 {
        harmony = 14.0;
    } else if pr % 20 == 0 {
        harmony = 12.0;
    } else if pr % 10 == 0 {
        harmony = 8.0;
    } else if pr % 5 == 0 {
        harmony = 3.0;
    }
    score -= harmony;

    // Dead-space penalty: residuals that are "awkward" (prime-ish / odd small leftovers)
    if pr > 0 && pr < 10 {
        score += 18.0;
    } else if pr > 0 && pr % 2 == 1 && pr < 20 {
        score += 6.0;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 12.0;
            // exact class match: next item exactly fills leftover
            if next_item_size == pr {
                score -= 20.0;
            } else if pr % next_item_size == 0 {
                score -= 6.0;
            }
        } else {
            score += 4.0; // next item won't fit here; slight penalty
        }
    } else {
        // last item: prefer tightest fit strongly
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive early or when all fits are terrible
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight_fit = (item_size as f64 / bin_capacity as f64) > 0.85;
        if !tight_fit && fitting_bins_count > 0 && progress < 0.9 {
            score += 40.0; // discourage wasting a fresh bin
        } else {
            score -= 5.0;
        }
    }

    // Prefer bins below mean residual (denser bins) mildly
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Small tie-break against too many open bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Reward near-perfect fills (post_residual <= 9 handled above; reward <= 15 mildly).
    if post_residual > 9 && post_residual <= 15 {
        score -= 8.0;
    }

    // Reward exact fit.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Prefer tightest bin: penalize bins with residual much larger than item.
    let slack = (bin_residual as f64 - item_size as f64).max(0.0);
    score += 0.15 * slack;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, avoid spreading; when few, mild.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening a new bin unless current placement is bad.
        score += 30.0 + 2.0 * open_bins_count as f64;
        // If the next item would fit in the fresh residual, slightly favor opening.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
        // Early stream: new bins are cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    } else {
        // If next item fits this bin's post-residual, reward (lookahead pairing).
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size > post_residual {
            score += 5.0;
        }
    }

    // Mild preference for bins below mean residual (tighter bins first).
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strong bonus when the item exactly fills the bin.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 400.0; // chained perfect fit
        } else if next_item_size <= post_residual {
            let tightness = next_item_size as f64 / post_residual as f64;
            score -= 150.0 * tightness; // prefer bins where next item fills most of leftover
        } else {
            // Next item cannot fit: post residual risks becoming dead space.
            let waste = (post_residual as f64) / bin_capacity as f64;
            score += 80.0 * waste;
        }
    }

    // Relative-to-mean residual coupling: bins with unusually small residual
    // are more "committed"; placing here keeps other flexible bins open.
    let rel = post_residual as f64 - mean_residual;
    score += 0.6 * rel;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize new-bin opening when existing bins could host the item well.
    if bin_residual == bin_capacity {
        // New bin baseline: its post residual equals capacity - item_size.
        // Make new bins attractive only if few alternatives or item is large.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 60.0 * (1.0 - item_frac) + 40.0 * progress;
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // Small nudge toward tight fits generally (best-fit flavor).
    score += 0.3 * (post_residual as f64 % 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward low post_residual non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Penalize opening a brand-new bin unless the fit in existing bins is bad.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Cost of a new bin: 100 units of residual wasted on average.
        score += 60.0;
        // But if this item leaves a large hole in any existing bin anyway,
        // opening a fresh bin becomes relatively attractive.
        score -= fit_ratio * 30.0;
        // Early in the stream, keep bins open longer (future items unknown).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 15.0;
        // If many bins are open and all are full-ish, a new bin is natural.
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    } else {
        // Reward using an existing bin, more so when it's the last chance.
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
        // Lookahead: if the next item would fit perfectly in the post-residual,
        // strongly favor this bin (chain-friendly placement).
        if next_item_size > 0 {
            let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
            score -= (1.0 - gap / bin_capacity as f64) * 8.0;
            // If next item cannot fit here anyway, mild penalty for hogging space.
            if post_residual < next_item_size {
                score += 3.0;
            }
        }
        // Prefer bins whose residual is below the mean (consolidate emptiness).
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    // Global pressure: when few bins fit the item, prioritize any fitting bin.
    if fitting_bins_count <= 2 && !is_new_bin {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (small post_residual), with quadratic shaping
    let mut score = pr;

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, tolerate slack; later, penalize it super-linearly.
    let progress_coupling = x * x * (1.0 + 2.0 * progress) * cap * 0.5;
    score += progress_coupling;

    // Cubic term: reward near-zero post residual especially late in stream
    score -= (1.0 - x).powi(3) * cap * (0.25 + 0.5 * progress);

    // Lookahead: if next item fits in the post residual, reward this bin smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit_amount = (pr - next_item_size as f64).max(0.0) / cap;
        let synergy = (1.0 - (nx - x).abs()).max(0.0);
        score -= synergy * fit_amount * cap * (0.3 + 0.4 * progress);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 8.0 * progress;
    }

    // Slight bias toward fuller bins relative to mean residual across open bins
    score += 0.15 * (mean_residual - pr);

    // Mild penalty for spreading across many bins early
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (residual 0) heavily rewarded
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Dead-space penalty grows quadratically for small unusable residuals
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 2.5;
        }
        // Modulo-classes of residual vs capacity: residuals that are multiples
        // of common small item sizes are more likely reusable later
        let r = post_residual;
        let reusable = (r % 10 == 0) as i32 + (r % 20 == 0) as i32 + (r % 25 == 0) as i32 + (r % 50 == 0) as i32;
        score -= reusable as f64 * 4.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * frac;
        } else {
            // next item won't fit here; slight penalty for hoarding space
            score += 3.0;
        }
    }

    // Fractional fill of this placement
    let fill = item_size as f64 / cap;
    score -= 20.0 * fill;

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless current residual is very tight
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.3;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Stream progression: later in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (post_residual as f64 / cap);

    // Many open bins: prefer tightening the fullest bins
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // dead zone: gap too small for the smallest plausible item (<=10)
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual <= 20 {
            score += 25.0; // risky gap, likely wasted
        }
    } else {
        // perfect fit: strong reward
        score -= 80.0;
    }

    // Reward tight fits relative to residual (best-fit flavor)
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Lookahead: if the next item fits the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item almost fits but not quite, penalize leaving a near-miss gap
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= next_item_size - 5 {
        score += 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins
    score += 0.8 * open_bins_count as f64;

    // Mean residual coupling: if open bins are already loose, prefer tighter placement here
    if mean_residual > post_residual as f64 {
        score += 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: neutral-ish baseline, slightly penalized so we prefer
    // existing bins unless the fit is terrible; allow opening when item is large
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size >= 70 {
            score -= 15.0; // large items: opening fresh bins is fine
        }
    }

    // Late stream: tighten up, avoid opening bins near the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual is close to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // 2-step lookahead: reward if the next item fits exactly into post_residual,
    // penalize if the leftover is too small to be useful for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // leftover dead space relative to next item
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize bins whose residual deviates from the mean (avoid fragmenting many bins).
    score += 0.25 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bonus: if this is the only bin that fits, use it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Slight preference to fill older/more crowded bins rather than open new ones.
    score += 0.3 * open_bins_count as f64;

    // Empty new-bin candidate: only attractive when the item is large and nothing fits well.
    if bin_residual == bin_capacity {
        score += 5.0 - 4.0 * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale by relative fill achieved.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * fill * 25.0;

    // Penalize post_residual that is small but nonzero (dead space trap):
    // tiny leftover gaps (<10) are nearly unusable since items >= 1 but small.
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 2.0;
    }
    // Perfect closure bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward proportional to how well it uses the gap
            score -= (next_item_size as f64 / post_residual as f64) * 8.0;
        } else {
            // next item won't fit here: penalize leaving a gap that "teases"
            let gap_waste = (next_item_size - post_residual) as f64;
            if post_residual > 0 {
                score += gap_waste * 0.15;
            }
        }
    } else {
        // Last item: strongly prefer closing a bin exactly.
        if post_residual == 0 {
            score -= 60.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + item_size as f64 * 0.1;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer reusing open bins when any fit is decent; make new bin costly
        // but allow it when open bins are all nearly full (mean residual low)
        // or the item is huge.
        let pressure = (mean_residual / bin_capacity as f64).max(0.0);
        score += 30.0 + 20.0 * (1.0 - pressure);
        if item_size >= 60 && mean_residual < item_size as f64 * 0.5 {
            score -= 25.0; // big item, no room anywhere: open new bin
        }
    } else {
        // Reuse reward: prefer bins with less residual (best-fit flavor),
        // already partially accounted by post_residual; add coupling with mean residual:
        // placing into a bin below-mean residual concentrates fullness.
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Time horizon: early in the stream, be conservative with bin count;
    // late in the stream, allow more aggressive closure of bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 6.0;

    // Many open bins: encourage consolidation into fewer bins.
    if open_bins_count > 4 {
        score -= (open_bins_count.min(20) as f64) * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 1.0 + 0.8 * t - 0.5 * t * t + 0.3 * t * t * t;
    score *= poly;

    // Reward tight fits: penalize (subtract) when post_residual is small relative to capacity
    score -= 30.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Penalize dead space relative to mean residual across open bins
    score += 0.4 * (pr - mean_residual).abs();

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward leaving space that still fits the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 12.0 * (1.0 - (nx / cap)) * (1.0 - t);
        } else {
            score += 8.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty for proliferation of open bins
    score += 0.15 * open_bins_count as f64 * (0.5 + t);

    // New-bin candidate: neutral-ish baseline so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 18.0 - 10.0 * (1.0 - pr_norm);
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues that are "usable" by
    // typical item sizes get rewarded; dead-space residues get penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Integer-division threshold classes on post_residual (capacity fractions).
    let quarter = bin_capacity / 4;   // 25
    let half = bin_capacity / 2;      // 50
    let third = bin_capacity / 3;     // 33

    // Reward tight fits: post_residual in low harmonic classes.
    if pr == 0 {
        score -= 30.0; // perfect packing
    } else if pr <= 10 {
        score -= 12.0;
    } else if pr <= quarter {
        score -= 4.0;
    } else if pr <= third {
        score += 2.0;
    } else if pr <= half {
        score += 5.0;
    } else {
        score += 8.0;
    }

    // Modulo arithmetic: residuals that are multiples of common item sizes
    // (10, 20, 25, 50) are re-fillable; odd dead residues are penalized.
    if pr % 10 == 0 {
        score -= 6.0;
    }
    if pr % 20 == 0 {
        score -= 4.0;
    }
    if pr % 25 == 0 {
        score -= 3.0;
    }
    if pr % 50 == 0 {
        score -= 5.0;
    }
    // Odd residues can rarely be filled by even-sized items.
    if pr % 2 == 1 {
        score += 3.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (harmonic chaining).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if pr >= next_item_size {
            let rem2 = pr - next_item_size;
            // Reward if the chain continues cleanly (small remainder).
            if rem2 <= 10 {
                score -= 8.0;
            }
            score -= (rem2 as f64) * 0.05;
        } else {
            // Next item won't fit here; penalize proportionally to wasted potential.
            score += (next_item_size as f64 - prf) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer keeping it closed unless open bins are very full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening a new bin is penalized more early on (long stream ahead),
        // less at the end; but attractive if mean residual is tiny.
        score = 40.0 + 30.0 * (1.0 - progress) - mean_residual * 0.4;
        if post_residual == bin_capacity {
            // fresh bin with nothing placed: keep base high
            score += 10.0;
        }
    }

    // Slight preference for fuller bins (smaller residual) overall.
    score += (bin_residual as f64) * 0.05;

    // Mean-residual coupling: if this bin is much emptier than average,
    // deprioritize it slightly (save emptier bins for larger future items).
    let bin_res_f = bin_residual as f64;
    if bin_res_f > mean_residual {
        score += (bin_res_f - mean_residual) * 0.1;
    } else {
        score -= (mean_residual - bin_res_f) * 0.1;
    }

    // Many open bins: encourage consolidation into emptier ones is already
    // handled; discourage spreading too thin.
    if open_bins_count > 8 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals that are too small for the smallest
    // plausible future item (<= 10) are "unusable" — penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Semi-dead zone: gaps that only fit tiny items are risky.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward exact / near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (chain two placements).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 6.0; // creates dead space after next item
        }
    }

    // Last-chance bin: only one bin can fit this item — avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; penalize new-bin calls implicitly
    // via residual (new bin has high post_residual) plus this term.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Prefer bins whose residual is below the mean residual (fuller bins),
    // encouraging tight packing first.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Early in the stream, be more willing to open bins (mild); late in the
    // stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual,
    // this is a perfect chain placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let leftover = post_residual - next_item_size;
            score -= (30.0 - (leftover as f64)).max(0.0);
            if leftover <= 10 {
                score -= 60.0;
            }
        } else {
            // Next item cannot fit here; penalize leaving a gap that
            // the lookahead item cannot use.
            score += 40.0;
        }
    }

    // Prefer bins tighter than the mean residual (good fits).
    let diff = post_residual as f64 - mean_residual;
    score += 0.5 * diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when the item is large and few bins fit it,
    // or when no open bin gives a tight fit.
    if bin_residual == bin_capacity {
        let tight_open = (bin_residual - item_size) as f64;
        if fitting_bins_count == 0 {
            score -= 300.0; // must open a bin
        } else if item_size >= 50 && tight_open > 20.0 {
            score -= 50.0; // large item, poor fits elsewhere -> fresh bin
        } else {
            score += 250.0; // discourage wasting fresh bins
        }
    }

    // Mild pressure to consolidate as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 500.0;
    }

    // Tightness: reward small post_residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 60.0;

    // Last chance: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Lookahead: penalize if next item could have used this residual better
    if next_item_size > 0 {
        let next_fits_after = next_item_size <= post_residual;
        if next_fits_after {
            score -= 25.0; // chain placement possible, good
        }
        // penalize wasting residual that next item would have fit in this bin
        if next_item_size <= bin_residual && next_item_size > post_residual {
            score += 35.0;
        }
    }

    // Fragmentation penalty: residual too small for typical items
    let min_item = 1u32;
    if post_residual < min_item.max(1) || (post_residual > 0 && post_residual < 10) {
        score += 40.0;
    }

    // Prefer fuller bins when many bins open
    let occupancy = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= occupancy * 50.0;

    // Time horizon: early in stream, be conservative about opening new bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize mildly, more so early on; less late when
        // open bins are crowded (high mean residual usage)
        let crowding = mean_residual / bin_capacity as f64;
        score += 80.0 - progress * 40.0 + crowding * 30.0;
        // if no open bin can fit, this must win
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    } else if fitting_bins_count == 0 {
        // fallback (shouldn't happen for open bins)
        score += 500.0;
    }

    // Global pressure: fewer bins per item -> prefer reusing bins
    score += (open_bins_count as f64).ln().max(0.0) * 5.0;

    // Mean residual coupling: when mean residual is high, avoid dumping into
    // already-loose bins; prefer bins below mean (tighter)
    let bin_residual_f = bin_residual as f64;
    if bin_residual_f < mean_residual {
        score -= 15.0;
    } else {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, small residuals hurt more (dead space compounds).
    let norm_pr = pr / cap;
    score += (norm_pr * norm_pr) * cap * (0.5 + progress);

    // Reward near-perfect fits with a smooth saturating term.
    let tightness = 1.0 - norm_pr;
    score -= (tightness * tightness * tightness) * cap * 0.35;

    // Penalize opening a new bin when open bins could fit, more so late in stream.
    if bin_residual == bin_capacity {
        score += cap * (0.6 - 0.3 * progress);
        // Opening is more acceptable if existing residuals are large and unusable.
        score -= (mean_residual / cap).max(0.0) * cap * 0.25;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * 0.5 * (1.0 - progress);
    }

    // Lookahead: if next item fits into post_residual, reward leaving useful space.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_quality = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= fit_quality * 8.0;
    } else if next_item_size > post_residual {
        // Post-residual too small for next item: smooth penalty proportional to waste.
        score += norm_pr * 5.0 * (0.5 + progress);
    }

    // Mild preference for consolidating into fewer bins.
    score += (open_bins_count as f64).ln().max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" is the leftover space.
    // Residuals that are multiples of common item sizes (or near them) are valuable.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit is always great
    } else {
        let mut bonus = 0.0;
        // Multiples of 10, 20, 25, 50 are classic "harmonic" leftovers
        if pr % 10 == 0 { bonus -= 8.0; }
        if pr % 20 == 0 { bonus -= 6.0; }
        if pr % 25 == 0 { bonus -= 6.0; }
        if pr % 50 == 0 { bonus -= 8.0; }
        // Small dead-space classes are bad
        if pr < 10 { bonus += 25.0; }
        else if pr < 20 { bonus += 10.0; }
        bonus
    };
    score += harmonic_bonus;

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            score -= 12.0 + (pr - next_item_size) as f64 * 0.15;
        } else {
            // next item won't fit here; penalize slightly if we'd strand space
            score += (next_item_size - pr).min(30) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: prefer keeping it closed unless open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        // Open a new bin when existing residuals are small/fragmented or many bins open
        score += 35.0 - fragmentation * 30.0 + open_bins_count as f64 * 1.5;
        // Early in stream, prefer filling existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Mild preference for tighter fits overall (best-fit flavor)
    score += (bin_residual - item_size) as f64 * 0.05;

    // Prefer bins whose residual is below the mean (consolidate emptier space)
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 40.0 * (dead_threshold - post_residual as f64);
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 2.0;

    // Last-chance bin: strongly favor using it rather than opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 15.0;
    }

    // New-bin candidate: keep it competitive only when nothing fits well.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward when next item exactly matches post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (next_item_size as u32) == post_residual {
            // Perfect chain: this bin will be exactly filled by the next item.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item still fits: partial reward scaled by how well it fills.
            let chain_fill = next / post_residual as f64;
            score -= 20.0 * chain_fill * chain_fill;
        } else {
            // Next item won't fit here: penalize leaving a large unusable gap.
            let gap = post_residual as f64;
            if gap < next * 0.5 {
                score += 6.0; // dead space likely
            }
        }
    } else {
        // Last item: strongly prefer minimal post_residual.
        score -= 30.0;
    }

    // Compare against mean residual across open bins.
    score -= 3.0 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are terrible.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if the item is huge relative to typical residuals, a fresh bin is fine.
        if item_size as f64 > mean_residual {
            score -= 18.0;
        }
        if next_item_size > 0 && next_item_size as f64 >= 0.9 * bin_capacity as f64 {
            score -= 10.0; // keep space clean for huge upcoming items
        }
    }

    // Mild pressure to close out bins early in the stream when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * (open_bins_count as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward filling a bin exactly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead chaining: if the next item also fits in the leftover space,
    // reward this bin (it enables a two-item packing chain).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.25 * next_item_size as f64;
        } else {
            // Penalize leftovers that are too small for the known next item
            // (they are likely dead space).
            let waste = (next_item_size as f64 - post_residual as f64).max(0.0);
            score += 0.15 * waste;
        }
    }

    // Last-chance bin: if this is the only open bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Small unusable leftovers (below the minimum item size of 1..10 range)
    // are dead space: penalize.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): it should only win
    // when existing fits are poor. Base penalty plus scaling with item size
    // (larger items benefit more from a fresh bin only if truly needed).
    if bin_residual == bin_capacity {
        score += 30.0 + 0.3 * item_size as f64;
        if fitting_bins_count > 0 {
            // There exists a real fit; make the new bin even less attractive.
            score += 15.0;
        }
        // Late in the stream, opening new bins is more costly (fewer chances
        // to fill them); penalize more as the stream progresses.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * t;
    }

    // Global consolidation pressure: when mean residual across open bins is
    // low (bins are nearly full), prefer packing into existing bins.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * t * (mean_residual / cap);

    // Many open bins: encourage consolidation into existing bins.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let item = item_size as f64;

    // Base: tightness of fit, non-linearly amplified for large dead space.
    let mut score = post + 8.0 * (post / cap).powi(2) * cap;

    // Reward near-perfect fits (post_residual close to 0) more aggressively.
    score -= 12.0 * (-post / 6.0).exp();

    // Last-chance bonus: strong discount when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead coupling: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0 + 4.0 * (1.0 - post / cap);
    } else if next_item_size > 0 {
        // Penalize leaving residual that wastes capacity for the next item.
        score += 3.0 * (post / cap);
    }

    // Penalize opening new bins early; as stream progresses, prefer filling existing bins.
    let is_new_bin = (resid - cap).abs() < 0.5;
    if is_new_bin {
        score += 20.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // But allow a new bin when the item barely fits nothing well.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Mild penalty if this bin's residual deviates far from the mean residual (fragmentation).
    score += 1.5 * ((resid - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: classify post_residual into residue classes mod 10
    let r = post_residual % 10;
    let class_bonus = match r {
        0 => 40.0,        // round residual, highly reusable
        5 => 30.0,        // half-class, common item sizes
        2 | 8 => 15.0,
        1 | 9 => 8.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Integer-division thresholds on post_residual: dead-space bands
    let band = post_residual / 10;
    if band == 0 {
        score += 25.0; // tiny sliver, near-dead space
    } else if band >= 5 {
        score += 10.0; // large residual, plenty of competition
    } else {
        score -= 12.0; // sweet spot 10-49 residual
    }

    // Lookahead coupling: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic match: next item size class compatible
            let m = next_item_size % 10;
            if m == r { score -= 35.0; } else { score -= 15.0; }
        } else {
            // next item won't fit here; penalize proportionally to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.5;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure)
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * 30.0;

    // Mean residual coupling: avoid leaving this bin far from the pack mean
    score += ((post_residual as f64 - mean_residual).abs()) * 0.3;

    // New-bin candidate: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 && next_item_size >= item_size { 1.2 } else { 1.0 };
        score += 90.0 * pressure - (open_bins_count as f64) * 2.0;
        if fitting_bins_count == 0 { score -= 120.0; }
    }

    // Slight early-stream openness to open bins (cheap bins early)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful later
    // are heavily penalized. Define "unusable" as post_residual < 10 (min item)
    // or post_residual smaller than the next item's size.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(10) {
        score += 25.0; // tiny dead gap
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // gap cannot host the lookahead item: penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.6;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // gap can host the next item: reward
        score -= (next_item_size as f64) * 0.3;
    }

    // Perfect or near-perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    } else {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 15.0; // reward tight packing
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // alternatives exist; encourage consolidation.
    if bin_residual < bin_capacity {
        score += (open_bins_count as f64) * 1.5;
    }

    // Mean residual coupling: prefer bins with residual below mean
    // (denser bins first), above-mean bins get a mild penalty.
    let resid_f = bin_residual as f64;
    if resid_f > mean_residual {
        score += (resid_f - mean_residual) * 0.2;
    } else {
        score -= (mean_residual - resid_f) * 0.2;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit
    // (i.e., this call is the empty-bin candidate and fits are scarce).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            score += 20.0; // last-chance bin should win instead
        } else {
            score += 8.0; // plenty of options; keep item in an open bin
        }
    }

    // Late in the stream: consolidate harder to avoid many half-empty bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), scaled
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 2-step lookahead: reward if next item exactly fills post_residual (perfect chain)
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        // Perfect follow-up: next item exactly fills the bin
        if gap == 0.0 {
            score -= 40.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize wasted potential
        score += 8.0 + 0.1 * next_item_size as f64;
    }

    // Compare post_residual against mean residual: leaving near-mean residual keeps flexibility
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 120.0 - 100.0 * pressure - 15.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Slight preference for filling bins more fully as stream progresses
    score -= 0.05 * (bin_capacity - post_residual) as f64 * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, with a convex penalty on wasted space
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    score += 0.35 * (pr * pr) / cap;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 12 {
        score -= 8.0;
    }

    // Dead-space penalty: residual too small for any plausible item (1..100)
    if post_residual >= 1 && post_residual < 10 {
        score += 10.0 * (10.0 - pr);
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }
    // Crowding effect: many competing bins -> tighten preference for tight fits
    if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; slight penalty for hoarding space
            score += 0.05 * ((next_item_size - post_residual) as f64).min(50.0);
        }
    }

    // Global residual state: if mean residual is high, be pickier (prefer tight fits)
    let mean_gap = mean_residual - pr;
    score += 0.15 * mean_gap.max(-20.0);

    // Time horizon: early in the stream, keep bins flexible; late, just pack tightly
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - t) * 0.0; // placeholder coupling
    score += (1.0 - t) * 0.10 * pr;   // early: penalize waste more gently
    score -= t * 0.20 * pr;           // late: reward tight packing more

    // New-bin candidate: only attractive when open bins are fragmented or item is huge
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = (open_bins_count as f64).ln().max(0.0);
        let item_frac = item_size as f64 / cap;
        // New bin good if item is large and open bins have little room on average
        let new_bin_bonus = 12.0 + 40.0 * (1.0 - fragmentation) * item_frac - 6.0 * pressure;
        score += new_bin_bonus;
        // Slightly discourage opening bins early in the stream
        score += (1.0 - t) * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let fill = 1.0 - pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (0.5 + 0.5 * progress) + norm_pr * (1.0 - progress);

    // Base: penalize wasted residual, scaled smoothly by progress
    let mut score = pr * (0.9 + 0.6 * progress * progress);

    // Non-linear interaction: large post_residual early is fine (room for future),
    // late it becomes dead space -> quadratic growth term
    score += 20.0 * poly * (1.0 + fit_ratio);

    // Reward tight fits (small post_residual) with smooth saturation
    score -= 12.0 * (-norm_pr * 8.0).exp() * (1.0 - progress * 0.5);

    // Lookahead coupling: bonus if next item fits the post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = (post_residual - next_item_size) as f64 / cap;
        score -= 15.0 * (1.0 - snug) * (1.0 - progress * 0.3);
    } else if next_item_size > 0 {
        // penalize residuals too small for lookahead item
        score += 6.0 * (1.0 - progress) * norm_pr;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - progress * 0.4);
    }

    // Mild penalty for spreading across many bins when residuals are high
    score += (open_bins_count as f64).sqrt() * mean_residual * 0.05 * (0.3 + 0.7 * progress);

    // New-bin candidate: neutral-ish baseline, penalize opening new bins early,
    // allow it late when residual waste is large
    if bin_residual == bin_capacity {
        score = cap * (0.6 + 0.4 * progress) - 10.0 * progress * mean_residual / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    // Residuals that are "clean" multiples of common item sizes are reusable.
    let pr = post_residual;
    let mut reusability = 0.0;
    for d in [10u32, 20, 25, 50, 100].iter() {
        if d > 0 && pr >= *d && pr % d == 0 {
            reusability += 6.0;
        }
    }
    // Harmonic class via capacity fraction: post_residual near multiples of cap/4, cap/2
    let quarter = cap / 4.0;
    let frac = (pr as f64 / quarter).round() * quarter - pr as f64;
    if frac.abs() < 2.0 { reusability += 4.0; }
    score -= reusability;

    // Penalize tiny dead space (< 10, unusable for min item size 1... keep small penalty)
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            score -= 10.0 + (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here: penalize leaving large residual
            score += (pr as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Perfect fit reward
    if pr == 0 {
        score -= 30.0;
    }

    // Slight bias toward fuller bins relative to mean residual
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Late in stream: consolidate, discourage opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (unusable gaps).
    if post_residual > 0 {
        let dead_threshold = 12.0;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 8.0;
        }
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Tightness ratio: prefer bins where the item fills a large fraction.
    let fill_frac = item_size as f64 / bin_residual as f64;
    score -= fill_frac * 20.0;

    // Pressure from number of open bins: discourage spreading when many bins
    // are already open, unless the fit is excellent.
    let open_pressure = (open_bins_count as f64).powf(0.7);
    score += open_pressure * 0.5 * (1.0 - fill_frac);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mean residual coupling: prefer bins below the mean residual (larger holes
    // get consumed first), penalize dipping into already-small bins.
    if (bin_residual as f64) < mean_residual {
        score += 6.0;
    } else {
        score -= 3.0;
    }

    // Lookahead: if next item could use the post_residual, reward leaving it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin fits well (large open_bins_count pressure or item too big for
    // typical residuals). Penalize default new-bin slightly so tight fits win.
    if bin_residual == bin_capacity {
        let base = 20.0 + open_pressure * 0.3;
        // If item is large relative to typical residual, new bin is fine.
        let large_item_bonus = if item_size as f64 > mean_residual { -15.0 } else { 0.0 };
        score += base + large_item_bonus;
    }

    // Early stream: slightly favor consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits. Normalize waste relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // 2-step lookahead: strongly reward bins where the NEXT item also fits
    // into the post-residual (perfect 2-item chain).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward proportional to how snugly next item fits after this one.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving a residual that is
            // "almost but not quite" big enough (dead space trap).
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 20.0 {
                score += 12.0 * (1.0 - gap / 20.0);
            }
        }
    } else {
        // Last item: just minimize waste.
        score += 10.0 * waste_frac;
    }

    // Relative-to-mean coupling: a bin with residual far below the mean
    // residual is already "tight"; using it now is good (consolidate).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 8.0 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin for a poorly-fitting item.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Mild competition penalty scaled by number of alternatives.
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: make it moderately attractive only when the item
    // is large relative to the current residuals, or stream is early.
    if bin_residual == bin_capacity {
        let early = step_index as f64 / (total_items.max(1) as f64);
        let large_item = item_size as f64 / bin_capacity as f64;
        let tight_world = mean_residual < item_size as f64;
        let bonus = if next_item_size > 0 && next_item_size <= (bin_capacity - item_size) {
            15.0 // fresh bin can host a 2-item chain
        } else if tight_world || large_item > 0.6 || early < 0.15 {
            8.0
        } else {
            -5.0 // discourage opening bins when open ones suffice
        };
        score -= bonus;
    }

    // Small progress-dependent tie-breaker for determinism/stability.
    score += 0.01 * ((step_index % 7) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward placements that leave little usable residue
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize leaving residue that is too small to be useful for typical items
    let dead_zone = (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64);
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - dead_zone);
    }

    // Lookahead coupling: reward if next item fits in post residual (chain packing)
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 10.0 + 0.1 * next_item_size as f64;
        } else {
            score += 6.0;
        }
    } else {
        // Last item: strongly prefer tightest fit
        score -= 8.0 * tightness;
    }

    // Last-chance bin: if this is the only bin that fits, favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless it offers a
    // clear advantage (many open bins with fragmented residuals, or early stream)
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { (mean_residual / bin_capacity as f64) } else { 0.0 };
        // Penalize new bins more when existing bins are roomy (fragmentation low)
        score += 18.0 + 30.0 * (1.0 - fragmentation);
        // Slightly cheaper to open bins early in the stream
        score -= 10.0 * (1.0 - progress);
    } else {
        // Reward using existing bins more when there are many open bins
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Global residual alignment: prefer bins whose residual is close to the mean
    // (balanced packing), scaled by stream progress
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (0.5 + progress);

    // Mild preference for tighter fits as the stream progresses
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let t = t.clamp(0.0, 1.0);

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, prefer filling bins tightly (low post_residual);
    // later, small residuals matter even more (dead space is permanent).
    let progress_weight = 0.5 + 1.5 * t * t;
    score *= progress_weight;

    // Quadratic penalty on tiny residuals (unusable dead space), scaled by progress.
    let dead = (cap - pr) / cap; // fraction of bin filled
    score -= 2.0 * dead * dead * (0.5 + t);

    // Reward near-perfect fits super-linearly.
    if pr < 5.0 {
        score -= 6.0 * (1.0 - pr / 5.0);
    }

    // Penalize bins whose residual is far below the mean (waste-prone), smoothly.
    score += 0.3 * ((pr - mean_residual) / cap).abs();

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 4.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 1.5 + 2.0 * (next_item_size as f64 / pr.max(1.0));
    } else if next_item_size > 0 {
        // next item won't fit here: mild penalty scaled by how much it misses
        score += 0.5 * ((next_item_size as f64 - pr) / cap);
    }

    // Many open bins: slight preference for consolidating into existing bins.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: keep it attractive only when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 3.0 - 2.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Perfect / near-perfect closure bonus.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 5 {
        score -= 80.0;
    }

    // Harmonic class logic: post_residual bucketed by integer division thresholds.
    // Residuals <= 20 are "dead space" (few items in 1..100 fit); penalize.
    let dead_class = post_residual / 20; // 0..=4
    score += match dead_class {
        0 => 40.0,             // 0..19: nearly dead
        1 => 15.0,             // 20..39: poor
        2 => 0.0,              // 40..59: medium
        3 => -10.0,            // 60..79: good
        _ => -20.0,            // 80..99: very usable
    };

    // Lookahead: reward if the next item fits exactly into post_residual (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            let pair_fill = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 30.0 * pair_fill;
        } else {
            // Next item cannot use this residual: mild penalty proportional to overflow gap.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate handling: opening a bin is expensive; make it unattractive
    // unless no decent fit exists (post_residual of new bin = capacity - item_size).
    if bin_residual == bin_capacity {
        score += 120.0;
        // Allow new bin if this item would leave a very usable residual elsewhere anyway? no:
        // allow new bin when item is large and would leave tiny residual in any bin.
        if item_size >= 80 {
            score -= 140.0;
        }
        // Fewer open bins => cheaper to open.
        score -= 3.0 * open_bins_count as f64;
    }

    // Prefer bins with small residuals overall (waste minimization), scaled by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * (mean_residual - post_residual as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Modular class: items congruent to small mod-10 residues pair well with matching residuals.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item are dead weight; penalize them super-linearly.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0; // exact fit, ideal
    } else if post_residual == 0 {
        score -= 200.0; // perfect closure
    } else {
        let r = post_residual as f64;
        // penalize unusable small gaps harder than proportionally
        if r < 10.0 {
            score += (10.0 - r) * 12.0; // dead space penalty
        } else if r < 30.0 {
            score += (30.0 - r) * 2.0; // moderately awkward gap
        }
        // reward gaps that can still host the lookahead item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        } else if next_item_size > 0 && post_residual > 0 {
            score += 6.0; // gap too small for next item
        }
    }

    // Open-bin pressure: discourage spreading across many bins when
    // a decent fit exists; scale with fraction of stream completed.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let tight_fit_exists = fitting_bins_count > 0
            && open_bins_count > 0
            && mean_residual > 0.0
            && (mean_residual - item_size as f64) < 15.0;
        if tight_fit_exists {
            score += 120.0; // keep using open bins with tight fits
        } else {
            score += 20.0 * open_bins_count as f64; // still mild pressure to consolidate
        }
    } else {
        // Reward using tighter existing bins (smaller residual before placement)
        score += (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Slight preference for bins below mean residual (consolidate emptier space)
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: if the NEXT item fits exactly into post_residual,
    // this placement is a chain win.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let chain_residual = post_residual - next_item_size;
            // Reward chains that leave small leftovers.
            score -= 30.0 * (1.0 - chain_residual as f64 / bin_capacity as f64);
            if chain_residual <= 10 {
                score -= 60.0;
            }
        } else {
            // Next item cannot follow here: penalize proportionally to the
            // wasted lookahead opportunity, scaled by stream progress.
            let progress = step_index as f64 / total_items.max(1) as f64;
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.5 * overshoot * (0.5 + 0.5 * progress);
        }
    } else {
        // Last item: strongly prefer zero residual.
        score -= 150.0;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving a residual well below the mean wastes less shared space.
    let mr = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    score -= 0.3 * (post_residual as f64 - mr);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize new-bin usage when many open bins already exist and the fit is loose.
    if bin_residual == bin_capacity {
        // New bin candidate: baseline cost of opening a bin.
        score += 250.0;
        // But if no open bin fits well (post_residual large relative to capacity),
        // opening a fresh bin is attractive.
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        if fit_quality > 0.5 {
            score -= 300.0 * (fit_quality - 0.5);
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 100.0 * (1.0 - progress);
        // If the next item is large, a fresh bin gives flexibility.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 40.0;
        }
    }

    // Mild penalty for leaving awkward mid-range residuals.
    if post_residual > 10 && post_residual < 30 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual closely matches the item.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 18.0 * (1.0 - tightness).powi(3);

    // Penalize leaving dead space that is too small for typical future items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        score += 6.0 * (1.0 - dead / bin_capacity as f64).powi(2);
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post-residual too small for next item: mild penalty for stranding space.
        score += 4.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // When many bins are open, prefer filling existing ones over opening new.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (open_bins_count as f64).ln() * 2.0;
    score -= progress * 5.0;

    // Global mean residual: if this bin is far below mean residual (fuller bin), favor it.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: make it moderately attractive only when no good fits exist.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (bin_capacity - item_size) < 10
            || (next_item_size > 0 && post_residual < next_item_size && post_residual < 10);
        if poor_fit {
            score -= 20.0;
        } else {
            score += 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post residual (tight fit), non-linearly
    let mut score = pr_norm * pr_norm * 100.0 + pr;

    // Reward near-perfect fits more aggressively
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * tightness * 40.0;

    // Stream progress coupling: late in stream, penalize residual waste harder
    let prog_coupling = progress * progress;
    score += pr_norm * prog_coupling * 60.0;

    // Lookahead: if next item fits into post_residual, reward this placement strongly
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack_after_next = pr - next_item_size as f64;
        score -= (1.0 - slack_after_next / cap) * 30.0 * (1.0 + progress);
    } else if next_item_size > 0 {
        // next item won't fit: penalize leaving a mid-sized residual that wastes space
        score += (1.0 - pr_norm) * 10.0 * prog_coupling;
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Penalize opening new bins when many bins already open and mean residual is high
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.5 + open_bins_count as f64 * 2.0 * (1.0 - progress);
    } else {
        // Slight reward for using bins whose residual is below mean (consolidating)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a superlinear penalty on waste
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Harmonic class of post_residual: dead space in (0..10) is nearly useless
    let small_tail = post_residual % 10;
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if small_tail > 0 && small_tail <= 3 {
        score += 8.0; // awkward remainder class
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 15.0 - 0.3 * slack as f64;
        } else {
            // next item won't fit here; mildly penalize leaving large gaps
            score += 0.15 * (next_item_size as f64 - post_residual as f64).min(40.0);
        }
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0 + 1.0);
        score = 55.0 + 30.0 * waste_frac + 20.0 * (1.0 - progress);
        if mean_residual < item_size as f64 * 1.2 {
            score -= 30.0; // open bins are tight, fresh bin is good
        }
        if fitting_bins_count == 1 {
            score += 45.0; // don't abandon the only fitting bin
        }
        let _ = crowded;
    }

    // Mild preference for bins below mean residual (consolidate emptier bins)
    if !is_new_bin {
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold any item (1..100)
    // are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another
    // (the new-bin candidate has residual == capacity, so this mainly shapes
    // competition among open bins vs. the fresh bin).
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 5.0 * (open_bins_count as f64).sqrt();
        // Opening a new bin is fine when nothing fits well anywhere; but if
        // other bins fit, bias slightly against it unless this is early stream.
        if fitting_bins_count > 1 {
            score += 10.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    } else {
        // Prefer tighter bins (smaller residual before placement) a bit more
        // than raw post_residual already implies.
        score += (bin_residual as f64 - item_size as f64) * 0.05;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item is big and post residual is a near-useless sliver, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 15 {
        score += 12.0;
    }

    // Mean residual coupling: when average slack across open bins is high,
    // avoid adding to the pile of half-empty bins.
    score += 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for exact/near-exact 2-step matches: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect 2-step match: big reward
        if diff == 0.0 {
            score -= 40.0;
        } else if diff <= 5.0 {
            score -= 25.0 - diff * 3.0;
        } else {
            // Penalize residual that neither fits next item nor is small
            score += diff * 0.15;
        }
        // If next item fits into the post residual, extra reward
        if next_item_size <= post_residual {
            score -= 8.0;
        }
    } else {
        // Last item: just minimize waste
        score += post_residual as f64 * 0.5;
    }

    // Relative-to-mean coupling: bins with residual near mean are "typical"; prefer filling below-mean bins
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Tight fit reward: small post_residual relative to item size
    if post_residual <= 5 {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is terrible
    if bin_residual == bin_capacity {
        score += 20.0;
        // Allow new bin if no good fit exists (fitting bins are loose)
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Late in stream: consolidate, prefer filling existing bins
    let progress = step_index as f64 / total_items as f64;
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in stream, guarded against division by zero.
    let progress = if total_items > 1 { step_index as f64 / (total_items - 1) as f64 } else { 0.0 };

    // Core best-fit bias: strongly reward tight fits, nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Perfect-fill bonus: zero waste is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize small-but-nonzero dead space that likely can't fit future items
        // (items >= 1, so any residual is technically usable; weight lightly).
        let dead = post_residual as f64;
        score += (dead / 10.0).powi(2) * 0.8;
    }

    // Lookahead: if the next item fits exactly in the post-residual, this is a
    // great chain placement; if post-residual can't hold the next item, the
    // leftover is more likely to become waste.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post_residual as f64 {
            let chain_tightness = next / post_residual as f64;
            score -= 12.0 * chain_tightness;
        } else {
            score += 4.0 * (1.0 - progress); // waste matters more early on
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): it's only attractive
    // when existing bins fit poorly. Penalize it so open bins with decent fits
    // win; relax the penalty when many bins are open (bin consolidation is
    // less critical) or late in the stream.
    if bin_residual == bin_capacity {
        let base_penalty = 55.0;
        let open_relief = (open_bins_count as f64).ln().max(0.0) * 4.0;
        let time_relief = 10.0 * progress;
        score += base_penalty - open_relief - time_relief;
        // If the item is large relative to capacity, a fresh bin is more natural.
        score -= 15.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Global state coupling: prefer placing into bins whose residual is already
    // below the mean (shrinking the spread of residuals), which reduces
    // fragmentation across the bin pool.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 3.0 * (mean_residual - res) / bin_capacity as f64;
    } else {
        score += 2.0 * (res - mean_residual) / bin_capacity as f64;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 1.5 * open_bins_count as f64 / (open_bins_count as f64 + 5.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: quadratic waste penalty (strongly favors tight fits)
    let mut score = (pr * pr) / cap;

    // Smooth cubic coupling of post-residual with stream progress:
    // later in the stream, waste becomes more costly.
    score += 0.5 * (pr / cap).powf(3.0) * (1.0 + progress);

    // Reward filling a bin almost completely (superlinear bonus near zero residual)
    score -= 12.0 * (1.0 - pr / cap).powf(4.0);

    // Lookahead: if next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - slack).powf(3.0);
        } else {
            // next item won't fit here; slight penalty proportional to overshoot
            score += 2.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bin: strongly favor using it rather than leaving it stranded.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 8.0 + 4.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    // or the stream is late and bins should be consolidated.
    if is_new_bin {
        score += 10.0 + 6.0 * progress + 0.5 * open_bins_count as f64;
        // But if this item would leave large dead space everywhere, opening
        // a fresh bin becomes attractive: soften the penalty via mean residual.
        let tight_elsewhere = (mean_residual - item_size as f64).abs() / cap;
        score -= 5.0 * (1.0 - tight_elsewhere.min(1.0)).powf(2.0);
    }

    // Mild preference for bins with residuals near the item (best-fit flavor)
    score += 0.3 * ((bin_residual as f64 - item_size as f64) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls in "nice"
    // residue classes (multiples of 10/25) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fit, gold
    } else if pr % 25 == 0 {
        score -= 12.0;
    } else if pr % 10 == 0 {
        score -= 6.0;
    } else if pr < 10 {
        score += 8.0; // dead space sliver
    }

    // Integer-division threshold: leftover bucket k = pr / 10.
    // Prefer leftovers that could host common small items next.
    let bucket = (pr / 10) as f64;
    score -= 0.8 * bucket;

    // Lookahead coupling: if next item fits into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        let tightness = 1.0 - (pr - next_item_size) as f64 / cap;
        score -= 14.0 + 10.0 * tightness;
        // harmonic bonus if the pair leaves a clean residue class
        if (pr - next_item_size) % 10 == 0 {
            score -= 5.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        score += 4.0; // this bin will be stranded for the next item
    }

    // Last-chance bin: strongly favor using it before opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin mildly, more so when
    // many bins are open and mean residual is still large.
    if bin_residual == bin_capacity {
        score += 10.0 + 1.5 * mean_residual * (open_bins_count as f64).sqrt();
        if next_item_size > 0 && next_item_size >= item_size {
            score += 3.0; // fresh bin still fine for lookahead anyway
        }
    }

    // Stream progression: early on, be pickier about waste (dead space).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.15;

    // Fractional capacity fill reward: closer to full is better.
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= 6.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (<= 12) are dead space -> heavy penalty.
    if post_residual < 12 {
        score += 60.0;
    } else if post_residual < 25 {
        // "awkward gap" zone: nonlinear penalty peaking around tiny gaps
        score += 25.0 * (1.0 - (post_residual as f64 / 25.0));
    }

    // Reward near-perfect fits (post_residual close to 0 but not dead)
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Tightness reward: fraction of bin filled by this item
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins; penalize the new-bin candidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New bin candidate: penalize more when many bins already open
        score += 20.0 + 8.0 * open_bins_count as f64 + 10.0 * progress;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this placement is excellent; if next item cannot fit, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual {
            score += 8.0;
        } else {
            score -= 5.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (i.e., nearly-full bins) to consolidate waste.
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= 6.0 * (mean_residual - bin_res_f) / bin_capacity as f64;
    } else {
        score += 3.0 * (bin_res_f - mean_residual) / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: the smaller the post_residual, the better (quadratic).
    score -= 2.0 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    // Aggressive 2-step lookahead: reward if next item exactly matches post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let gap = pr - nxt;
            // Perfect match is ideal; penalize gap quadratically.
            score -= 6.0 * (1.0 - gap / bin_capacity as f64);
            // Slight extra reward for near-perfect match.
            if gap == 0.0 { score -= 8.0; }
        } else {
            // Next item can't fit here anyway; penalize leaving a small unusable remainder.
            score += 3.0 * (nxt - pr) / nxt.max(1.0) as f64;
        }
    } else {
        // Last item: prefer filling bins as tightly as possible.
        score -= 10.0 * (1.0 - pr / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize bins far below mean residual (fragmentation risk), unless new bin.
    if bin_residual != bin_capacity {
        score += 0.5 * (mean_residual - post_residual as f64).abs() / bin_capacity as f64;
    }

    // New-bin candidate: prefer it only when post_residual is large (fresh capacity)
    // and few bins fit; otherwise discourage hoarding into fresh bins.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && next_item_size >= item_size {
            score += 4.0; // discourage opening new bin when lookahead is large
        } else {
            score += 1.0;
        }
        if fitting_bins_count == 0 { score -= 5.0; }
    }

    // Late in stream: consolidate aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 3.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small leftover space.
    let pr = post_residual as f64;
    score -= (bin_capacity as f64 - pr) * 0.35;

    // Penalize dead space that is too small to hold typical future items.
    if pr > 0.0 && pr < 12.0 {
        score += (12.0 - pr) * 1.5;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 + (post_residual - next_item_size) as f64 * 0.1;
        } else {
            // Next item won't fit here after placement: mild penalty scaled by waste.
            score += (next_item_size - post_residual) as f64 * 0.08;
        }
    }

    // Last-chance bin: this is the only open bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a bin is costly unless current bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // Base cost of a fresh bin; relax late in the stream or when no bin fits.
        score = 100.0 - fit_pressure * 90.0 - progress * 5.0;
        // Favor opening a new bin when the item fits perfectly (item == capacity slot use).
        if item_size == bin_capacity {
            score -= 95.0;
        }
        // If the item leaves a large residual in a new bin while open bins fit well, discourage.
        score += (mean_residual - post_residual as f64).abs() * 0.2;
    }

    // Global state coupling: many open bins with high mean residual -> prefer filling existing bins.
    if open_bins_count > 4 && bin_residual < bin_capacity {
        score -= mean_residual * 0.15;
    }

    // Prefer bins whose residual is close to item size (best-fit flavor).
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear sharpening
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth coupling: as stream progresses, penalize large residuals more strongly
    let progress_coupling = 1.0 + 3.0 * progress * norm_pr * norm_pr;
    score += pr * progress_coupling * 0.5;

    // Non-linear interaction between post_residual and mean residual across open bins
    let mean_norm = mean_residual / cap;
    score += 8.0 * norm_pr * norm_pr * mean_norm;

    // Reward bins that leave residual matching the lookahead item (smooth Gaussian-like term)
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64) / cap;
        score -= 6.0 * (-4.0 * diff * diff);
    }

    // Last-chance bin bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Penalty for spreading across many open bins late in the stream
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * norm_pr * (1.0 + progress);

    // New-bin candidate: neutral-ish score that only wins when fits are bad
    if bin_residual == bin_capacity {
        score = cap * (1.2 + 1.5 * norm_pr) + 10.0 * progress;
        // Make new bin attractive when existing fits are poor (large post_residual)
        score -= 15.0 * (1.0 - (mean_norm * 0.5).min(1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo small divisors.
    let pr = post_residual;
    let r4 = pr % 4;
    let r10 = pr % 10;
    let r25 = pr % 25;

    // Penalize post residuals that fall into "dead" residue classes
    // (awkward leftovers unlikely to be filled by future items).
    let dead_penalty = match r4 {
        1 => 6.0,
        3 => 3.0,
        _ => 0.0,
    };
    score += dead_penalty;

    // Reward post_residuals in "nice" classes: exact multiples of 10 or 25.
    if r10 == 0 && pr > 0 {
        score -= 4.0;
    }
    if r25 == 0 && pr > 0 {
        score -= 5.0;
    }

    // Integer-division thresholds on post_residual: tiny slivers are dead space.
    if pr > 0 && pr <= 5 {
        score += 8.0;
    } else if pr <= 15 {
        score += 2.0;
    }

    // Perfect-fit reward.
    if pr == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            // harmonic classes of the gap
            let g10 = gap % 10;
            if g10 == 0 {
                score -= 6.0;
            }
            score += (gap as f64) * 0.15;
        } else {
            // next item cannot fit here: mild penalty scaled by overflow class
            score += ((next_item_size - pr) % 20) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: prefer opening fresh bin when current bins are cluttered
    // and mean residual is large relative to item.
    if bin_residual == bin_capacity {
        let mean_frac = mean_residual / bin_capacity as f64;
        if mean_frac > 0.35 && item_size >= 40 {
            score -= 10.0;
        } else {
            score += 5.0;
        }
    }

    // Stream progression: late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.1;

    // Slight pressure against hoarding many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest possible item (1..100 range, min item 1)
    // are "wasted" forever. Penalize small nonzero gaps harshly.
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving gaps that can still host the lookahead item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (post_residual as f64 - next_item_size as f64).min(20.0) * 1.5;
        } else {
            score += 12.0; // creates a gap the next item cannot use
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones over new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 2.0 * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bins are badly fragmented
    if bin_residual == bin_capacity {
        score = 100.0 + mean_residual * 0.5 + open_bins_count as f64 * 1.0;
        if fitting_bins_count == 0 {
            score = 0.0; // no alternative, must open
        }
    }

    // Mild alignment with mean residual: prefer bins near average fullness
    score -= (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this a brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Progress through stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- Core 2-step lookahead coupling ----
    if next_item_size > 0 {
        // Perfect match: post_residual exactly fits the next item -> strong reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement: reward proportionally,
            // stronger when the leftover after the next item is small (tight chain).
            let chain_left = post_residual - next_item_size;
            score -= 25.0 * (1.0 - chain_left as f64 / bin_capacity as f64);
        } else {
            // Next item will NOT fit here: penalize creating stranded residual,
            // unless the residual is so small it is near-useless anyway (dead space ok).
            let gap = (next_item_size - post_residual) as f64;
            if post_residual >= 10 {
                score += 0.8 * gap;
            } else {
                score -= 5.0; // tiny dead space, fine to strand
            }
        }
    } else {
        // Last item: just minimize waste tightly.
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // ---- Relative to mean residual ----
    // Favor bins whose residual is below average (already fragmented, use them up),
    // penalize draining bins that are above average (keep big residual bins flexible).
    let diff = bin_residual as f64 - mean_residual;
    score += 0.15 * diff;

    // ---- Last-chance bin bonus ----
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // ---- New bin candidate handling ----
    if is_new_bin {
        // Opening a new bin wastes (capacity - item) immediately; only attractive
        // when no open bin fits well (fitting_bins_count small) or item is large.
        let waste = (bin_capacity - item_size) as f64;
        score += 30.0 + waste * 0.5;
        if fitting_bins_count <= 1 {
            score -= 40.0; // no good alternative, opening new bin is fine
        }
        // Late in the stream, prefer consolidating into open bins.
        score += 20.0 * progress;
    }

    // ---- Mild tightness reward ----
    score -= 0.3 * (item_size as f64 / bin_capacity as f64) * 10.0;

    // Small tie-breaker against many open bins: prefer fewer bins to stay open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual is barely consumed.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving small unusable slivers (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward leaving residual that can still host typical items.
    if post_residual >= 20 && post_residual <= 50 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty for blocking
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Time horizon: early in the stream, be conservative (prefer filling open bins);
    // late in the stream, avoid opening bins that will be left mostly empty.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Global state coupling: many open bins with large mean residual -> discourage new-bin spread.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins are already slack.
        score += 15.0 + 0.5 * open_bins_count as f64 + 0.3 * mean_residual;
        // But allow a new bin if current item is huge and mean residual is small.
        if item_size > 60 && mean_residual < item_size as f64 {
            score -= 35.0;
        }
    } else {
        // Favor bins below mean residual (denser bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        }
    }

    // Small item into a big residual: mild penalty to avoid wasting capacity.
    if item_size <= 20 && bin_residual >= 80 && bin_residual < bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Smooth non-linear coupling: residual cost grows super-linearly as post_residual shrinks,
    // modulated by stream progress (late in stream, prefer tighter fits even more).
    let tightness = 1.0 - (pr / cap);
    let progress_coupling = 1.0 + progress * tightness * tightness;
    score += 8.0 * tightness * tightness * progress_coupling;

    // Reward bins whose post_residual matches the next item (smooth kernel).
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 6.0 * (-diff * diff / 400.0);
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // Penalize spreading across many open bins mildly; encourage consolidation.
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 2.0;

    // Mean residual deviation: prefer bins near mean residual (balanced usage).
    let dev = (pr - mean_residual).abs();
    score += dev * 0.05 * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin smoothly, more so early in stream.
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: strong best-fit preference
    score *= 1.0;

    // Harmonic class of the post-residual: classify leftover into capacity fractions
    let frac = post_residual as f64 / cap; // 0..1
    let class = (frac * 10.0).floor() as u32; // decile class of leftover

    // Penalize leftover dead space non-linearly; small leftovers are gold
    match class {
        0 => score -= 30.0,           // leftover < 10% : near-perfect fit
        1 => score -= 18.0,
        2 => score -= 10.0,
        3 => score -= 4.0,
        4 => score += 0.0,
        _ => score += (class as f64 - 4.0) * 3.0, // big leftovers penalized
    }

    // Modulo logic: leftovers that are multiples of common small sizes are reusable
    for m in [10u32, 20, 25, 50] {
        if post_residual % m == 0 && post_residual > 0 {
            score -= 6.0;
            break;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 12.0 * (1.0 - gap as f64 / cap);
        } else {
            // next item won't fit here; mild penalty for leaving a stranded gap
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are bad
    if bin_residual == bin_capacity {
        // Neutral baseline; adjust with stream context
        score = cap * 0.85;
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a bin
        } else {
            // discourage opening new bin if decent fits exist
            score += open_bins_count as f64 * 1.5;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // big next item: fresh bin useful
        }
    }

    // Stream progression: later in the stream, prefer tightening existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (1.0 - frac);

    // Coupling with mean residual: bins far below mean residual are attractive targets
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps heavily.
    // If post_residual is nonzero but too small for even the smallest item (1),
    // it's pure waste; if it's small relative to capacity, it's likely dead.
    let dead_threshold = 10.0f64; // items can be as small as 1; small gaps are hard to fill
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Nonlinear penalty on post_residual: small residuals are quadratically bad.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 25.0 {
        score += (25.0 - pr) * (25.0 - pr) * 0.05;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open bins pressure: when many bins are open, favor filling existing ones
    // (penalize opening new bins / spreading items).
    let bin_pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += bin_pressure * 2.5;

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; slight penalty for leaving a gap it could have used
        score += 3.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (fill the fullest bins first, keep large gaps available).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: opening a new bin is only acceptable when no open bin
    // offers a good fit. Penalize new bins progressively with open_bins_count.
    if bin_residual == bin_capacity {
        let base = 55.0 + open_bins_count as f64 * 4.0;
        // If nothing else fits, this penalty is irrelevant (only candidate),
        // but if an open bin fits, it will usually score lower.
        score += base;
        // Late in the stream, allow opening bins more freely (avoid cramming).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fits the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            // next item fits, but leftover after it matters
            let after2 = post_residual - next_item_size;
            score -= 60.0 - (after2 as f64) * 0.5;
        } else {
            // next item cannot use this residual: penalize small dead space
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Penalize leaving residuals below the minimum item size (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Slight preference to keep new-bin option for late stream? mild
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    score
}
